css:
@property --amo-ride-sweep { syntax: "<angle>"; inherits: false; initial-value: 0deg; }
.amo-ride {
  /* re-theme with these four; everything else is mixed from them */
  --amo-ride-paper: oklch(0.985 0.004 85);
  --amo-ride-ink: oklch(0.21 0.012 255);
  --amo-ride-accent: oklch(0.66 0.19 42);
  --amo-ride-land: oklch(0.956 0.012 88);

  --amo-ride-line: color-mix(in oklch, var(--amo-ride-ink) 11%, transparent);
  --amo-ride-line2: color-mix(in oklch, var(--amo-ride-ink) 20%, transparent);
  --amo-ride-hover: color-mix(in oklch, var(--amo-ride-ink) 5%, transparent);
  --amo-ride-mute: color-mix(in oklch, var(--amo-ride-ink) 64%, var(--amo-ride-paper));
  --amo-ride-faint: color-mix(in oklch, var(--amo-ride-ink) 42%, var(--amo-ride-paper));
  --amo-ride-tint: color-mix(in oklch, var(--amo-ride-accent) 13%, var(--amo-ride-paper));
  --amo-ride-on: var(--amo-ride-paper);
  /* map */
  --amo-ride-block: color-mix(in oklch, var(--amo-ride-land), var(--amo-ride-ink) 3.5%);
  --amo-ride-bld: color-mix(in oklch, var(--amo-ride-land), var(--amo-ride-ink) 8%);
  --amo-ride-park: color-mix(in oklab, var(--amo-ride-land), oklch(0.74 0.12 145) 36%);
  --amo-ride-water: color-mix(in oklab, var(--amo-ride-land), oklch(0.7 0.075 236) 55%);
  --amo-ride-street: color-mix(in oklch, var(--amo-ride-land), white 80%);
  --amo-ride-main: color-mix(in oklch, var(--amo-ride-land), oklch(0.93 0.09 88) 70%);
  --amo-ride-case: color-mix(in oklch, var(--amo-ride-land), var(--amo-ride-ink) 13%);
  --amo-ride-ease: cubic-bezier(.2, .8, .2, 1);
  --amo-ride-spring: linear(0, 0.12 5%, 0.42 11%, 0.77 18%, 0.98 25%, 1.06 31%, 1.07 37%, 1.03 46%, 1.004 58%, 0.998 72%, 1);

  position: relative; width: 100%; height: var(--amo-ride-h, 680px); box-sizing: border-box;
  container-type: inline-size; overflow: clip; isolation: isolate;
  display: flex; flex-direction: column; border-radius: 18px;
  background: var(--amo-ride-paper); color: var(--amo-ride-ink); color-scheme: light; accent-color: var(--amo-ride-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  box-shadow: inset 0 0 0 1px var(--amo-ride-line); -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--amo-ride-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled, & [aria-disabled="true"] { cursor: not-allowed; }
  & h2, & h3, & p, & ul, & ol { margin: 0; padding: 0; }
  & ul, & ol { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 5px; font: 600 10px/1 ui-monospace, Menlo, monospace; color: var(--amo-ride-mute); background: var(--amo-ride-paper); box-shadow: inset 0 0 0 1px var(--amo-ride-line2), 0 1px 0 var(--amo-ride-line2); }
  & .amo-ride-num { font-variant-numeric: tabular-nums; }
}

/* ── shell ─────────────────────────────────────────── */
.amo-ride .amo-ride-tabs { display: none; }
.amo-ride .amo-ride-app {
  flex: 1; min-height: 0; display: grid;
  grid-template-columns: clamp(300px, 33cqi, 384px) minmax(0, 1fr);
  grid-template-areas: "panel map";
}
.amo-ride .amo-ride-panel {
  grid-area: panel; position: relative; min-height: 0; display: flex; flex-direction: column;
  border-right: 1px solid var(--amo-ride-line); background: var(--amo-ride-paper); z-index: 2;
}
.amo-ride .amo-ride-top {
  display: flex; align-items: center; justify-content: space-between; padding: 16px 20px 6px;
  & .amo-ride-brand { display: flex; align-items: center; gap: 8px; }
  & .amo-ride-brand svg { width: 26px; height: 26px; stroke-width: 1.6; }
  & .amo-ride-brand b { font-size: 17px; font-weight: 800; letter-spacing: -.035em; }
  & .amo-ride-clock { display: flex; align-items: center; gap: 5px; padding: 4px 9px 4px 7px; border-radius: 99px; background: var(--amo-ride-hover); font-size: 12px; color: var(--amo-ride-mute); }
  & .amo-ride-clock b { color: var(--amo-ride-ink); font-weight: 650; font-variant-numeric: tabular-nums; }
  & .amo-ride-clock svg { width: 14px; height: 14px; }
}
.amo-ride .amo-ride-body {
  flex: 1; min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin;
  padding: 8px 20px 18px; display: flex; flex-direction: column; gap: 14px;
}
.amo-ride .amo-ride-keys {
  display: flex; flex-wrap: wrap; gap: 4px 12px; padding: 10px 20px 12px; border-top: 1px solid var(--amo-ride-line);
  font-size: 11px; color: var(--amo-ride-faint);
  & span { display: inline-flex; align-items: center; gap: 4px; }
  &:empty { display: none; }
}

/* ── where to ─────────────────────────────────────── */
.amo-ride .amo-ride-h {
  font-size: clamp(22px, 2.5cqi, 28px); font-weight: 760; letter-spacing: -.035em; line-height: 1.1; text-wrap: balance;
}
.amo-ride .amo-ride-legs {
  position: relative; display: grid; border-radius: 14px; background: var(--amo-ride-hover);
  box-shadow: inset 0 0 0 1px var(--amo-ride-line);
  &::before { content: ""; position: absolute; left: 21px; top: 30px; bottom: 30px; width: 2px; background: repeating-linear-gradient(var(--amo-ride-faint) 0 3px, transparent 3px 6px); }
}
.amo-ride .amo-ride-leg {
  position: relative; display: grid; grid-template-columns: 20px minmax(0, 1fr) auto; align-items: center; gap: 10px;
  min-height: 54px; padding: 8px 46px 8px 12px; text-align: left; border-radius: 14px;
  transition: background .2s;
  & + .amo-ride-leg { border-top: 1px solid var(--amo-ride-line); border-radius: 0 0 14px 14px; }
  & .dot { justify-self: center; width: 11px; height: 11px; border-radius: 50%; background: var(--amo-ride-ink); box-shadow: 0 0 0 3px var(--amo-ride-paper), 0 0 0 4px var(--amo-ride-line2); }
  & .sq { justify-self: center; width: 11px; height: 11px; border-radius: 2px; background: var(--amo-ride-accent); box-shadow: 0 0 0 3px var(--amo-ride-paper), 0 0 0 4px var(--amo-ride-line2); }
  & small { display: block; font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--amo-ride-faint); }
  & b { display: block; font-weight: 600; font-size: 14px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & input { width: 100%; border: 0; padding: 0; background: none; font-weight: 600; font-size: 14px; outline: none; text-overflow: ellipsis; }
  & input::placeholder { color: var(--amo-ride-faint); font-weight: 500; }
  &:has(input:focus) { background: var(--amo-ride-paper); box-shadow: inset 0 0 0 2px var(--amo-ride-ink); }
  &.edit { background: var(--amo-ride-paper); box-shadow: inset 0 0 0 2px var(--amo-ride-ink); }
}
.amo-ride button.amo-ride-leg:hover { background: color-mix(in oklch, var(--amo-ride-ink) 4%, var(--amo-ride-paper)); }
.amo-ride .amo-ride-clear {
  display: grid; place-items: center; width: 24px; height: 24px; border-radius: 50%; color: var(--amo-ride-mute);
  &:hover { background: var(--amo-ride-line); color: var(--amo-ride-ink); }
  & svg { width: 13px; height: 13px; stroke-width: 2.2; }
}
.amo-ride .amo-ride-swap {
  position: absolute; right: 10px; top: 50%; translate: 0 -50%; z-index: 1;
  display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%;
  background: var(--amo-ride-paper); box-shadow: 0 0 0 1px var(--amo-ride-line2), 0 2px 6px -2px var(--amo-ride-line2);
  transition: rotate .45s var(--amo-ride-spring), background .2s;
  &:hover:not(:disabled) { background: var(--amo-ride-ink); color: var(--amo-ride-on); }
  &.spun { rotate: 180deg; }
  &:disabled { opacity: .45; }
}

/* suggestions */
.amo-ride .amo-ride-sug {
  display: grid; gap: 2px;
  & h3 { font-size: 10.5px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--amo-ride-faint); padding: 2px 0 6px; }
  & [role="option"] {
    display: grid; grid-template-columns: 34px minmax(0, 1fr) auto; align-items: center; gap: 10px; padding: 7px 8px; border-radius: 10px; cursor: pointer;
    animation: amo-ride-in .4s var(--amo-ride-ease) backwards; animation-delay: calc(var(--i, 0) * 32ms);
    transition: background .15s;
    &:hover, &[aria-selected="true"] { background: var(--amo-ride-hover); }
  }
  & .ic { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; background: var(--amo-ride-hover); color: var(--amo-ride-mute); }
  & b { display: block; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { display: block; color: var(--amo-ride-mute); font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & mark { background: none; color: var(--amo-ride-accent); font-weight: 750; }
  & em { font-style: normal; font-size: 11.5px; color: var(--amo-ride-faint); font-variant-numeric: tabular-nums; }
  & .none { padding: 14px 8px; color: var(--amo-ride-mute); text-wrap: pretty; }
}
@keyframes amo-ride-in { from { opacity: 0; translate: 0 6px; } }

/* route summary + options */
.amo-ride .amo-ride-sum {
  display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: -4px;
  & p { display: flex; align-items: baseline; gap: 6px; flex-wrap: wrap; font-size: 12.5px; color: var(--amo-ride-mute); min-width: 0; }
  & b { color: var(--amo-ride-ink); font-weight: 650; font-variant-numeric: tabular-nums; }
  & i { width: 3px; height: 3px; border-radius: 50%; background: var(--amo-ride-faint); align-self: center; }
  & button { flex: none; display: inline-flex; align-items: center; gap: 3px; font-size: 12px; font-weight: 650; color: var(--amo-ride-mute); padding: 3px 4px 3px 8px; border-radius: 99px; }
  & button:hover { color: var(--amo-ride-ink); background: var(--amo-ride-hover); }
  & button svg { width: 13px; height: 13px; transition: rotate .3s var(--amo-ride-ease); }
  & button[aria-expanded="true"] svg { rotate: 180deg; }
}
.amo-ride .amo-ride-opts { display: grid; gap: 6px; }
.amo-ride .amo-ride-opt {
  position: relative; display: grid; grid-template-columns: 58px minmax(0, 1fr) auto; align-items: center; gap: 10px;
  padding: 7px 12px 7px 6px; border-radius: 14px; text-align: left;
  box-shadow: inset 0 0 0 1px var(--amo-ride-line);
  transition: box-shadow .2s, background .2s, scale .35s var(--amo-ride-spring);
  animation: amo-ride-in .45s var(--amo-ride-ease) backwards; animation-delay: calc(var(--i, 0) * 45ms);
  &:hover { background: var(--amo-ride-hover); }
  &:active { scale: .985; }
  &[aria-checked="true"] { box-shadow: inset 0 0 0 2px var(--amo-ride-ink); background: var(--amo-ride-paper); }
  & .car { width: 58px; height: 30px; stroke-width: 1.3; color: var(--amo-ride-ink); }
  & .car .b { fill: color-mix(in oklch, var(--amo-ride-ink) 8%, transparent); }
  &.green .car .b { fill: color-mix(in oklch, oklch(0.7 0.14 150) 30%, transparent); }
  & .nm { display: flex; align-items: baseline; gap: 6px; font-weight: 700; font-size: 14.5px; letter-spacing: -.01em; }
  & .nm span { display: inline-flex; align-items: center; gap: 2px; font-size: 11.5px; font-weight: 600; color: var(--amo-ride-mute); }
  & .nm span svg { width: 12px; height: 12px; }
  & small { display: block; font-size: 12px; color: var(--amo-ride-mute); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .pr { text-align: right; font-weight: 720; font-size: 15px; font-variant-numeric: tabular-nums; letter-spacing: -.01em; }
  & .pr small { font-weight: 500; }
  & kbd { position: absolute; top: 6px; right: 6px; opacity: 0; transition: opacity .2s; }
  &:hover kbd { opacity: 1; }
}
.amo-ride .amo-ride-lines {
  display: grid; gap: 4px; padding: 10px 12px; border-radius: 12px; background: var(--amo-ride-hover); font-size: 12.5px;
  transition: opacity .3s, translate .35s var(--amo-ride-ease);
  @starting-style { opacity: 0; translate: 0 -4px; }
  & div { display: flex; justify-content: space-between; gap: 10px; color: var(--amo-ride-mute); }
  & div span:last-child { font-variant-numeric: tabular-nums; color: var(--amo-ride-ink); }
  & .t { padding-top: 6px; margin-top: 2px; border-top: 1px dashed var(--amo-ride-line2); font-weight: 700; }
  & .t span { color: var(--amo-ride-ink) !important; }
}
.amo-ride .amo-ride-dock {
  position: sticky; bottom: -18px; z-index: 3; display: grid; gap: 8px; margin: auto -20px -18px; padding: 14px 20px 18px;
  background: linear-gradient(color-mix(in oklch, var(--amo-ride-paper) 0%, transparent), var(--amo-ride-paper) 22px);
}
.amo-ride .amo-ride-pay {
  position: relative; display: flex; align-items: center; justify-content: space-between; gap: 10px;
  & > button { display: flex; align-items: center; gap: 8px; padding: 6px 10px 6px 6px; border-radius: 10px; font-weight: 600; transition: background .15s; }
  & > button:hover { background: var(--amo-ride-hover); }
  & .cardi { display: grid; place-items: center; width: 30px; height: 22px; border-radius: 5px; background: var(--amo-ride-ink); color: var(--amo-ride-on); }
  & .cardi svg { width: 14px; height: 14px; }
  & > span { font-size: 12px; color: var(--amo-ride-faint); }
}
.amo-ride .amo-ride-menu {
  position: absolute; left: 0; bottom: calc(100% + 6px); z-index: 5; min-width: 250px; padding: 6px; border-radius: 14px;
  background: var(--amo-ride-paper); box-shadow: 0 0 0 1px var(--amo-ride-line2), 0 18px 40px -12px color-mix(in oklch, var(--amo-ride-ink) 35%, transparent);
  transform-origin: 20% 100%; transition: opacity .2s, scale .3s var(--amo-ride-spring);
  @starting-style { opacity: 0; scale: .94; }
  & [role="menuitemradio"] { display: grid; grid-template-columns: 30px minmax(0, 1fr) 16px; align-items: center; gap: 10px; width: 100%; padding: 8px; border-radius: 9px; text-align: left; }
  & [role="menuitemradio"]:hover:not([aria-disabled="true"]), & [role="menuitemradio"]:focus-visible { background: var(--amo-ride-hover); outline: none; }
  & [aria-disabled="true"] { opacity: .45; }
  & b { display: block; font-weight: 600; }
  & small { display: block; font-size: 11.5px; color: var(--amo-ride-mute); }
  & .ck { color: var(--amo-ride-accent); opacity: 0; }
  & [aria-checked="true"] .ck { opacity: 1; }
}
.amo-ride .amo-ride-cta {
  position: relative; display: flex; align-items: center; justify-content: space-between; gap: 10px; width: 100%;
  padding: 15px 18px; border-radius: 14px; background: var(--amo-ride-ink); color: var(--amo-ride-on);
  font-weight: 700; font-size: 15px; letter-spacing: -.01em; overflow: hidden;
  transition: scale .35s var(--amo-ride-spring), background .2s, opacity .2s;
  & span:last-child { font-variant-numeric: tabular-nums; opacity: .8; font-weight: 600; display: flex; align-items: center; gap: 8px; }
  & kbd { background: transparent; color: inherit; box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--amo-ride-on) 40%, transparent); }
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--amo-ride-ink), var(--amo-ride-accent) 22%); }
  &:active:not(:disabled) { scale: .98; }
  &:disabled { opacity: .35; }
  &.ghost { background: var(--amo-ride-hover); color: var(--amo-ride-ink); justify-content: center; }
  &.ghost:hover:not(:disabled) { background: var(--amo-ride-line); }
}

/* ── live stages ──────────────────────────────────── */
.amo-ride .amo-ride-status {
  display: grid; gap: 4px;
  & .eyebrow { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--amo-ride-accent); }
  & .big { display: flex; align-items: baseline; gap: 8px; }
  & .big b { font-size: clamp(36px, 4.6cqi, 50px); font-weight: 760; letter-spacing: -.05em; line-height: 1; font-variant-numeric: tabular-nums; }
  & .big span { font-size: 15px; font-weight: 600; color: var(--amo-ride-mute); }
  & p { color: var(--amo-ride-mute); text-wrap: pretty; }
}
.amo-ride .amo-ride-prog {
  height: 4px; border-radius: 4px; background: var(--amo-ride-line); overflow: hidden;
  & i { display: block; height: 100%; width: 100%; border-radius: inherit; background: var(--amo-ride-ink); transform-origin: left; scale: var(--p, 0) 1; }
  &.seek i { width: 34%; animation: amo-ride-seek 1.3s cubic-bezier(.6, 0, .3, 1) infinite; scale: 1; }
}
@keyframes amo-ride-seek { from { translate: -110% 0; } to { translate: 310% 0; } }
.amo-ride .amo-ride-radar {
  position: relative; width: 120px; height: 120px; margin: 4px auto 0; border-radius: 50%;
  background: conic-gradient(from var(--amo-ride-sweep), color-mix(in oklch, var(--amo-ride-accent) 40%, transparent), transparent 28%);
  box-shadow: inset 0 0 0 1px var(--amo-ride-line2);
  animation: amo-ride-sweep 1.6s linear infinite;
  &::before, &::after { content: ""; position: absolute; border-radius: 50%; box-shadow: inset 0 0 0 1px var(--amo-ride-line2); }
  &::before { inset: 22px; } &::after { inset: 44px; background: var(--amo-ride-ink); box-shadow: 0 0 0 6px color-mix(in oklch, var(--amo-ride-ink) 14%, transparent); }
}
@keyframes amo-ride-sweep { to { --amo-ride-sweep: 360deg; } }
.amo-ride .amo-ride-driver {
  display: grid; grid-template-columns: 52px minmax(0, 1fr) auto; align-items: center; gap: 12px; padding: 12px; border-radius: 16px;
  box-shadow: inset 0 0 0 1px var(--amo-ride-line);
  animation: amo-ride-in .5s var(--amo-ride-ease) backwards;
  & .av { display: grid; place-items: center; width: 52px; height: 52px; border-radius: 50%; color: var(--amo-ride-on); font-weight: 750; font-size: 16px; letter-spacing: .02em; background: oklch(0.5 0.09 var(--h, 40)); }
  & b { display: block; font-size: 15px; font-weight: 700; }
  & small { display: flex; align-items: center; gap: 4px; color: var(--amo-ride-mute); font-size: 12px; font-variant-numeric: tabular-nums; }
  & small svg { width: 12px; height: 12px; fill: currentColor; stroke: none; color: var(--amo-ride-accent); }
  & .car { font-size: 12px; color: var(--amo-ride-mute); margin-top: 2px; }
  & .plate { padding: 5px 8px; border-radius: 6px; background: oklch(0.93 0.12 95); color: oklch(0.2 0.02 90); font: 800 13px/1 ui-monospace, Menlo, monospace; letter-spacing: .06em; box-shadow: inset 0 0 0 1.5px oklch(0.2 0.02 90 / .7); white-space: nowrap; }
}
.amo-ride .amo-ride-pin {
  display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 10px 12px; border-radius: 12px; background: var(--amo-ride-tint);
  font-size: 12.5px; color: var(--amo-ride-mute);
  & b { display: flex; gap: 4px; }
  & b i { display: grid; place-items: center; width: 24px; height: 28px; border-radius: 6px; background: var(--amo-ride-paper); color: var(--amo-ride-ink); font: 750 15px/1 ui-monospace, Menlo, monospace; font-style: normal; box-shadow: inset 0 0 0 1px var(--amo-ride-line2); }
}
.amo-ride .amo-ride-acts {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px;
  & button { display: grid; justify-items: center; gap: 4px; padding: 10px 4px 8px; border-radius: 12px; font-size: 11.5px; font-weight: 600; color: var(--amo-ride-mute); transition: background .15s, color .15s; }
  & button:hover { background: var(--amo-ride-hover); color: var(--amo-ride-ink); }
  & button svg { width: 19px; height: 19px; color: var(--amo-ride-ink); }
  & button.warn svg, & button.warn { color: oklch(0.55 0.19 28); }
  & button[aria-pressed="true"] { background: var(--amo-ride-tint); color: var(--amo-ride-ink); }
}
.amo-ride .amo-ride-trip {
  display: grid; gap: 0; padding: 4px 0;
  & li { display: grid; grid-template-columns: 20px minmax(0, 1fr) auto; gap: 10px; align-items: center; padding: 6px 0; position: relative; }
  & li + li::before { content: ""; position: absolute; left: 9px; top: -9px; height: 18px; width: 2px; background: var(--amo-ride-line2); }
  & .dot, & .sq { justify-self: center; width: 9px; height: 9px; border-radius: 50%; background: var(--amo-ride-ink); }
  & .sq { border-radius: 2px; background: var(--amo-ride-accent); }
  & span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & em { font-style: normal; font-variant-numeric: tabular-nums; color: var(--amo-ride-mute); font-size: 12px; }
}
.amo-ride .amo-ride-row { display: flex; gap: 8px; & > * { flex: 1; } }
.amo-ride .amo-ride-skip { justify-self: center; display: inline-flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 600; color: var(--amo-ride-faint); padding: 4px 10px; border-radius: 99px; &:hover { color: var(--amo-ride-ink); background: var(--amo-ride-hover); } & svg { width: 13px; height: 13px; } }

/* receipt */
.amo-ride .amo-ride-receipt {
  display: grid; gap: 12px;
  & .amt { font-size: clamp(34px, 4.4cqi, 46px); font-weight: 780; letter-spacing: -.05em; font-variant-numeric: tabular-nums; line-height: 1; }
  & h3 { font-size: 10.5px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--amo-ride-faint); }
}
.amo-ride .amo-ride-stars {
  display: flex; gap: 4px;
  & [role="radio"] { display: grid; place-items: center; width: 38px; height: 38px; border-radius: 10px; color: var(--amo-ride-line2); transition: color .2s, scale .35s var(--amo-ride-spring), background .15s; }
  & [role="radio"]:hover { background: var(--amo-ride-hover); }
  & [role="radio"] svg { width: 24px; height: 24px; fill: currentColor; stroke: none; }
  & .on { color: var(--amo-ride-accent); }
  & [aria-checked="true"] { scale: 1.12; }
}
.amo-ride .amo-ride-tips {
  display: flex; gap: 6px; flex-wrap: wrap;
  & [role="radio"] { padding: 8px 14px; border-radius: 99px; font-weight: 650; font-variant-numeric: tabular-nums; box-shadow: inset 0 0 0 1px var(--amo-ride-line2); transition: background .15s, color .15s; }
  & [role="radio"]:hover { background: var(--amo-ride-hover); }
  & [aria-checked="true"] { background: var(--amo-ride-ink); color: var(--amo-ride-on); box-shadow: none; }
}

/* ── sheet (chat / cancel) ─────────────────────────── */
.amo-ride .amo-ride-sheet {
  position: absolute; inset: auto 0 0; z-index: 6; max-height: 88%; display: flex; flex-direction: column;
  border-radius: 20px 20px 0 0; background: var(--amo-ride-paper);
  box-shadow: 0 -1px 0 var(--amo-ride-line2), 0 -24px 48px -20px color-mix(in oklch, var(--amo-ride-ink) 40%, transparent);
  transition: translate .45s var(--amo-ride-ease), opacity .3s;
  @starting-style { translate: 0 40%; opacity: 0; }
  & header { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 14px 16px 10px; border-bottom: 1px solid var(--amo-ride-line); }
  & header b { font-size: 15px; font-weight: 700; }
  & header small { display: block; font-size: 12px; color: var(--amo-ride-mute); }
  & .x { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; background: var(--amo-ride-hover); }
  & .x:hover { background: var(--amo-ride-line); }
}
.amo-ride .amo-ride-thread {
  flex: 1; min-height: 120px; overflow-y: auto; display: flex; flex-direction: column; gap: 6px; padding: 12px 16px;
  & p { max-width: 80%; padding: 8px 12px; border-radius: 16px 16px 16px 4px; background: var(--amo-ride-hover); text-wrap: pretty; animation: amo-ride-in .3s var(--amo-ride-ease) backwards; }
  & p.me { align-self: flex-end; border-radius: 16px 16px 4px 16px; background: var(--amo-ride-ink); color: var(--amo-ride-on); }
  & p small { display: block; font-size: 10.5px; opacity: .6; margin-top: 2px; }
  & .typing { color: var(--amo-ride-mute); font-style: italic; background: none; padding-left: 4px; }
}
.amo-ride .amo-ride-quick { display: flex; gap: 6px; overflow-x: auto; padding: 0 16px 8px; scrollbar-width: none;
  & button { flex: none; padding: 7px 12px; border-radius: 99px; font-size: 12.5px; box-shadow: inset 0 0 0 1px var(--amo-ride-line2); white-space: nowrap; }
  & button:hover { background: var(--amo-ride-hover); }
}
.amo-ride .amo-ride-compose {
  display: flex; gap: 8px; padding: 8px 16px 14px;
  & input { flex: 1; min-width: 0; padding: 10px 14px; border-radius: 99px; border: 0; background: var(--amo-ride-hover); outline: none; }
  & input:focus { box-shadow: inset 0 0 0 2px var(--amo-ride-ink); }
  & button { display: grid; place-items: center; width: 40px; border-radius: 50%; background: var(--amo-ride-ink); color: var(--amo-ride-on); }
  & button:disabled { opacity: .3; }
}
.amo-ride .amo-ride-confirm { display: grid; gap: 12px; padding: 16px; & p { color: var(--amo-ride-mute); text-wrap: pretty; } & p b { color: var(--amo-ride-ink); } }
.amo-ride .amo-ride-danger { background: oklch(0.55 0.19 28) !important; }

/* ── map ──────────────────────────────────────────── */
.amo-ride .amo-ride-map { grid-area: map; position: relative; min-width: 0; min-height: 0; overflow: hidden; background: var(--amo-ride-land); }
.amo-ride .amo-ride-svg {
  position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; cursor: crosshair; user-select: none;
  fill: none; stroke: none; stroke-width: 1;
  &.panning { cursor: grabbing; }
  & text { font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; }
  & .m-land { fill: var(--amo-ride-land); }
  & .m-block { fill: var(--amo-ride-block); stroke: var(--amo-ride-block); stroke-width: 6; stroke-linejoin: round; }
  & .m-bld { fill: var(--amo-ride-bld); }
  & .m-big { fill: color-mix(in oklch, var(--amo-ride-bld), var(--amo-ride-ink) 6%); }
  & .m-park { fill: var(--amo-ride-park); stroke: var(--amo-ride-park); stroke-width: 6; stroke-linejoin: round; }
  & .m-path { fill: none; stroke: color-mix(in oklch, var(--amo-ride-park), white 45%); stroke-width: 2.4; stroke-dasharray: 1 5; stroke-linecap: round; }
  & .m-tree { fill: color-mix(in oklch, var(--amo-ride-park), oklch(0.45 0.1 150) 22%); }
  & .m-water { fill: var(--amo-ride-water); }
  & .m-wave { fill: none; stroke: color-mix(in oklch, var(--amo-ride-water), white 35%); stroke-width: 1.5; stroke-linecap: round; }
  & .m-case { fill: none; stroke: var(--amo-ride-case); stroke-linecap: round; stroke-linejoin: round; }
  & .m-st { fill: none; stroke: var(--amo-ride-street); stroke-linecap: round; stroke-linejoin: round; }
  & .m-st.main { stroke: var(--amo-ride-main); }
  & .m-bridge { stroke: color-mix(in oklch, var(--amo-ride-case), var(--amo-ride-ink) 25%); }
  & .m-lbl { font-size: 10.5px; font-weight: 600; letter-spacing: .02em; fill: color-mix(in oklch, var(--amo-ride-ink) 48%, var(--amo-ride-land)); paint-order: stroke; stroke: var(--amo-ride-street); stroke-width: 3px; stroke-linejoin: round; }
  & .m-lbl.water { fill: color-mix(in oklch, var(--amo-ride-water), var(--amo-ride-ink) 40%); stroke: none; font-style: italic; letter-spacing: .3em; font-size: 12px; }
  & .m-lbl.park { fill: color-mix(in oklch, var(--amo-ride-park), oklch(0.35 0.08 150) 70%); stroke: none; font-size: 11px; }
}
/* every map symbol sits at (--x, --y), turns by --r and is scaled by --k so it keeps its screen size at any zoom */
.amo-ride .amo-ride-svg .k { transform: translate(calc(var(--x) * 1px), calc(var(--y) * 1px)) rotate(calc(var(--r, 0) * 1deg)) scale(var(--k, 1)); }
/* points of interest */
.amo-ride .amo-ride-svg .poi {
  cursor: pointer; outline: none;
  & .r { fill: var(--amo-ride-paper); stroke: var(--amo-ride-line2); stroke-width: 1; transition: scale .35s var(--amo-ride-spring); transform-box: fill-box; transform-origin: center; }
  & .g { fill: none; stroke: var(--amo-ride-mute); stroke-width: 2.6; stroke-linecap: round; stroke-linejoin: round; }
  & text { font-size: 11.5px; font-weight: 650; fill: var(--amo-ride-ink); paint-order: stroke; stroke: var(--amo-ride-land); stroke-width: 3.5px; stroke-linejoin: round; }
  &:hover .r, &:focus-visible .r { scale: 1.18; stroke: var(--amo-ride-ink); stroke-width: 1.5; }
  &:focus-visible .r { stroke: var(--amo-ride-accent); stroke-width: 2.5; }
  &.dest .r { fill: var(--amo-ride-accent); stroke: var(--amo-ride-paper); }
  &.dest .g { stroke: var(--amo-ride-paper); }
}
/* cars */
.amo-ride .amo-ride-svg .car {
  & .sh { fill: color-mix(in oklch, var(--amo-ride-ink) 22%, transparent); }
  & .bd { fill: var(--amo-ride-paper); stroke: color-mix(in oklch, var(--amo-ride-ink) 55%, transparent); stroke-width: 1.2; }
  & .gl { fill: color-mix(in oklch, var(--amo-ride-ink) 55%, transparent); }
  &.mine .bd { fill: var(--amo-ride-ink); stroke: var(--amo-ride-paper); stroke-width: 1.4; }
  &.mine .gl { fill: color-mix(in oklch, var(--amo-ride-paper) 70%, transparent); }
  &.mine .halo { fill: color-mix(in oklch, var(--amo-ride-ink) 12%, transparent); }
}
/* route */
.amo-ride .amo-ride-svg {
  & .rt-case { fill: none; stroke: var(--amo-ride-paper); stroke-width: 13; stroke-linecap: round; stroke-linejoin: round; }
  & .rt { fill: none; stroke: var(--amo-ride-ink); stroke-width: 6; stroke-linecap: round; stroke-linejoin: round; }
  & .rt-done { fill: none; stroke: color-mix(in oklch, var(--amo-ride-ink) 22%, transparent); stroke-width: 6; stroke-linecap: round; stroke-linejoin: round; }
  & .ap { fill: none; stroke: var(--amo-ride-ink); stroke-width: 4; stroke-dasharray: 0.1 10; stroke-linecap: round; opacity: .7; }
  & .pk-halo { fill: color-mix(in oklch, var(--amo-ride-ink) 14%, transparent); transform-box: fill-box; transform-origin: center; animation: amo-ride-breathe 2.6s ease-in-out infinite; }
  & .pk { fill: var(--amo-ride-ink); stroke: var(--amo-ride-paper); stroke-width: 3; }
  & .dp { fill: var(--amo-ride-accent); stroke: var(--amo-ride-paper); stroke-width: 3; }
  & .dp-c { fill: var(--amo-ride-paper); }
  & .tag rect { fill: var(--amo-ride-ink); }
  & .tag text { fill: var(--amo-ride-on); font-size: 11.5px; font-weight: 700; font-variant-numeric: tabular-nums; }
  & .tag text tspan { font-weight: 500; fill-opacity: .7; }
  & .tag.acc rect { fill: var(--amo-ride-paper); stroke: var(--amo-ride-line2); }
  & .tag.acc text { fill: var(--amo-ride-ink); }
  & .ping { fill: none; stroke: var(--amo-ride-accent); stroke-width: 2; transform-box: fill-box; transform-origin: center; animation: amo-ride-ping 2.1s cubic-bezier(.2, .7, .3, 1) infinite; animation-delay: calc(var(--i) * 700ms); opacity: 0; }
}
@keyframes amo-ride-breathe { 50% { scale: 1.35; opacity: .55; } }
@keyframes amo-ride-ping { 0% { scale: .2; opacity: .9; } 100% { scale: 1; opacity: 0; } }
.amo-ride .amo-ride-hint {
  position: absolute; left: 14px; top: 14px; display: flex; align-items: center; gap: 7px; padding: 7px 12px 7px 9px; border-radius: 99px;
  background: color-mix(in oklch, var(--amo-ride-paper) 92%, transparent); box-shadow: 0 0 0 1px var(--amo-ride-line), 0 6px 18px -8px var(--amo-ride-line2);
  font-size: 12px; font-weight: 600; pointer-events: none; transition: opacity .25s;
  & svg { width: 14px; height: 14px; color: var(--amo-ride-accent); }
  &:empty { opacity: 0; }
}
.amo-ride .amo-ride-ctl {
  position: absolute; right: 14px; top: 14px; display: grid; border-radius: 12px; overflow: hidden;
  background: var(--amo-ride-paper); box-shadow: 0 0 0 1px var(--amo-ride-line), 0 8px 22px -10px var(--amo-ride-line2);
  & button { display: grid; place-items: center; width: 36px; height: 36px; transition: background .15s; }
  & button + button { border-top: 1px solid var(--amo-ride-line); }
  & button:hover:not(:disabled) { background: var(--amo-ride-hover); }
  & button:disabled { opacity: .35; }
}
.amo-ride .amo-ride-scale {
  position: absolute; left: 14px; bottom: 14px; display: flex; align-items: flex-end; gap: 6px; font-size: 10.5px; font-weight: 650; color: var(--amo-ride-mute);
  & i { display: block; height: 6px; border: 1.5px solid var(--amo-ride-mute); border-top: 0; width: var(--w, 80px); transition: width .3s var(--amo-ride-ease); }
}

/* toast */
.amo-ride .amo-ride-toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 9; translate: -50% 0; display: flex; align-items: center; gap: 12px;
  max-width: calc(100% - 32px); padding: 10px 12px 10px 16px; border-radius: 12px; background: var(--amo-ride-ink); color: var(--amo-ride-on);
  font-size: 13px; box-shadow: 0 14px 30px -12px color-mix(in oklch, var(--amo-ride-ink) 60%, transparent);
  transition: opacity .25s, translate .4s var(--amo-ride-spring);
  @starting-style { opacity: 0; translate: -50% 12px; }
  & button { font-weight: 700; color: var(--amo-ride-accent); padding: 2px 6px; border-radius: 6px; }
  & button:hover { background: color-mix(in oklch, var(--amo-ride-on) 12%, transparent); }
}

/* ── responsive ───────────────────────────────────── */
@container (max-width: 959px) {
  .amo-ride .amo-ride-app { grid-template-columns: 316px minmax(0, 1fr); }
  .amo-ride .amo-ride-keys { display: none; }
}
@container (max-width: 759px) {
  .amo-ride .amo-ride-tabs {
    display: flex; gap: 4px; padding: 8px 10px; border-bottom: 1px solid var(--amo-ride-line);
    & button { flex: 1; display: flex; align-items: center; justify-content: center; gap: 6px; padding: 8px; border-radius: 10px; font-weight: 650; color: var(--amo-ride-mute); }
    & button[aria-selected="true"] { background: var(--amo-ride-ink); color: var(--amo-ride-on); }
  }
  .amo-ride .amo-ride-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "main"; }
  .amo-ride .amo-ride-panel, .amo-ride .amo-ride-map { grid-area: main; border: 0; }
  .amo-ride[data-view="ride"] .amo-ride-map { visibility: hidden; }
  .amo-ride[data-view="map"] .amo-ride-panel { display: none; }
  .amo-ride .amo-ride-top { padding: 12px 16px 4px; }
  .amo-ride .amo-ride-body { padding: 6px 16px 16px; }
  .amo-ride .amo-ride-dock { margin: auto -16px -16px; padding: 12px 16px 16px; bottom: -16px; }
  .amo-ride .amo-ride-acts button { font-size: 11px; }
}
@container (max-width: 420px) {
  .amo-ride .amo-ride-opt { grid-template-columns: 44px minmax(0, 1fr) auto; & .car { width: 44px; } }
  .amo-ride .amo-ride-driver { grid-template-columns: 44px minmax(0, 1fr); & .av { width: 44px; height: 44px; } & .plate { grid-column: 1 / -1; justify-self: start; } }
}

@media (prefers-reduced-motion: reduce) {
  .amo-ride {
    & *, & *::before, & *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
    & .amo-ride-radar { background: color-mix(in oklch, var(--amo-ride-accent) 14%, transparent); }
    & .amo-ride-prog.seek i { animation: none; width: 100%; opacity: .35; }
    & .amo-ride-svg .ping { display: none; }
    & .amo-ride-svg .pk-halo { animation: none; }
  }
}

