/* ── Corvo · ride hailing on a real street graph ──────────────────────────
   The city is a jittered grid of intersections cut by a river that only three
   bridges cross. Every route (rider to destination, driver to rider) is a
   Dijkstra shortest path over that graph, timed by street class, so the
   distance, the minutes, each fare line, the pickup ETAs and the moving car
   all come from one source. The assigned car follows its polyline with a
   smoothed heading on a rAF loop that only runs while something is moving,
   on screen, in a visible tab. Map symbols are scaled by a single --k custom
   property so they stay the same size on screen at every zoom. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const NS = 'http://www.w3.org/2000/svg';
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const gbp = p => '£' + (p / 100).toFixed(2);
const hm = m => { m = ((Math.round(m) % 1440) + 1440) % 1440; return String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0'); };
const ico = p => '<svg viewBox="0 0 24 24" aria-hidden="true">' + p + '</svg>';
const I = {
  x: '<path d="M6 6l12 12M18 6 6 18"/>',
  swap: '<path d="M8 4v16M8 4 4.5 7.5M8 4l3.5 3.5M16 20V4M16 20l-3.5-3.5M16 20l3.5-3.5"/>',
  pin: '<path d="M12 21s-6.5-5.6-6.5-11a6.5 6.5 0 0 1 13 0c0 5.4-6.5 11-6.5 11Z"/><circle cx="12" cy="10" r="2.3"/>',
  here: '<path d="M12 3 19 20l-7-4-7 4Z"/>',
  home: '<path d="M4 11 12 4l8 7M6.5 9.5V20h11V9.5"/><path d="M10 20v-5h4v5"/>',
  work: '<rect x="3.5" y="7.5" width="17" height="12" rx="2"/><path d="M9 7.5V5.5A1.5 1.5 0 0 1 10.5 4h3A1.5 1.5 0 0 1 15 5.5v2M3.5 12.5h17"/>',
  rail: '<rect x="6" y="3.5" width="12" height="13" rx="3"/><path d="M6 11h12M9 20l1.5-3.5M15 20l-1.5-3.5"/>',
  bag: '<path d="M5 8h14l-1 12H6Z"/><path d="M9 8V6.5a3 3 0 0 1 6 0V8"/>',
  cross: '<rect x="4" y="4" width="16" height="16" rx="4"/><path d="M12 8v8M8 12h8"/>',
  mask: '<path d="M4 6h16v5a8 8 0 0 1-16 0Z"/><path d="M8 10.5c.8-.6 1.7-.6 2.5 0M13.5 10.5c.8-.6 1.7-.6 2.5 0M9 15c1.8 1.3 4.2 1.3 6 0"/>',
  swim: '<path d="M3 17c1.5 1 3 1 4.5 0s3-1 4.5 0 3 1 4.5 0 3-1 4.5 0"/><circle cx="15" cy="7" r="1.8"/><path d="m6 13 5-4.5 3 3.5"/>',
  book: '<path d="M4 5.5A1.5 1.5 0 0 1 5.5 4H11v16H5.5A1.5 1.5 0 0 1 4 18.5Z"/><path d="M20 5.5A1.5 1.5 0 0 0 18.5 4H13v16h5.5a1.5 1.5 0 0 0 1.5-1.5Z"/>',
  cross2: '<path d="M7 7h10v10H7z"/>',
  star: '<path d="m12 3.2 2.7 5.6 6.1.8-4.5 4.2 1.1 6-5.4-2.9-5.4 2.9 1.1-6L3.2 9.6l6.1-.8Z"/>',
  chat: '<path d="M5 18.5V7a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2v7a2 2 0 0 1-2 2H8Z"/>',
  phone: '<path d="M6.5 3.5h3l1.5 4.5-2 1.5a11 11 0 0 0 5.5 5.5l1.5-2 4.5 1.5v3a2 2 0 0 1-2 2A16 16 0 0 1 4.5 5.5a2 2 0 0 1 2-2Z"/>',
  share: '<path d="M12 15V4M8 7.5 12 3.5l4 4"/><path d="M6 11v8.5h12V11"/>',
  card: '<rect x="3" y="6" width="18" height="12" rx="2"/><path d="M3 10h18"/>',
  wallet: '<path d="M4 7.5V18a1.5 1.5 0 0 0 1.5 1.5h13A1.5 1.5 0 0 0 20 18v-8.5A1.5 1.5 0 0 0 18.5 8h-13A1.5 1.5 0 0 1 4 6.5 1.5 1.5 0 0 1 5.5 5H17"/><circle cx="16" cy="13.7" r="1.1"/>',
  check: '<path d="m5 12.5 4.5 4.5L19 7.5"/>',
  chev: '<path d="m6 9 6 6 6-6"/>',
  send: '<path d="M4 12 20 4l-5 16-3.5-6.5Z"/><path d="m11.5 13.5 3-3"/>',
  ff: '<path d="M4 6.5v11l7-5.5Z"/><path d="M12 6.5v11l7-5.5Z"/>',
  user: '<circle cx="12" cy="8.5" r="3.5"/><path d="M5 20a7 7 0 0 1 14 0"/>',
  stop: '<circle cx="12" cy="12" r="8.5"/><path d="M8.5 8.5l7 7M15.5 8.5l-7 7"/>',
  clock: '<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>',
};
/* side-view silhouettes for the ride options, drawn on a 58×30 grid */
const CARS = {
  hatch: '<path class="b" d="M5 22v-6c0-1.5 1-2.6 2.4-3l7.6-2 6.3-5.6c.8-.7 1.8-1.1 2.9-1.1h11.6c1.2 0 2.3.5 3.1 1.4l4.6 5.6 5 1.4c1.5.5 2.5 1.8 2.5 3.4V22Z"/><path d="M17 11h28M31.5 4.6V11"/>',
  saloon: '<path class="b" d="M3 22v-5c0-1.4 1-2.5 2.3-2.8L16 12l6.5-5.3c.8-.6 1.8-1 2.8-1h10.3c1.1 0 2.1.4 2.9 1.1L45 12.2l8 1.6c1.4.3 2.4 1.5 2.4 2.9V22Z"/><path d="M18 12h27M31 5.7V12"/>',
  van: '<path class="b" d="M4 22V9.5c0-2 1.4-3.8 3.4-4.2l3.6-.8c1-.2 2-.3 3-.3h26.5c1.3 0 2.5.6 3.3 1.6l4.7 6 4.3 1.5c1.4.5 2.2 1.7 2.2 3.1V22Z"/><path d="M4 12h44M20 4.3V12M34 4.3V12"/>',
};
const wheels = '<circle cx="15" cy="22" r="4.2" fill="var(--amo-ride-paper)"/><circle cx="44" cy="22" r="4.2" fill="var(--amo-ride-paper)"/>';
const carSvg = (shape, bolt) => '<svg class="car" viewBox="0 0 58 30" aria-hidden="true">' + CARS[shape] + wheels + (bolt ? '<path d="m50 3-3 4.5h3.2L47.6 12" stroke-width="1.5"/>' : '') + '</svg>';

/* ── the city ─────────────────────────────────────────────────────────── */
const MW = 1200, MH = 800, COLS = 9, ROWS = 7, EXT = 220;
const XS = [70, 200, 330, 460, 600, 740, 870, 1000, 1130];
const YS = [60, 168, 276, 386, 526, 634, 742];
const ROWN = ['Ashby Row', 'Kiln Street', 'Mercer Street', 'North Quay', 'South Quay', 'Tanner Street', 'Holloway Road'];
const COLN = ['Fenwick Lane', 'Orchard Way', 'Bell Street', 'Saltmarket', 'Lantern Avenue', 'Copper Lane', 'Weaver Street', 'Granary Road', 'Eastgate'];
const BRIDGES = [1, 4, 7], MAIN_R = [3, 4], MAIN_C = [4];
const KM = 0.003;                               /* one map unit is 3 m */
const SPEED = { main: 30 / KM / 60, local: 20 / KM / 60 };   /* units per minute */
