/* Dijkstra by travel time. 63 nodes, so the plain O(n²) version is plenty. */
function route(from, to) {
  const n = N.length, dist = new Array(n).fill(Infinity), prev = new Array(n).fill(-1), done = new Array(n).fill(false);
