    if (u < 0 || dist[u] === Infinity) break;
    if (u === to) break;
    done[u] = true;
    for (const { to: v, e } of ADJ[u]) { const d = dist[u] + edgeT(e); if (d < dist[v]) { dist[v] = d; prev[v] = u; } }
