@property --amo-courier-p { syntax: "<percentage>"; inherits: true; initial-value: 0%; }
.amo-courier {
  /* re-theme with these five */
  --amo-courier-bg: oklch(0.19 0.009 70);
  --amo-courier-ink: oklch(0.95 0.008 85);
  --amo-courier-accent: oklch(0.83 0.15 78);
  --amo-courier-good: oklch(0.79 0.14 155);
  --amo-courier-bad: oklch(0.7 0.17 32);

  --amo-courier-surf: color-mix(in oklch, var(--amo-courier-ink) 5%, var(--amo-courier-bg));
  --amo-courier-surf2: color-mix(in oklch, var(--amo-courier-ink) 9%, var(--amo-courier-bg));
  --amo-courier-line: color-mix(in oklch, var(--amo-courier-ink) 10%, transparent);
  --amo-courier-line2: color-mix(in oklch, var(--amo-courier-ink) 18%, transparent);
  --amo-courier-mute: color-mix(in oklch, var(--amo-courier-ink) 62%, var(--amo-courier-bg));
  --amo-courier-faint: color-mix(in oklch, var(--amo-courier-ink) 40%, var(--amo-courier-bg));
  --amo-courier-on: oklch(0.2 0.03 70);
  --amo-courier-map: color-mix(in oklch, var(--amo-courier-bg), black 28%);
  --amo-courier-ease: cubic-bezier(.2, .8, .2, 1);
  --amo-courier-spring: linear(0, 0.13 6%, 0.45 13%, 0.8 21%, 1 29%, 1.05 36%, 1.04 44%, 1.01 56%, 1);

