  & .l-home { stroke: color-mix(in oklch, var(--amo-courier-accent) 40%, var(--amo-courier-map)); stroke-width: calc(2px * var(--s)); stroke-dasharray: calc(2px * var(--s)) calc(6px * var(--s)); stroke-linecap: round; stroke-linejoin: round; }
  & .l-rest { stroke: color-mix(in oklch, var(--amo-courier-accent) 70%, var(--amo-courier-map)); stroke-width: calc(3px * var(--s)); stroke-dasharray: calc(10px * var(--s)) calc(8px * var(--s)); stroke-linejoin: round; animation: amo-courier-march 1.6s linear infinite; }
  & .l-next-glow { stroke: color-mix(in oklch, var(--amo-courier-accent) 30%, transparent); stroke-width: calc(14px * var(--s)); stroke-linecap: round; stroke-linejoin: round; }
  & .l-next { stroke: var(--amo-courier-accent); stroke-width: calc(5px * var(--s)); stroke-linecap: round; stroke-linejoin: round; }
  & .l-nav { stroke: var(--amo-courier-ink); stroke-width: calc(4px * var(--s)); stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: calc(8px * var(--s)) calc(6px * var(--s)); animation: amo-courier-march 1.2s linear infinite; }
}
@keyframes amo-courier-march { to { stroke-dashoffset: calc(-36px * var(--s)); } }
.amo-courier .amo-courier-svg .pin {
  transform: translate(calc(var(--x) * 1px), calc(var(--y) * 1px)) scale(var(--s));
