  &.stop { cursor: pointer; outline: none; }
  & .hit { fill: transparent; }
  & .halo { fill: color-mix(in oklch, var(--amo-courier-accent) 30%, transparent); opacity: 0; transform-box: fill-box; transform-origin: center; scale: .5; transition: opacity .25s, scale .45s var(--amo-courier-spring); }
  & .dot { fill: var(--amo-courier-surf2); stroke: var(--amo-courier-accent); stroke-width: 2.2; transition: scale .35s var(--amo-courier-spring); transform-box: fill-box; transform-origin: center; }
  & .gl { stroke: var(--amo-courier-on); stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
