  & .pulse { fill: color-mix(in oklch, var(--amo-courier-ink) 22%, transparent); transform-box: fill-box; transform-origin: center; animation: amo-courier-pulse 2.2s cubic-bezier(.2, .7, .3, 1) infinite; }
}
@keyframes amo-courier-pulse { 0% { scale: .3; opacity: 1; } 100% { scale: 1.3; opacity: 0; } }
.amo-courier .amo-courier-dir {
  position: absolute; left: 14px; bottom: 14px; width: min(300px, calc(100% - 28px)); padding: 12px 14px; border-radius: 14px;
  background: color-mix(in oklch, var(--amo-courier-bg) 88%, transparent); backdrop-filter: blur(8px); box-shadow: 0 0 0 1px var(--amo-courier-line2), 0 18px 40px -16px black;
