}

/* ── stop card ────────────────────────────────────── */
.amo-courier .amo-courier-card {
  grid-area: map; z-index: 4; align-self: start; justify-self: end; margin: 12px; width: min(318px, calc(100% - 24px)); max-height: calc(100% - 24px);
