  & .x .i-back { display: none; }
  & .x:hover { background: var(--amo-courier-surf2); color: var(--amo-courier-ink); }
  & h3 { font-size: 11px; font-weight: 750; letter-spacing: .09em; text-transform: uppercase; color: var(--amo-courier-faint); }
}
.amo-courier .amo-courier-body { display: grid; gap: 12px; padding: 12px 14px 14px; overflow-y: auto; scrollbar-width: thin; }
.amo-courier .amo-courier-facts {
  display: flex; flex-wrap: wrap; gap: 6px;
  & .eta { padding: 5px 8px; border-radius: 8px; background: var(--amo-courier-surf2); font-size: 13px; }
  & .fact { display: inline-flex; align-items: center; gap: 5px; padding: 5px 8px; border-radius: 8px; background: var(--amo-courier-surf); font-size: 12px; color: var(--amo-courier-mute); font-variant-numeric: tabular-nums; }
  & .fact svg { width: 13px; height: 13px; }
