}
.amo-courier .note { padding: 9px 11px; border-radius: 10px; background: var(--amo-courier-surf); border-left: 3px solid var(--amo-courier-accent); color: var(--amo-courier-ink); text-wrap: pretty; font-size: 12.5px;
