  & i.zL { background: var(--amo-courier-accent); } & i.zM { background: color-mix(in oklch, var(--amo-courier-accent) 60%, var(--amo-courier-ink)); }
}
.amo-courier .amo-courier-three { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; & .amo-courier-btn { padding: 0 6px; font-size: 12px; gap: 5px; } & svg { width: 14px; height: 14px; } }
.amo-courier .amo-courier-two { display: grid; grid-template-columns: 1fr 1.4fr; gap: 8px; &.big .amo-courier-btn { height: 46px; font-size: 14px; } }
.amo-courier .amo-courier-state { display: flex; align-items: center; gap: 6px; font-weight: 700; &.good { color: var(--amo-courier-good); } &.bad { color: var(--amo-courier-bad); } }
.amo-courier .amo-courier-sigview { width: 100%; height: auto; border-radius: 10px; background: var(--amo-courier-surf); & path { fill: none; stroke: var(--amo-courier-ink); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; } }
.amo-courier .amo-courier-seg {
