    & button[aria-selected="true"] { background: var(--amo-courier-surf2); color: var(--amo-courier-ink); }
  }
  .amo-courier .amo-courier-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "main"; }
  .amo-courier .amo-courier-list, .amo-courier .amo-courier-map { grid-area: main; border: 0; }
