    & .amo-courier-svg .l-rest, & .amo-courier-svg .l-nav { animation: none; }
    & .amo-courier-svg .van .pulse { animation: none; opacity: .5; scale: .8; }
  }
}

js:
/* ── Stopwise · a courier's route for the day ─────────────────────────────
   Northside is a street grid laid at -20°, and every stop sits on a corner,
   so a leg between two stops is a real two-street drive (along one street,
   then turn onto the other). The drawn line, the kilometres, the turn-by-turn
   text and the ETAs all come from that one L-shaped leg. ETAs run the route
   forward from now with service time and delivery windows (arrive early and
   you wait, arrive after the window and you are late). Drag a stop by its
   grip, press Alt+arrows, or Optimise (nearest neighbour, then 2-opt and
   relocate passes against a lateness-weighted cost): the list moves with a
   FLIP and every change is undoable. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const hm = m => { m = Math.round(m); return String(Math.floor(m / 60) % 24).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0'); };
const dur = m => { m = Math.round(m); return m >= 60 ? Math.floor(m / 60) + 'h ' + String(m % 60).padStart(2, '0') + 'm' : m + ' min'; };
const ico = p => '<svg viewBox="0 0 24 24" aria-hidden="true">' + p + '</svg>';
const I = {
  x: '<path d="M6 6l12 12M18 6 6 18"/>',
  check: '<path d="m5 12.5 4.5 4.5L19 7.5"/>',
  box: '<path d="M4 7.5 12 3l8 4.5v9L12 21l-8-4.5Z"/><path d="m4 7.5 8 4.5 8-4.5M12 12v9"/>',
  clock: '<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>',
  pen: '<path d="M4 20h4L19 9l-4-4L4 16Z"/><path d="m13.5 6.5 4 4"/>',
  biz: '<path d="M4 20V8l6-4v16M10 20V9l10 3v8M4 20h16"/>',
  nav: '<path d="M12 3 19 20l-7-4-7 4Z"/>',
  phone: '<path d="M6.5 3.5h3l1.5 4.5-2 1.5a11 11 0 0 0 5.5 5.5l1.5-2 4.5 1.5v3a2 2 0 0 1-2 2A16 16 0 0 1 4.5 5.5a2 2 0 0 1 2-2Z"/>',
  end: '<path d="M12 4v13M7 12l5 5 5-5M5 20h14"/>',
  warn: '<path d="M12 4 21 19.5H3Z"/><path d="M12 10v4M12 17v.01"/>',
  turnR: '<path d="M6 20v-7a4 4 0 0 1 4-4h8M14 5l4 4-4 4"/>',
  turnL: '<path d="M18 20v-7a4 4 0 0 0-4-4H6M10 5 6 9l4 4"/>',
  up: '<path d="M12 20V5M6 11l6-6 6 6"/>',
  flag: '<path d="M5 21V4M5 4h11l-2 4 2 4H5"/>',
  back: '<path d="M15 6 9 12l6 6"/>',
  undo: '<path d="M9 14 4 9l5-5"/><path d="M4 9h10.5a5.5 5.5 0 0 1 0 11H11"/>',
  chev: '<path d="m6 9 6 6 6-6"/>',
  grip: '<circle cx="9" cy="6" r="1.3"/><circle cx="15" cy="6" r="1.3"/><circle cx="9" cy="12" r="1.3"/><circle cx="15" cy="12" r="1.3"/><circle cx="9" cy="18" r="1.3"/><circle cx="15" cy="18" r="1.3"/>',
};

/* ── Northside: a -20° street grid, 400 m between corners ─────────────── */
const GS = 40, STEP_KM = 0.4, KMH = 22, TH = -20 * Math.PI / 180, CT = Math.cos(TH), ST = Math.sin(TH);
const W = (u, v) => ({ x: (u * CT - v * ST) * GS, y: (u * ST + v * CT) * GS });
const EW = ['Northgate', 'Ridge Road', 'Coldharbour Lane', 'Quarry Road', 'Larch Crescent', 'Mill Race', 'Sycamore Avenue', 'Pendle Street', 'Marlow Road', 'Rookery Lane', 'Alder Close', 'Gasworks Road', 'Brickfield Road', 'Canal Street', 'Lockside', 'Weir Road'];
const NS = ['Westway', 'Chapel Street', 'Kiln Lane', 'Ash Grove', 'Bramble Street', 'Heron Wharf', 'Station Road', 'Foundry Lane', 'Hatton Street', 'Tannery Row', 'Market Way', 'Union Street', 'Well Lane', 'Bishop Street', 'Cooper Street', 'Lime Walk', 'Cobble Mews', 'Garnet Street', 'Vale Road', 'Ferrous Way', 'Orchard Rise', 'Thorn Lane', 'Eastway'];
const ART_EW = [3, 9, 13], ART_NS = [6, 14];
const DEPOT = { id: 'depot', u: 2, v: 12, addr: 'Larkspur Depot, Kiln Lane' };
/* window [start, end] in minutes; sig = signature needed; biz = business (longer handover) */
const STOPS = [
  { id: 's1', u: 4, v: 10, addr: '12 Alder Close', who: 'Hannah Moretti', tel: '07700 900412', p: ['M', 'S'], win: [540, 1080], note: 'Side gate is unlocked — leave by the bins if no answer.' },
  { id: 's2', u: 7, v: 12, addr: 'Unit 4, Brickfield Trade Park', who: 'Coldwater Joinery', tel: '01632 960118', p: ['L', 'L', 'M', 'M', 'S'], win: [480, 1020], biz: 1, note: 'Goods-in at the rear. Ask for Dev.' },
  { id: 's3', u: 6, v: 8, addr: 'Flat 7, Marlow House, 88 Station Road', who: 'Kofi Mensah', tel: '07700 900877', p: ['S'], win: [600, 780], note: 'Buzzer 7. The lift is out of order.' },
  { id: 's4', u: 9, v: 9, addr: '3 Rookery Lane', who: 'Edith Chalmers', tel: '07700 900231', p: ['S'], win: [540, 1020], sig: 1, note: 'Age-restricted item — check ID and take a signature.' },
  { id: 's5', u: 11, v: 6, addr: '41 Sycamore Avenue', who: 'The Grain Store Café', tel: '01632 960552', p: ['L', 'M', 'M'], win: [420, 690], biz: 1, note: 'Closes for deliveries at 11:30.' },
  { id: 's6', u: 14, v: 7, addr: '19 Pendle Street', who: 'Arjun Bhatt', tel: '07700 900634', p: ['M', 'S'], win: [540, 1080], note: '' },
  { id: 's7', u: 13, v: 3, addr: 'Northside Library, Quarry Road', who: 'Northside Library', tel: '01632 960771', p: ['L', 'L', 'M', 'S'], win: [570, 960], biz: 1, sig: 1, note: 'Staff entrance on Bishop Street. Signature from the duty librarian.' },
  { id: 's8', u: 17, v: 4, addr: '56 Larch Crescent', who: 'Mia Fitzgerald', tel: '07700 900190', p: ['S'], win: [720, 900], note: 'Booked 12:00–15:00. Dog in the garden, friendly.' },
  { id: 's9', u: 19, v: 8, addr: '2 Ferrous Way', who: 'Halcyon Bikes', tel: '01632 960340', p: ['L', 'L', 'L', 'M', 'M', 'S'], win: [600, 960], biz: 1, note: 'Roller door — ring the bell on the left.' },
  { id: 's10', u: 16, v: 10, addr: 'Flat 2, 9 Cobble Mews', who: 'Sian Pryce', tel: '07700 900558', p: ['M'], win: [540, 1080], note: 'Mews is cobbled and narrow — park on Garnet Street.' },
  { id: 's11', u: 20, v: 12, addr: '77 Orchard Rise', who: 'Jakub Nowak', tel: '07700 900726', p: ['M', 'S'], win: [540, 1080], note: '' },
  { id: 's12', u: 12, v: 12, addr: 'St Brigid’s Primary, Well Lane', who: 'St Brigid’s Primary', tel: '01632 960905', p: ['L', 'M', 'M'], win: [510, 750], biz: 1, sig: 1, note: 'Reception only — sign in at the office. Deliveries close at 12:30 for lunch.' },
  { id: 's13', u: 9, v: 4, addr: '14 Tannery Row', who: 'Lucía Romero', tel: '07700 900383', p: ['S'], win: [780, 1020], note: 'Booked 13:00–17:00.' },
  { id: 's14', u: 5, v: 3, addr: '5 Heron Wharf', who: 'Callie Dunmore', tel: '07700 900917', p: ['M', 'S'], win: [540, 1080], note: 'Houseboat at the far end of the wharf.' },
];
const BY = Object.fromEntries(STOPS.concat(DEPOT).map(s => [s.id, s]));
const KG = { S: 0.8, M: 3.2, L: 9.5 };
STOPS.forEach((s, i) => s.codes = s.p.map((z, k) => 'LP ' + (2207 + i * 37 + k * 11) + ' ' + String(4401 + i * 613 + k * 97).slice(-4)));
const service = s => 2 + s.p.length + (s.biz ? 2 : 0) + (s.sig ? 1 : 0);

/* a leg is two straight runs: along the first stop's east–west street, then the second's north–south street */
function leg(a, b) {
  const du = b.u - a.u, dv = b.v - a.v;
  return { a, b, du, dv, steps: Math.abs(du) + Math.abs(dv), km: (Math.abs(du) + Math.abs(dv)) * STEP_KM, min: (Math.abs(du) + Math.abs(dv)) * STEP_KM / KMH * 60 };
}
function legD(a, b) { const p = W(a.u, a.v), c = W(b.u, a.v), q = W(b.u, b.v); return 'M' + p.x.toFixed(1) + ' ' + p.y.toFixed(1) + 'L' + c.x.toFixed(1) + ' ' + c.y.toFixed(1) + 'L' + q.x.toFixed(1) + ' ' + q.y.toFixed(1); }
function directions(a, b) {
  const L = leg(a, b), out = [];
  if (!L.steps) return [{ ic: 'flag', t: 'You are here' }];
  const ew = L.du > 0 ? 'east' : 'west', ns = L.dv > 0 ? 'south' : 'north';
  if (L.du) out.push({ ic: 'up', t: 'Head ' + ew + ' on ' + EW[a.v], km: Math.abs(L.du) * STEP_KM });
  if (L.dv) {
    if (L.du) {
      const d1 = { x: CT * Math.sign(L.du), y: ST * Math.sign(L.du) }, d2 = { x: -ST * Math.sign(L.dv), y: CT * Math.sign(L.dv) };
      const right = d1.x * d2.y - d1.y * d2.x > 0;
      out.push({ ic: right ? 'turnR' : 'turnL', t: 'Turn ' + (right ? 'right' : 'left') + ' onto ' + NS[b.u], km: Math.abs(L.dv) * STEP_KM });
    } else out.push({ ic: 'up', t: 'Head ' + ns + ' on ' + NS[a.u], km: Math.abs(L.dv) * STEP_KM });
  }
  out.push({ ic: 'flag', t: 'Arrive at ' + b.addr });
  return out;
}

/* ── state ───────────────────────────────────────────────────────────── */
const S = {
  /* pending stops in route order; the first five were delivered this morning */
  order: ['s6', 's9', 's11', 's10', 's8', 's7', 's14', 's13', 's12'],
  st: {
    s1: { s: 'done', at: 552, how: 'Safe place · side gate' }, s2: { s: 'done', at: 577, how: 'Signed by Dev Anand', sig: 1 },
    s3: { s: 'done', at: 603, how: 'Handed to Kofi Mensah', sig: 1 }, s4: { s: 'done', at: 621, how: 'Signed by Edith Chalmers · ID checked', sig: 1 },
    s5: { s: 'done', at: 640, how: 'Handed to Tess at the counter' },
  },
  doneOrder: ['s1', 's2', 's3', 's4', 's5'], now: 641,
  sel: 's6', filter: 'all', showDone: false, mode: 'info', nav: null, undo: [], view: 'stops',
  proof: { how: 'hand', spot: 'Porch', who: '', strokes: [] }, fail: { why: 'absent', card: true },
};
const pos = () => S.doneOrder.length ? BY[S.doneOrder[S.doneOrder.length - 1]] : DEPOT;

/* run the route forward from now */
function plan(order, from = pos(), t0 = S.now) {
  let t = t0, at = from, km = 0;
  const rows = order.map(id => {
    const s = BY[id], L = leg(at, s), arrive = t + L.min, begin = Math.max(arrive, s.win[0]);
    const r = { id, arrive, begin, wait: begin - arrive, late: Math.max(0, begin - s.win[1]), km: L.km, end: begin + service(s) };
    km += L.km; t = r.end; at = s;
    return r;
  });
  const home = leg(at, DEPOT);
  km += home.km;
  return { rows, km, finish: t + home.min, late: rows.reduce((n, r) => n + (r.late > 0), 0), lateMin: rows.reduce((n, r) => n + r.late, 0), wait: rows.reduce((n, r) => n + r.wait, 0) };
}
const cost = p => p.finish + p.km * 1.2 + p.lateMin * 25;   /* minutes, with a kilometre worth 1.2 min of fuel and wear */

/* nearest neighbour seed, then 2-opt reversals and single-stop relocations until nothing improves */
function optimise(ids) {
  let rest = ids.slice(), at = pos(), seq = [];
  while (rest.length) { rest.sort((a, b) => leg(at, BY[a]).steps - leg(at, BY[b]).steps); const n = rest.shift(); seq.push(n); at = BY[n]; }
  let best = seq, bc = cost(plan(seq)), better = true, guard = 0;
  if (cost(plan(ids)) < bc) { best = ids.slice(); bc = cost(plan(ids)); }
  while (better && guard++ < 60) {
    better = false;
    for (let i = 0; i < best.length - 1; i++) for (let j = i + 1; j < best.length; j++) {
      const c = best.slice(0, i).concat(best.slice(i, j + 1).reverse(), best.slice(j + 1)), k = cost(plan(c));
      if (k < bc - .01) { best = c; bc = k; better = true; }
