.amo-transit {
  /* re-theme with these four; line colours live in the timetable data */
  --amo-transit-paper: oklch(0.99 0.003 95);
  --amo-transit-ink: oklch(0.17 0.01 260);
  --amo-transit-accent: oklch(0.52 0.17 255);
  --amo-transit-warn: oklch(0.58 0.19 30);

  --amo-transit-line: color-mix(in oklch, var(--amo-transit-ink) 10%, transparent);
  --amo-transit-line2: color-mix(in oklch, var(--amo-transit-ink) 18%, transparent);
  --amo-transit-hover: color-mix(in oklch, var(--amo-transit-ink) 4%, transparent);
  --amo-transit-mute: color-mix(in oklch, var(--amo-transit-ink) 60%, var(--amo-transit-paper));
  --amo-transit-faint: color-mix(in oklch, var(--amo-transit-ink) 40%, var(--amo-transit-paper));
  --amo-transit-tint: color-mix(in oklch, var(--amo-transit-accent) 9%, var(--amo-transit-paper));
  --amo-transit-well: color-mix(in oklch, var(--amo-transit-ink) 3.5%, var(--amo-transit-paper));
  --amo-transit-ease: cubic-bezier(.2, .8, .2, 1);
  --amo-transit-spring: linear(0, 0.14 6%, 0.47 13%, 0.82 21%, 1.01 29%, 1.05 36%, 1.03 45%, 1.005 58%, 1);

  position: relative; width: 100%; height: var(--amo-transit-h, 680px); box-sizing: border-box;
  container-type: inline-size; overflow: clip; isolation: isolate; display: flex; flex-direction: column;
  border-radius: 18px; background: var(--amo-transit-paper); color: var(--amo-transit-ink); color-scheme: light; accent-color: var(--amo-transit-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; box-shadow: inset 0 0 0 1px var(--amo-transit-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--amo-transit-accent); outline-offset: 2px; }
  & button, & input, & output { font: inherit; color: inherit; }
