  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 4px; font: 650 10px/1 ui-monospace, Menlo, monospace; color: var(--amo-transit-mute); box-shadow: inset 0 0 0 1px var(--amo-transit-line2); }
}
