  & .chip { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px; border-radius: 99px; font-size: 12px; font-weight: 600; color: var(--amo-transit-faint); box-shadow: inset 0 0 0 1px var(--amo-transit-line2); text-decoration: line-through; transition: background .15s, color .15s; }
