  & .chip:hover { background: var(--amo-transit-hover); }
  & .chip i { width: 10px; height: 10px; border-radius: 3px; background: currentColor; }
  & .chip i.m-tram, & .chip i.m-bus { border-radius: 50%; }
  & .chip[aria-pressed="true"] i.m-metro { background: oklch(0.57 0.2 27); } & .chip[aria-pressed="true"] i.m-rail { background: oklch(0.55 0.13 152); }
  & .chip[aria-pressed="true"] i.m-tram { background: oklch(0.6 0.1 210); } & .chip[aria-pressed="true"] i.m-bus { background: oklch(0.55 0.17 345); }
  & .sw svg { width: 14px; height: 14px; }
  & .sw[aria-checked="true"] { background: var(--amo-transit-ink); color: var(--amo-transit-paper); box-shadow: none; }
}
.amo-transit .amo-transit-tabs {
  display: flex; align-items: flex-end; gap: 16px; padding: 0 18px; border-bottom: 1px solid var(--amo-transit-line);
  & [role="tab"] { position: relative; padding: 10px 0 9px; font-weight: 700; color: var(--amo-transit-faint); }
  & [role="tab"]::after { content: ""; position: absolute; left: 0; right: 0; bottom: -1px; height: 2.5px; border-radius: 2px; background: var(--amo-transit-ink); scale: 0 1; transition: scale .35s var(--amo-transit-ease); }
  & [role="tab"][aria-selected="true"] { color: var(--amo-transit-ink); }
  & [role="tab"][aria-selected="true"]::after { scale: 1 1; }
  & [role="tab"]:hover { color: var(--amo-transit-ink); }
}
.amo-transit .amo-transit-sort {
  margin-left: auto; display: flex; gap: 2px; padding-bottom: 7px;
  & button { padding: 3px 7px; border-radius: 6px; font-size: 11.5px; font-weight: 600; color: var(--amo-transit-faint); white-space: nowrap; }
  & button:hover { color: var(--amo-transit-ink); }
  & [aria-checked="true"] { color: var(--amo-transit-ink); background: var(--amo-transit-well); box-shadow: inset 0 0 0 1px var(--amo-transit-line); }
}
.amo-transit .amo-transit-results { flex: 1; min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; padding: 0 12px 14px; }
.amo-transit .amo-transit-keys {
  display: flex; flex-wrap: wrap; gap: 4px 12px; padding: 8px 18px 10px; border-top: 1px solid var(--amo-transit-line); font-size: 11px; color: var(--amo-transit-faint);
  & span { display: inline-flex; align-items: center; gap: 3px; }
}

/* shared time axis */
.amo-transit .amo-transit-axis {
  position: sticky; top: 0; z-index: 2; height: 26px; margin: 0 12px; background: linear-gradient(var(--amo-transit-paper) 80%, transparent);
  & span { position: absolute; top: 8px; translate: -50% 0; font: 600 10px/1 ui-monospace, Menlo, monospace; color: var(--amo-transit-faint); font-variant-numeric: tabular-nums; }
  & span::after { content: ""; position: absolute; left: 50%; top: 13px; width: 1px; height: 5px; background: var(--amo-transit-line2); }
}
.amo-transit .amo-transit-opts { display: grid; gap: 6px; }
.amo-transit .amo-transit-opt {
  position: relative; display: grid; gap: 7px; padding: 11px 12px 10px; border-radius: 12px; cursor: pointer; outline-offset: -2px;
  box-shadow: inset 0 0 0 1px var(--amo-transit-line); transition: background .15s, box-shadow .2s;
  animation: amo-transit-in .45s var(--amo-transit-ease) backwards; animation-delay: calc(var(--i, 0) * 45ms);
  &:hover { background: var(--amo-transit-hover); }
  &[aria-selected="true"] { background: var(--amo-transit-paper); box-shadow: inset 0 0 0 2px var(--amo-transit-ink), 0 8px 20px -14px var(--amo-transit-line2); }
  & .top { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
  & .tt { display: flex; align-items: baseline; gap: 6px; font-variant-numeric: tabular-nums; }
  & .tt b { font-size: 18px; font-weight: 780; letter-spacing: -.03em; }
  & .tt i { font-style: normal; color: var(--amo-transit-faint); }
  & .dur { font-size: 12px; color: var(--amo-transit-mute); }
  & .dur b { font-size: 15px; font-weight: 750; color: var(--amo-transit-ink); font-variant-numeric: tabular-nums; }
  & .track { position: relative; height: 8px; background: linear-gradient(var(--amo-transit-line), var(--amo-transit-line)) 0 50% / 100% 1px no-repeat; }
  & .bar { position: absolute; top: 0; bottom: 0; display: flex; gap: 0; }
  & .seg + .seg { margin-left: 2px; }
  & .seg { height: 8px; border-radius: 4px; background: var(--c); min-width: 3px; transform-origin: left; animation: amo-transit-grow .6s var(--amo-transit-ease) backwards; animation-delay: calc(var(--i, 0) * 45ms + 120ms); }
  & .seg.wait { background: repeating-linear-gradient(90deg, var(--amo-transit-line2) 0 2px, transparent 2px 4px); height: 4px; margin-top: 2px; border-radius: 2px; }
  & .seg.walk { background: radial-gradient(circle, var(--amo-transit-faint) 1.3px, transparent 1.6px) 0 50% / 5px 5px repeat-x; }
  & .meta { display: flex; align-items: center; gap: 5px; flex-wrap: wrap; }
  & .sep { width: 6px; height: 1.5px; background: var(--amo-transit-line2); }
  & .w { display: inline-flex; align-items: center; font-size: 11.5px; color: var(--amo-transit-mute); font-variant-numeric: tabular-nums; }
  & .w svg { width: 14px; height: 14px; }
  & .sp { flex: 1; }
  & .tag { font-size: 11px; font-weight: 650; color: var(--amo-transit-mute); padding: 1px 6px; border-radius: 5px; background: var(--amo-transit-well); white-space: nowrap; }
  & .tag.hi { color: oklch(0.42 0.12 150); background: color-mix(in oklch, oklch(0.62 0.15 150) 14%, var(--amo-transit-paper)); }
  & .tag.bad { color: var(--amo-transit-warn); background: color-mix(in oklch, var(--amo-transit-warn) 10%, var(--amo-transit-paper)); }
  & .fare { font-weight: 700; font-variant-numeric: tabular-nums; }
  & .leave { font-size: 11.5px; color: var(--amo-transit-mute); }
}
@keyframes amo-transit-in { from { opacity: 0; translate: 0 8px; } }
@keyframes amo-transit-grow { from { scale: 0 1; } }
.amo-transit .amo-transit-more { width: 100%; margin-top: 8px; padding: 10px; border-radius: 10px; font-weight: 650; color: var(--amo-transit-accent); &:hover { background: var(--amo-transit-tint); } }
.amo-transit .amo-transit-empty { display: grid; justify-items: center; gap: 8px; padding: 40px 20px; text-align: center; color: var(--amo-transit-mute); text-wrap: pretty; & svg { width: 26px; height: 26px; color: var(--amo-transit-warn); } }

/* line badges: metro square, rail rectangle, tram circle, bus pill */
.amo-transit .amo-transit-badge {
  display: inline-grid; place-items: center; min-width: 26px; height: 22px; padding: 0 5px; border-radius: 5px; flex: none;
  background: var(--c); color: white; font: 800 12px/1 system-ui, sans-serif; letter-spacing: -.01em;
  &.dk { color: oklch(0.2 0.03 80); }
  &.m-rail { border-radius: 2px; min-width: 30px; }
  &.m-tram { border-radius: 50%; min-width: 22px; padding: 0; }
  &.m-bus { border-radius: 99px; background: var(--amo-transit-paper); color: var(--c); box-shadow: inset 0 0 0 2px var(--c); }
  &.sm { min-width: 22px; height: 18px; font-size: 10.5px; }
  &.sm.m-tram { min-width: 18px; } &.sm.m-rail { min-width: 25px; }
}

/* departures board */
.amo-transit .amo-transit-board {
  display: grid; gap: 2px; padding-top: 10px;
  & h3 { padding: 2px 6px 8px; font-size: 11px; font-weight: 750; letter-spacing: .09em; text-transform: uppercase; color: var(--amo-transit-faint); }
  & .dep { border-radius: 10px; transition: background .15s; }
  & .dep.open { background: var(--amo-transit-well); }
  & .row { display: grid; grid-template-columns: 52px auto minmax(0, 1fr) auto 16px; align-items: center; gap: 10px; width: 100%; padding: 8px 8px; border-radius: 10px; text-align: left; animation: amo-transit-in .4s var(--amo-transit-ease) backwards; animation-delay: calc(var(--i, 0) * 30ms); }
  & .row:hover { background: var(--amo-transit-hover); }
  & .row > svg { color: var(--amo-transit-faint); transition: rotate .3s var(--amo-transit-ease); }
  & .row[aria-expanded="true"] > svg { rotate: 180deg; }
  & .t { display: grid; font-variant-numeric: tabular-nums; }
  & .t b { font: 750 14px/1.1 ui-monospace, Menlo, monospace; }
  & .t s { font-size: 11px; color: var(--amo-transit-faint); }
  & .to { min-width: 0; font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .to small { display: block; font-weight: 500; font-size: 11.5px; color: var(--amo-transit-mute); }
  & .to em { font-style: normal; color: var(--amo-transit-warn); font-weight: 650; }
  & .in { font-size: 12px; font-weight: 650; color: var(--amo-transit-accent); white-space: nowrap; }
  & .calls { padding: 0 12px 10px 70px; }
}
.amo-transit .calls {
  display: grid; gap: 3px; font-size: 12.5px;
  & li { display: grid; grid-template-columns: 46px 1fr; color: var(--amo-transit-mute); animation: amo-transit-in .3s var(--amo-transit-ease) backwards; }
  & li span { font-variant-numeric: tabular-nums; color: var(--amo-transit-faint); }
}

/* ── main: map + itinerary ────────────────────────── */
.amo-transit .amo-transit-main { grid-area: main; min-width: 0; min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; }
.amo-transit .amo-transit-map { padding: 10px 14px 0; background: linear-gradient(var(--amo-transit-well), var(--amo-transit-paper)); border-bottom: 1px solid var(--amo-transit-line); }
.amo-transit .amo-transit-svg {
  display: block; width: 100%; height: auto; max-height: 300px; fill: none; stroke: none;
  & .ln { fill: none; stroke: var(--c); stroke-width: 6; stroke-linecap: round; stroke-linejoin: round; }
  & .wk { fill: none; stroke: var(--amo-transit-faint); stroke-width: 2.5; stroke-dasharray: 1 5; stroke-linecap: round; }
  & .dim { opacity: .2; transition: opacity .4s; }
  & .hi .ln.on { stroke-width: 7; stroke-dasharray: 1 1; animation: amo-transit-draw .7s var(--amo-transit-ease) backwards; animation-delay: calc(var(--i, 0) * 260ms); }
  & .hi .wk.on { stroke: var(--amo-transit-ink); }
  & .st { cursor: pointer; outline: none; }
  & .st .hit { fill: transparent; }
  & .st .ring { fill: var(--amo-transit-paper); stroke: var(--amo-transit-ink); stroke-width: 2.6; transition: stroke-width .2s; }
  & .st .dot { fill: var(--amo-transit-paper); stroke: var(--c); stroke-width: 3; }
  & .st text { font: 650 11.5px/1 system-ui, sans-serif; fill: var(--amo-transit-ink); paint-order: stroke; stroke: var(--amo-transit-paper); stroke-width: 4px; stroke-linejoin: round; transition: fill .2s; }
  & .st.off text { fill: var(--amo-transit-faint); font-weight: 500; }
  & .st .role { fill: none; stroke: var(--amo-transit-accent); stroke-width: 2.5; stroke-dasharray: 3 3; transform-box: fill-box; transform-origin: center; animation: amo-transit-spin 8s linear infinite; }
  & .st.from .role { stroke: var(--amo-transit-ink); }
  & .st:hover text, & .st:focus-visible text { fill: var(--amo-transit-accent); }
  & .st:hover .ring, & .st:focus-visible .ring { stroke-width: 4; }
}
@keyframes amo-transit-draw { from { stroke-dashoffset: 1; } }
@keyframes amo-transit-spin { to { rotate: 360deg; } }
.amo-transit .amo-transit-ihead {
  position: sticky; top: 0; z-index: 3; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: end; gap: 12px; padding: 14px 20px 12px;
  background: color-mix(in oklch, var(--amo-transit-paper) 94%, transparent); backdrop-filter: blur(6px); border-bottom: 1px solid var(--amo-transit-line);
  & .k { font-size: 11px; font-weight: 750; letter-spacing: .08em; text-transform: uppercase; color: var(--amo-transit-faint); }
  & h2 { display: flex; align-items: baseline; gap: 10px; font-size: clamp(24px, 3cqi, 32px); font-weight: 800; letter-spacing: -.04em; line-height: 1.05; font-variant-numeric: tabular-nums; }
  & h2 i { font-style: normal; font-weight: 400; color: var(--amo-transit-faint); }
  & p { color: var(--amo-transit-mute); font-variant-numeric: tabular-nums; text-wrap: pretty; }
  & p b { color: var(--amo-transit-ink); }
  & .acts { display: flex; gap: 4px; }
  & .acts button { display: grid; justify-items: center; gap: 2px; min-width: 52px; padding: 6px 6px 5px; border-radius: 10px; font-size: 11px; font-weight: 650; color: var(--amo-transit-mute); }
  & .acts button:hover { background: var(--amo-transit-hover); color: var(--amo-transit-ink); }
  & .acts svg { width: 18px; height: 18px; color: var(--amo-transit-ink); }
  & .acts [aria-pressed="true"] { color: var(--amo-transit-accent); }
  & .acts [aria-pressed="true"] svg { color: var(--amo-transit-accent); fill: color-mix(in oklch, var(--amo-transit-accent) 25%, transparent); }
}
.amo-transit .amo-transit-back { display: none; }
.amo-transit .amo-transit-alert { display: flex; gap: 8px; align-items: flex-start; margin: 12px 20px 0; padding: 9px 12px; border-radius: 10px; background: color-mix(in oklch, var(--amo-transit-warn) 9%, var(--amo-transit-paper)); color: color-mix(in oklch, var(--amo-transit-warn), black 25%); font-size: 12.5px; text-wrap: pretty; & svg { margin-top: 1px; } }
.amo-transit .amo-transit-legs {
  padding: 14px 20px 24px;
  & > li { position: relative; display: grid; grid-template-columns: 54px 22px minmax(0, 1fr); gap: 10px; }
  & .time { padding-top: 2px; text-align: right; font-size: 11.5px; color: var(--amo-transit-faint); font-variant-numeric: tabular-nums; }
  & .time b { font: 750 14px/1.2 ui-monospace, Menlo, monospace; color: var(--amo-transit-ink); }
  & .rail { position: relative; justify-self: center; width: 22px; }
  & > li > div { min-width: 0; padding-bottom: 14px; }
  & > li > div > b { display: block; font-weight: 700; font-size: 14px; }
  & small { display: flex; align-items: center; gap: 4px; flex-wrap: wrap; font-size: 12px; color: var(--amo-transit-mute); }
  & small svg { width: 13px; height: 13px; }
  & .stop .rail::before { content: ""; position: absolute; left: 50%; top: 3px; width: 14px; height: 14px; translate: -50% 0; border-radius: 50%; background: var(--amo-transit-paper); box-shadow: inset 0 0 0 3.5px var(--amo-transit-ink); z-index: 1; }
  & .stop.start .rail::before, & .stop.end .rail::before { width: 16px; height: 16px; box-shadow: inset 0 0 0 5px var(--amo-transit-ink); }
  & .stop > div { padding-bottom: 10px; }
  & .ride .rail::before { content: ""; position: absolute; left: 50%; top: -14px; bottom: -4px; width: 7px; translate: -50% 0; border-radius: 4px; background: var(--c); }
  & .ride .line { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
  & .ride .line b { font-weight: 650; }
  & .ride em { font-style: normal; font-size: 12px; font-weight: 700; color: var(--amo-transit-warn); }
  & .ride em.ok { color: oklch(0.5 0.12 150); font-weight: 600; }
  & .ride .time { padding-top: 4px; }
  & .calls-t { display: inline-flex; align-items: center; gap: 4px; margin-top: 4px; padding: 3px 6px 3px 2px; border-radius: 6px; font-size: 12px; color: var(--amo-transit-mute); }
  & .calls-t:hover { color: var(--amo-transit-ink); background: var(--amo-transit-hover); }
  & .calls-t svg { width: 14px; height: 14px; transition: rotate .3s var(--amo-transit-ease); }
  & .calls-t[aria-expanded="true"] svg { rotate: 180deg; }
  & .ride .calls { margin-top: 6px; position: relative; }
  & .ride small { margin-top: 3px; }
  & .chg .rail::before, & .walk .rail::before { content: ""; position: absolute; left: 50%; top: -8px; bottom: 0; translate: -50% 0; border-left: 3px dotted var(--amo-transit-line2); }
  & .chg > div, & .walk > div { padding: 2px 0 14px; }
  & .chg b, & .walk b { font-size: 13px !important; font-weight: 650 !important; }
  & .walk > div { display: grid; grid-template-columns: auto 1fr; column-gap: 6px; }
  & .walk > div svg { grid-row: span 2; width: 18px; height: 18px; color: var(--amo-transit-mute); }
}
.amo-transit .amo-transit-none { display: grid; justify-items: center; gap: 10px; padding: 40px; color: var(--amo-transit-mute); & svg { width: 28px; height: 28px; } }

/* toast */
.amo-transit .amo-transit-toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 9; translate: -50% 0; max-width: calc(100% - 32px); padding: 10px 16px; border-radius: 10px;
  background: var(--amo-transit-ink); color: var(--amo-transit-paper); font-weight: 550; box-shadow: 0 16px 36px -12px color-mix(in oklch, var(--amo-transit-ink) 55%, transparent);
  transition: opacity .25s, translate .45s var(--amo-transit-spring); @starting-style { opacity: 0; translate: -50% 12px; }
}

/* ── responsive ───────────────────────────────────── */
@container (max-width: 959px) {
  .amo-transit .amo-transit-app { grid-template-columns: 340px minmax(0, 1fr); }
  .amo-transit .amo-transit-when { flex-wrap: wrap; }
  .amo-transit .amo-transit-seg { flex-basis: 100%; }
  .amo-transit .amo-transit-step { flex: 1; justify-content: space-between; }
  .amo-transit .amo-transit-sort button:nth-child(3) { display: none; }
  .amo-transit .amo-transit-keys { display: none; }
  .amo-transit .amo-transit-ihead .acts span { display: none; }
  .amo-transit .amo-transit-ihead .acts button { min-width: 36px; }
}
@container (max-width: 759px) {
  .amo-transit .amo-transit-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "one"; }
  .amo-transit .amo-transit-side, .amo-transit .amo-transit-main { grid-area: one; border: 0; }
  .amo-transit[data-view="list"] .amo-transit-main { display: none; }
  .amo-transit[data-view="detail"] .amo-transit-side { display: none; }
  .amo-transit .amo-transit-back { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 10px; margin-left: -6px; background: var(--amo-transit-well); grid-row: 1; }
  .amo-transit .amo-transit-ihead { grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; padding: 12px 16px; }
  .amo-transit .amo-transit-legs { padding: 14px 16px 24px; }
  .amo-transit .amo-transit-when { flex-wrap: nowrap; }
  .amo-transit .amo-transit-seg { flex-basis: auto; }
  .amo-transit .amo-transit-step { flex: none; }
}
@container (max-width: 420px) {
  .amo-transit .amo-transit-seg button { font-size: 11px; }
  .amo-transit .amo-transit-tabs { gap: 12px; padding: 0 14px; }
  .amo-transit .amo-transit-form, .amo-transit .amo-transit-brand { padding-left: 14px; padding-right: 14px; }
  .amo-transit .amo-transit-ihead .acts { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .amo-transit {
    & *, & *::before, & *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
    & .amo-transit-svg .st .role { animation: none; }
    & .amo-transit-now i { animation: none; }
  }
}

