/* ── Meridian · journey planner over a real timetable ─────────────────────
   Five lines run on headways with fixed offsets and today's delays, and the
   planner is a small RAPTOR: round k scans every route touched in round k-1
   for the earliest trip it can still catch (with change time and the
   step-free rule), then relaxes walking links. Each round that improves the
   arrival is a journey with one more change, and re-running just after the
   earliest boarding gives later departures. The options share one time axis,
   so their bars compare at a glance, and the network diagram lights the
   chosen path. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const hm = m => { m = Math.round(m); return String(Math.floor(m / 60) % 24).padStart(2, '0') + ':' + String(((m % 60) + 60) % 60).padStart(2, '0'); };
const ico = p => '<svg viewBox="0 0 24 24" aria-hidden="true">' + p + '</svg>';
const I = {
  walk: '<circle cx="13" cy="4.5" r="1.8"/><path d="m9 21 2.5-6 3 2.5V21M7.5 11.5 10.5 8h3.5l2.5 4 2.5.8M11.5 15l-1-5"/>',
  star: '<path d="m12 3.2 2.7 5.6 6.1.8-4.5 4.2 1.1 6-5.4-2.9-5.4 2.9 1.1-6L3.2 9.6l6.1-.8Z"/>',
  bell: '<path d="M6 16.5V11a6 6 0 0 1 12 0v5.5l1.5 2h-15Z"/><path d="M10 20.5a2 2 0 0 0 4 0"/>',
  share: '<path d="M12 15V4M8 7.5 12 3.5l4 4"/><path d="M6 11v8.5h12V11"/>',
  chev: '<path d="m6 9 6 6 6-6"/>',
  back: '<path d="M15 6 9 12l6 6"/>',
  lift: '<rect x="5" y="3.5" width="14" height="17" rx="2"/><path d="m9 9 3-3 3 3M9 15l3 3 3-3"/>',
