  .amo-scoot .amo-scoot-sheet::before { content: ""; justify-self: center; width: 40px; height: 4px; border-radius: 2px; background: var(--amo-scoot-line2); margin: -6px 0 -4px; }
  .amo-scoot .amo-scoot-toast { top: 58px; }
  .amo-scoot .amo-scoot-keys { display: none; }
}
@container (max-width: 420px) {
  .amo-scoot .amo-scoot-filters button svg { display: none; }
  .amo-scoot .amo-scoot-facts dd { font-size: 13px; }
}

@media (prefers-reduced-motion: reduce) {
  .amo-scoot {
    & *, & *::before, & *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
