/* ── Wisp · scooter and e-bike rental ─────────────────────────────────────
   Zones are polygons and every rule is a point-in-polygon test against the
   vehicle's live position: inside the Old Town slow zone the speed is capped
   at 10 km/h, and End ride only unlocks inside a parking bay. Unlocking is a
   press-and-hold: a registered <angle> custom property sweeps the ring in
   CSS while a timer waits for the hold to complete, and letting go early
   springs it back. The ride runs on a simulated clock (20× real time) in a
   rAF loop that stops off screen or in a hidden tab, and the fare, distance
   and battery are all integrated from the same movement. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
