const gbp = p => '£' + (p / 100).toFixed(2);
const hm = m => { m = Math.floor(m); return String(Math.floor(m / 60) % 24).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0'); };
const ms = m => { const s = Math.floor(m * 60); return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0'); };
const ico = p => '<svg viewBox="0 0 24 24" aria-hidden="true">' + p + '</svg>';
