const node = (i, j) => ({ x: NX(i), y: NY(j) });
const SIM = 1 / 3;                         /* simulated minutes per real second (20×) */
const SPEED = { open: 18, slow: 10 };      /* km/h */
const UPM = kmh => kmh * 1000 / 60 / M_PER_U;   /* units per minute */
const rect = (cx, cy, w, h) => [{ x: cx - w / 2, y: cy - h / 2 }, { x: cx + w / 2, y: cy - h / 2 }, { x: cx + w / 2, y: cy + h / 2 }, { x: cx - w / 2, y: cy + h / 2 }];
const ZONES = [
