const SLOW = { name: 'Old Town', poly: [node(4, 2.5), { x: NX(5), y: NY(1.6) }, { x: NX(7.4), y: NY(1.7) }, node(8.4, 2.8), node(8.2, 4.6), { x: NX(6.3), y: NY(5.3) }, node(4.3, 4.8), { x: NX(3.6), y: NY(3.6) }] };
