const PAUSE_RATE = 8;
const FLEET = [
  ['WSP-2186', 'scooter', 5, 3, 82], ['WSP-1043', 'scooter', 2, 4, 46], ['WSP-3317', 'ebike', 7, 2, 91], ['WSP-2954', 'scooter', 8, 5, 17],
  ['WSP-1702', 'ebike', 4, 6, 64], ['WSP-3561', 'scooter', 10, 4, 73], ['WSP-1280', 'scooter', 1, 2, 55], ['WSP-3049', 'ebike', 11, 7, 38],
  ['WSP-2417', 'scooter', 7, 8, 88], ['WSP-1876', 'scooter', 9, 1, 8], ['WSP-3390', 'ebike', 3, 7, 77], ['WSP-2603', 'scooter', 12, 3, 69],
