const ME = { x: NX(5) + 30, y: NY(4) };
const ROWN = ['Kiln Row', 'Station Road', 'Fennel Street', 'Corn Street', 'Abbey Street', 'Tanner Lane', 'Vale Road', 'Moor Lane', 'Wharf Road', 'Lock Street'];
const streetOf = p => { const z = zoneAt(p); return z ? z.name : ROWN[Math.max(0, Math.min(9, Math.round((p.y - 30) / 72)))]; };
function inside(p, q) {
  let r = false;
  for (let i = 0, j = q.length - 1; i < q.length; j = i++) if ((q[i].y > p.y) !== (q[j].y > p.y) && p.x < (q[j].x - q[i].x) * (p.y - q[i].y) / (q[j].y - q[i].y) + q[i].x) r = !r;
  return r;
}
const zoneAt = p => ZONES.find(z => inside(p, z.poly));
const walkM = (a, b) => (Math.abs(a.x - b.x) + Math.abs(a.y - b.y)) * M_PER_U;
const range = v => v.bat * T[v.t].kmPer;

/* streets only: go along the street you are on, then turn onto the target's */
function pathTo(p, q) {
  const onRow = Math.abs(((p.y - 30) / 72) - Math.round((p.y - 30) / 72)) < .02;
  const c = onRow ? { x: q.x, y: p.y } : { x: p.x, y: q.y };
  return [p, c, q].filter((pt, i, a) => !i || Math.hypot(pt.x - a[i - 1].x, pt.y - a[i - 1].y) > .5);
}

/* ── state ───────────────────────────────────────────────────────────── */
