const svg = $('[data-svg]'), mapEl = $('[data-map]'), sheet = $('[data-sheet]');

/* ── map drawing ─────────────────────────────────────────────────────── */
const P = q => q.map((p, i) => (i ? 'L' : 'M') + p.x.toFixed(1) + ' ' + p.y.toFixed(1)).join('') + 'Z';
function rng(a) { return () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
function drawBase() {
  const R = rng(5);
