  const PARK = (i, j) => i >= 5 && i <= 6 && j >= 6 && j <= 7 || (i === 0 && j === 5);
  for (let i = -8; i < 20; i++) for (let j = -6; j < 16; j++) {
    const x0 = NX(i) + 9, y0 = NY(j) + 9, w = 75 - 18, hh = 72 - 18;
    if (PARK(i, j)) { pk += '<rect class="m-park" x="' + (x0 - 4) + '" y="' + (y0 - 4) + '" width="' + (w + 8) + '" height="' + (hh + 8) + '" rx="6"/>'; continue; }
    bl += '<rect class="m-blk" style="--l:' + (R() * 3.5).toFixed(2) + '%" x="' + x0 + '" y="' + y0 + '" width="' + w + '" height="' + hh + '" rx="3"/>';
    /* building footprints: a 2 × 2 split with a few courtyards left open */
    for (let a = 0; a < 2; a++) for (let c = 0; c < 2; c++) {
      if (R() < .22) continue;
      const bw = (w - 9) / 2, bh = (hh - 9) / 2;
      bl += '<rect class="m-bld" x="' + (x0 + 3 + a * (bw + 3)).toFixed(1) + '" y="' + (y0 + 3 + c * (bh + 3)).toFixed(1) + '" width="' + (bw * (R() < .3 ? .7 : 1)).toFixed(1) + '" height="' + bh.toFixed(1) + '" rx="1.5"/>';
    }
  }
  h += bl + pk;
  /* Moor Park merges two blocks into one; paths cross it */
  h += '<rect class="m-park" x="' + (NX(5) + 5) + '" y="' + (NY(6) + 5) + '" width="' + (150 - 10) + '" height="' + (144 - 10) + '" rx="10"/>';
  h += '<path class="m-trail" d="M' + (NX(5) + 8) + ' ' + (NY(7) + 30) + 'C' + (NX(6)) + ' ' + (NY(6) + 20) + ' ' + (NX(6) + 10) + ' ' + (NY(8) - 10) + ' ' + (NX(7) - 8) + ' ' + (NY(6) + 40) + '"/>';
  /* main streets glow a little brighter */
  let ms = '';
  [3, 6].forEach(j => ms += 'M-800 ' + NY(j) + 'H1800');
