  const lab = (x, y, t, r) => '<text class="m-lbl" x="' + x + '" y="' + y + '"' + (r ? ' transform="rotate(-90 ' + x + ' ' + y + ')"' : '') + ' text-anchor="middle">' + t + '</text>';
  h += lab(NX(1.5), NY(3) + 3.5, 'CORN STREET') + lab(NX(10.5), NY(6) + 3.5, 'VALE ROAD') + lab(NX(4) + 3.5, NY(7.5), 'HIGH STREET', 1) + lab(NX(9) + 3.5, NY(2.5) - 10, 'MILL LANE', 1);
  h += '<text class="m-lbl park" x="' + NX(6) + '" y="' + (NY(7) + 4) + '" text-anchor="middle">MOOR PARK</text>';
