  const rw = r.width - sw, rh = r.height - sh - 56;
  const k = Math.max(MW / rw, MH / rh) * (narrow ? .8 : .96);   /* units per pixel: fit the district into the free region */
  const vb = { w: r.width * k, h: r.height * k };
