const walkTxt = m => Math.round(m / 10) * 10 + ' m · ' + Math.max(1, Math.round(m / 80)) + ' min walk';
function batBar(v) { return '<div class="amo-scoot-bat' + (v.bat < 20 ? ' low' : '') + '" style="--b:' + v.bat + '%"><i></i><span><b>' + v.bat + '%</b> · ' + Math.round(range(v)) + ' km range</span></div>'; }
