  --amo-park-mute: color-mix(in oklch, var(--amo-park-ink) 60%, var(--amo-park-bg));
  --amo-park-faint: color-mix(in oklch, var(--amo-park-ink) 40%, var(--amo-park-bg));
  --amo-park-tint: color-mix(in oklch, var(--amo-park-accent) 10%, var(--amo-park-card));
  --amo-park-warn: oklch(0.6 0.19 32);
