  position: relative; width: 100%; height: var(--amo-park-h, 680px); box-sizing: border-box;
  container-type: inline-size; overflow: clip; isolation: isolate; display: flex; flex-direction: column; border-radius: 18px;
  background: var(--amo-park-bg); color: var(--amo-park-ink); color-scheme: light; accent-color: var(--amo-park-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; box-shadow: inset 0 0 0 1px var(--amo-park-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--amo-park-accent); outline-offset: 2px; }
