  & kbd { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 4px; font: 650 10px/1 ui-monospace, Menlo, monospace; color: var(--amo-park-mute); background: var(--amo-park-card); box-shadow: inset 0 0 0 1px var(--amo-park-line2); }
  & .k { font-size: 10.5px; font-weight: 750; letter-spacing: .09em; text-transform: uppercase; color: var(--amo-park-faint); }
}
