.amo-park .amo-park-app {
  flex: 1; min-height: 0; display: grid;
  grid-template-columns: clamp(270px, 26cqi, 310px) minmax(0, 1fr) clamp(290px, 28cqi, 330px); grid-template-areas: "list plan pay";
}

/* ── list ─────────────────────────────────────────── */
.amo-park .amo-park-list { grid-area: list; min-height: 0; display: flex; flex-direction: column; gap: 10px; padding: 16px 0 0; border-right: 1px solid var(--amo-park-line); }
.amo-park .amo-park-brand {
  display: flex; align-items: center; gap: 10px; padding: 0 16px;
  & b { display: block; font-size: 16px; font-weight: 800; letter-spacing: -.03em; line-height: 1.1; }
  & small { display: block; font-size: 11.5px; color: var(--amo-park-mute); font-variant-numeric: tabular-nums; }
}
.amo-park .amo-park-p { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 9px; background: var(--amo-park-accent); color: white; font-weight: 900; font-size: 20px; box-shadow: inset 0 0 0 2.5px color-mix(in oklch, white 85%, transparent), 0 0 0 1px var(--amo-park-accent); }
.amo-park .amo-park-sorts {
  display: grid; grid-template-columns: repeat(3, 1fr); margin: 4px 16px 0; padding: 3px; border-radius: 10px; background: color-mix(in oklch, var(--amo-park-ink) 5%, var(--amo-park-bg));
  & button { height: 28px; border-radius: 7px; font-size: 12px; font-weight: 650; color: var(--amo-park-mute); }
  & [aria-checked="true"] { background: var(--amo-park-card); color: var(--amo-park-ink); box-shadow: 0 1px 2px var(--amo-park-line2); }
}
.amo-park .amo-park-feats {
  display: flex; gap: 6px; padding: 0 16px; flex-wrap: wrap;
  & button { display: inline-flex; align-items: center; gap: 5px; height: 28px; padding: 0 10px; border-radius: 99px; font-size: 12px; font-weight: 600; color: var(--amo-park-mute); box-shadow: inset 0 0 0 1px var(--amo-park-line2); transition: background .15s, color .15s; }
  & button svg { width: 13px; height: 13px; }
  & button:hover { background: var(--amo-park-hover); }
  & [aria-pressed="true"] { background: var(--amo-park-ink); color: var(--amo-park-bg); box-shadow: none; }
}
.amo-park .amo-park-cards { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: thin; display: grid; align-content: start; gap: 8px; padding: 4px 12px 14px; }
.amo-park .amo-park-card {
  display: grid; gap: 6px; padding: 12px; border-radius: 14px; background: var(--amo-park-card); cursor: pointer; outline-offset: -2px;
  box-shadow: inset 0 0 0 1px var(--amo-park-line); transition: box-shadow .2s, translate .3s var(--amo-park-ease);
  animation: amo-park-in .4s var(--amo-park-ease) backwards; animation-delay: calc(var(--i) * 40ms);
  &:hover { box-shadow: inset 0 0 0 1px var(--amo-park-line2), 0 6px 18px -12px var(--amo-park-line2); }
  &[aria-selected="true"] { box-shadow: inset 0 0 0 2px var(--amo-park-accent); }
  & .t { display: flex; justify-content: space-between; gap: 8px; align-items: baseline; }
  & .t b { font-weight: 700; font-size: 13.5px; line-height: 1.25; text-wrap: balance; }
  & .pr { display: grid; justify-items: end; font-weight: 780; font-size: 15px; font-variant-numeric: tabular-nums; white-space: nowrap; }
  & .pr small { font-size: 10.5px; font-weight: 550; color: var(--amo-park-faint); }
  & .s { display: flex; align-items: center; gap: 4px; font-size: 12px; color: var(--amo-park-mute); }
  & .s svg { width: 13px; height: 13px; }
  & .occ { display: grid; gap: 4px; font-size: 11.5px; color: var(--amo-park-mute); font-variant-numeric: tabular-nums; }
  & .occ i { height: 5px; border-radius: 3px; background: linear-gradient(90deg, var(--amo-park-ev) var(--f), var(--amo-park-line) var(--f)); }
  & .occ b { color: var(--amo-park-ink); }
  & .tags { display: flex; flex-wrap: wrap; gap: 4px; }
  & .tags span { display: inline-flex; align-items: center; gap: 3px; font-size: 11px; padding: 1px 6px; border-radius: 5px; background: var(--amo-park-hover); color: var(--amo-park-mute); }
  & .tags .ev { color: color-mix(in oklch, var(--amo-park-ev), black 20%); background: color-mix(in oklch, var(--amo-park-ev) 12%, var(--amo-park-card)); }
  & .tags svg { width: 11px; height: 11px; }
  &.full .occ b { color: var(--amo-park-warn); }
  &.full .occ i { background: var(--amo-park-line); }
}
@keyframes amo-park-in { from { opacity: 0; translate: 0 6px; } }
.amo-park .amo-park-none { padding: 20px 8px; color: var(--amo-park-mute); text-align: center; }

/* ── plan ─────────────────────────────────────────── */
.amo-park .amo-park-plan { grid-area: plan; min-width: 0; min-height: 0; display: flex; flex-direction: column; }
.amo-park .amo-park-planhead {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; flex-wrap: wrap; padding: 16px 20px 10px;
  & h2 { font-size: clamp(19px, 2.1cqi, 24px); font-weight: 790; letter-spacing: -.035em; line-height: 1.1; text-wrap: balance; }
  & p { font-size: 12px; color: var(--amo-park-mute); }
}
.amo-park .amo-park-levels {
  display: flex; gap: 4px; padding: 3px; border-radius: 12px; background: color-mix(in oklch, var(--amo-park-ink) 5%, var(--amo-park-bg));
  & button { display: grid; justify-items: center; min-width: 54px; padding: 4px 8px; border-radius: 9px; transition: background .2s; }
  & b { font: 800 13px/1.2 ui-monospace, Menlo, monospace; }
  & small { font-size: 10.5px; color: var(--amo-park-mute); font-variant-numeric: tabular-nums; }
  & button:hover { background: var(--amo-park-hover); }
  & [aria-selected="true"] { background: var(--amo-park-card); box-shadow: 0 1px 3px var(--amo-park-line2); }
  & [aria-selected="true"] b { color: var(--amo-park-accent); }
}
.amo-park .amo-park-floor { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: none; display: flex; flex-direction: column; justify-content: center; gap: 14px; padding: 4px 16px; }
.amo-park .amo-park-facts {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(110px, 1fr)); gap: 1px; border-radius: 12px; overflow: hidden; background: var(--amo-park-line); flex: none;
  & div { padding: 8px 12px; background: var(--amo-park-card); }
  & dt { font-size: 10.5px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--amo-park-faint); }
  & dd { font-size: 12.5px; font-weight: 650; font-variant-numeric: tabular-nums; }
}
.amo-park .amo-park-svg {
  width: 100%; height: auto; flex: none; display: block; fill: none; stroke: none;
  & text { font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; }
  & .slab { fill: color-mix(in oklch, var(--amo-park-ink) 5%, var(--amo-park-bg)); stroke: var(--amo-park-line2); stroke-width: 1.5; }
  & .aisle { fill: color-mix(in oklch, var(--amo-park-ink) 9%, var(--amo-park-bg)); }
  & .arrow { stroke: var(--amo-park-card); stroke-width: 2.5; stroke-linecap: round; stroke-linejoin: round; }
  & .arrow.in { stroke: var(--amo-park-ev); stroke-width: 3; }
  & .pillar { fill: var(--amo-park-line2); }
  & .core rect { fill: color-mix(in oklch, var(--amo-park-ink) 12%, var(--amo-park-bg)); }
  & .core .ramp { stroke: color-mix(in oklch, var(--amo-park-ink) 7%, var(--amo-park-bg)); stroke-width: 6; }
  & .core text { font-size: 10px; font-weight: 800; letter-spacing: .1em; fill: var(--amo-park-mute); }
  & .core text.sm { font-size: 9.5px; font-weight: 550; letter-spacing: .02em; }
  & .gate path { stroke: var(--amo-park-ev); stroke-width: 4; stroke-linecap: round; }
  & .gate text { font-size: 9.5px; font-weight: 800; letter-spacing: .12em; fill: var(--amo-park-ev); }
  & .route { stroke: var(--amo-park-accent); stroke-width: 3.5; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 1 1; }
}
.amo-park .amo-park-svg .bay {
  outline: none;
  & .cell { fill: transparent; transition: fill .2s; }
  & .paint { stroke: var(--amo-park-card); stroke-width: 2.2; }
  & .id { font-size: 8.5px; font-weight: 700; fill: var(--amo-park-faint); letter-spacing: .04em; }
  & .car rect:first-child { stroke: color-mix(in oklch, black 25%, transparent); stroke-width: 1; }
  & .car .gl { fill: color-mix(in oklch, black 38%, transparent); }
  & .sym { stroke: var(--amo-park-ev); stroke-width: 2.2; fill: none; }
  &.acc .sym { stroke: var(--amo-park-accent); }
  &.free { cursor: pointer; }
  &.free .cell { fill: color-mix(in oklch, var(--amo-park-ev) 7%, transparent); }
  &.free.ev .cell { fill: color-mix(in oklch, var(--amo-park-ev) 16%, transparent); stroke: color-mix(in oklch, var(--amo-park-ev) 45%, transparent); stroke-width: 1.2; }
  &.free.acc .cell { fill: color-mix(in oklch, var(--amo-park-accent) 9%, transparent); stroke: color-mix(in oklch, var(--amo-park-accent) 35%, transparent); stroke-width: 1.2; stroke-dasharray: 3 2; }
  &.free:hover .cell, &.free:focus-visible .cell { fill: color-mix(in oklch, var(--amo-park-accent) 22%, transparent); }
  &.free:focus-visible .cell { stroke: var(--amo-park-accent); stroke-width: 2; stroke-dasharray: none; }
  &.mine .cell { fill: var(--amo-park-accent); }
  &.mine .id, &.mine .sym { opacity: 0; }
  & .pin circle { fill: var(--amo-park-card); }
  & .pin text { font: 900 15px/1 system-ui, sans-serif; fill: var(--amo-park-accent); }
  & .pin { animation: amo-park-pop .5s var(--amo-park-spring) backwards; }
}
@keyframes amo-park-pop { from { scale: 0; } }
.amo-park .amo-park-legend {
  display: flex; flex-wrap: wrap; align-items: center; gap: 6px 14px; padding: 8px 20px 12px; font-size: 11.5px; color: var(--amo-park-mute);
  & span { display: inline-flex; align-items: center; gap: 5px; }
  & i { width: 12px; height: 16px; border-radius: 3px; }
  & .free { background: color-mix(in oklch, var(--amo-park-ev) 10%, var(--amo-park-card)); box-shadow: inset 0 0 0 1px var(--amo-park-line2); }
  & .taken { background: oklch(0.6 0.02 250); }
  & .ev { background: color-mix(in oklch, var(--amo-park-ev) 22%, var(--amo-park-card)); box-shadow: inset 0 0 0 1px var(--amo-park-ev); }
  & .acc { background: color-mix(in oklch, var(--amo-park-accent) 10%, var(--amo-park-card)); box-shadow: inset 0 0 0 1px var(--amo-park-accent); }
  & .sel { background: var(--amo-park-accent); }
  & .keys { margin-left: auto; color: var(--amo-park-faint); gap: 3px; }
}

/* ── pay panel ────────────────────────────────────── */
.amo-park .amo-park-pay { grid-area: pay; min-height: 0; overflow-y: auto; scrollbar-width: thin; display: grid; align-content: start; gap: 14px; padding: 16px 18px 18px; border-left: 1px solid var(--amo-park-line); background: var(--amo-park-card); }
.amo-park .amo-park-payhead {
  display: grid; gap: 1px;
  & b { font-size: 16px; font-weight: 760; letter-spacing: -.02em; line-height: 1.2; }
  & .bay { font-size: 12.5px; color: var(--amo-park-mute); font-variant-numeric: tabular-nums; }
  & .live { display: inline-flex; align-items: center; gap: 6px; color: var(--amo-park-ev); }
  & .live i { width: 7px; height: 7px; border-radius: 50%; background: currentColor; animation: amo-park-blink 1.6s ease-in-out infinite; }
}
@keyframes amo-park-blink { 50% { opacity: .25; } }
.amo-park .amo-park-veh {
  display: grid; grid-template-columns: 1fr 1fr; gap: 6px;
  & button { display: grid; justify-items: start; gap: 3px; padding: 8px 10px; border-radius: 12px; text-align: left; box-shadow: inset 0 0 0 1px var(--amo-park-line2); transition: box-shadow .2s, background .2s; }
  & button:hover { background: var(--amo-park-hover); }
  & [aria-checked="true"] { box-shadow: inset 0 0 0 2px var(--amo-park-ink); }
  & .plate { padding: 3px 6px; border-radius: 4px; background: oklch(0.92 0.13 95); color: oklch(0.2 0.02 90); font: 800 12px/1 ui-monospace, Menlo, monospace; letter-spacing: .06em; box-shadow: inset 0 0 0 1px oklch(0.2 0.02 90 / .6); }
  & small { font-size: 11px; color: var(--amo-park-mute); }
}
/* the rotary dial: --amo-park-a drives the arc and the knob together */
.amo-park .amo-park-dial {
  position: relative; width: min(236px, 100%); aspect-ratio: 1; justify-self: center; border-radius: 50%; touch-action: none; cursor: grab; outline-offset: 6px;
  transition: --amo-park-a .55s var(--amo-park-spring);
  &.drag { transition: none; cursor: grabbing; }
  & .ring { position: absolute; inset: 0; border-radius: 50%; }
  & .arc { position: absolute; inset: 0; border-radius: 50%; background: conic-gradient(var(--amo-park-accent) var(--amo-park-a), color-mix(in oklch, var(--amo-park-ink) 8%, var(--amo-park-card)) 0); -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 22px), #000 calc(100% - 21px)); mask: radial-gradient(farthest-side, transparent calc(100% - 22px), #000 calc(100% - 21px)); }
  & .ticks { position: absolute; inset: 26px; border-radius: 50%; background: repeating-conic-gradient(from -.6deg, var(--amo-park-faint) 0 1.2deg, transparent 1.2deg 30deg); -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 7px), #000 calc(100% - 6px)); mask: radial-gradient(farthest-side, transparent calc(100% - 7px), #000 calc(100% - 6px)); }
  & .nogo { position: absolute; inset: 0; border-radius: 50%; background: conic-gradient(transparent var(--amo-park-max), color-mix(in oklch, var(--amo-park-warn) 18%, transparent) 0); -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 22px), #000 calc(100% - 21px)); mask: radial-gradient(farthest-side, transparent calc(100% - 22px), #000 calc(100% - 21px)); }
  & .knob { position: absolute; inset: 0; rotate: var(--amo-park-a); pointer-events: none; }
  & .knob i { position: absolute; left: 50%; top: 11px; width: 28px; height: 28px; translate: -50% -50%; border-radius: 50%; background: var(--amo-park-card); box-shadow: 0 0 0 4px var(--amo-park-accent), 0 4px 10px -2px color-mix(in oklch, var(--amo-park-ink) 50%, transparent); transition: scale .3s var(--amo-park-spring); }
  &.drag .knob i, &:active .knob i { scale: 1.12; }
  & .mid { position: absolute; inset: 40px; display: grid; place-content: center; justify-items: center; gap: 2px; text-align: center; pointer-events: none; }
  & .d { font-size: clamp(20px, 2.2cqi, 24px); font-weight: 800; letter-spacing: -.035em; font-variant-numeric: tabular-nums; }
  & .u { font-size: 12px; color: var(--amo-park-mute); }
  & .u b { color: var(--amo-park-ink); font-variant-numeric: tabular-nums; }
  & .c { margin-top: 4px; padding: 3px 10px; border-radius: 99px; background: var(--amo-park-tint); color: var(--amo-park-accent); font-weight: 780; font-size: 15px; font-variant-numeric: tabular-nums; }
  & .hr { position: absolute; font-size: 9.5px; font-weight: 700; color: var(--amo-park-faint); pointer-events: none; }
  & .h0 { left: 50%; top: 38px; translate: -50% 0; } & .h1 { right: 40px; top: 50%; translate: 0 -50%; } & .h2 { left: 50%; bottom: 38px; translate: -50% 0; } & .h3 { left: 40px; top: 50%; translate: 0 -50%; }
}
.amo-park .amo-park-quick {
  display: flex; flex-wrap: wrap; justify-content: center; gap: 5px;
  & button { padding: 5px 10px; border-radius: 99px; font-size: 12px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--amo-park-line2); transition: background .15s, color .15s; }
  & button:hover { background: var(--amo-park-hover); }
  & [aria-pressed="true"] { background: var(--amo-park-ink); color: var(--amo-park-bg); box-shadow: none; }
}
.amo-park .amo-park-lines {
  display: grid; gap: 4px; padding: 10px 12px; border-radius: 12px; background: color-mix(in oklch, var(--amo-park-ink) 4%, var(--amo-park-card)); font-size: 12.5px;
  & div { display: flex; justify-content: space-between; gap: 10px; color: var(--amo-park-mute); }
  & div span:last-child { color: var(--amo-park-ink); font-variant-numeric: tabular-nums; }
  & .t { padding-top: 6px; margin-top: 2px; border-top: 1px dashed var(--amo-park-line2); font-weight: 780; color: var(--amo-park-ink); }
}
.amo-park .amo-park-cta {
  display: flex; align-items: center; justify-content: space-between; gap: 10px; width: 100%; padding: 14px 16px; border-radius: 14px; background: var(--amo-park-accent); color: white; font-weight: 750; font-size: 15px;
  transition: background .2s, scale .3s var(--amo-park-spring);
  & span:last-child { font-variant-numeric: tabular-nums; }
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--amo-park-accent), black 14%); }
  &:active:not(:disabled) { scale: .98; }
  &.stop { background: var(--amo-park-ink); justify-content: flex-start; }
  &.stop span:last-child { margin-left: auto; }
}
.amo-park .amo-park-fine { font-size: 11.5px; color: var(--amo-park-mute); text-wrap: pretty; text-align: center; }
/* session timer */
.amo-park .amo-park-timer {
  position: relative; width: min(210px, 100%); aspect-ratio: 1; justify-self: center; transition: --amo-park-left 1s linear;
  & .ring { position: absolute; inset: 0; border-radius: 50%; }
  & .arc { position: absolute; inset: 0; border-radius: 50%; background: conic-gradient(var(--amo-park-ev) var(--amo-park-left), color-mix(in oklch, var(--amo-park-ink) 8%, var(--amo-park-card)) 0); -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 14px), #000 calc(100% - 13px)); mask: radial-gradient(farthest-side, transparent calc(100% - 14px), #000 calc(100% - 13px)); scale: -1 1; }
  & .mid { position: absolute; inset: 24px; display: grid; place-content: center; justify-items: center; text-align: center; gap: 2px; }
  & .mid > b { font: 780 clamp(26px, 2.8cqi, 32px)/1 ui-monospace, Menlo, monospace; letter-spacing: -.04em; font-variant-numeric: tabular-nums; }
  & .mid span { font-size: 12px; color: var(--amo-park-mute); }
  & .mid span b { color: var(--amo-park-ink); }
  &.soon .arc { background: conic-gradient(oklch(0.75 0.16 70) var(--amo-park-left), color-mix(in oklch, var(--amo-park-ink) 8%, var(--amo-park-card)) 0); }
  &.over .arc { background: var(--amo-park-warn); opacity: .85; }
  &.over .mid > b { color: var(--amo-park-warn); }
}
.amo-park .amo-park-banner { padding: 9px 12px; border-radius: 10px; background: color-mix(in oklch, oklch(0.8 0.15 75) 22%, var(--amo-park-card)); font-size: 12.5px; text-wrap: pretty; &.bad { background: color-mix(in oklch, var(--amo-park-warn) 14%, var(--amo-park-card)); color: color-mix(in oklch, var(--amo-park-warn), black 25%); } }
.amo-park .amo-park-stats {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; border-radius: 12px; overflow: hidden; background: var(--amo-park-line);
  & div { padding: 8px 10px; background: var(--amo-park-card); }
  & dt { font-size: 10.5px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--amo-park-faint); }
  & dd { font-weight: 750; font-size: 14px; font-variant-numeric: tabular-nums; }
}
.amo-park .amo-park-pay h3 { font-size: 10.5px; font-weight: 750; letter-spacing: .09em; text-transform: uppercase; color: var(--amo-park-faint); margin-bottom: -6px; }
.amo-park .amo-park-ext {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px;
  & button { display: grid; justify-items: center; padding: 8px 4px; border-radius: 12px; box-shadow: inset 0 0 0 1px var(--amo-park-line2); transition: background .15s; }
  & button:hover:not(:disabled) { background: var(--amo-park-tint); }
  & b { font-weight: 750; } & small { font-size: 11px; color: var(--amo-park-mute); font-variant-numeric: tabular-nums; }
}
.amo-park .amo-park-switches {
  display: grid; gap: 4px;
  & [role="switch"] { display: flex; align-items: center; gap: 8px; padding: 6px 4px; border-radius: 8px; font-size: 12.5px; text-align: left; }
  & [role="switch"]:hover { background: var(--amo-park-hover); }
  & [role="switch"] i { position: relative; width: 30px; height: 18px; border-radius: 99px; background: var(--amo-park-line2); transition: background .2s; flex: none; }
  & [role="switch"] i::after { content: ""; position: absolute; left: 2px; top: 2px; width: 14px; height: 14px; border-radius: 50%; background: white; box-shadow: 0 1px 2px var(--amo-park-line2); transition: translate .3s var(--amo-park-spring); }
  & [aria-checked="true"] i { background: var(--amo-park-ev); }
  & [aria-checked="true"] i::after { translate: 12px 0; }
  & svg { width: 14px; height: 14px; color: var(--amo-park-mute); }
}
.amo-park .amo-park-paid { display: grid; gap: 2px; & .amt { font: 800 40px/1 ui-monospace, Menlo, monospace; letter-spacing: -.05em; } & span:last-child { color: var(--amo-park-mute); } }
.amo-park .amo-park-save { display: flex; gap: 6px; align-items: flex-start; font-size: 12.5px; color: color-mix(in oklch, var(--amo-park-ev), black 20%); text-wrap: pretty; & svg { margin-top: 1px; } }

/* toast */
.amo-park .amo-park-toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 9; translate: -50% 0; max-width: calc(100% - 32px); padding: 10px 16px; border-radius: 10px;
  background: var(--amo-park-ink); color: var(--amo-park-bg); font-weight: 550; box-shadow: 0 16px 36px -12px color-mix(in oklch, var(--amo-park-ink) 55%, transparent);
  transition: opacity .25s, translate .45s var(--amo-park-spring); @starting-style { opacity: 0; translate: -50% 12px; }
}

/* ── responsive ───────────────────────────────────── */
@container (max-width: 959px) {
  .amo-park .amo-park-tabs {
    display: flex; gap: 4px; padding: 8px 10px; border-bottom: 1px solid var(--amo-park-line);
    & button { flex: 1; height: 34px; border-radius: 9px; font-weight: 650; color: var(--amo-park-mute); }
    & button[aria-selected="true"] { background: var(--amo-park-ink); color: var(--amo-park-bg); }
    & [data-view="pay"] { display: none; }
  }
  .amo-park .amo-park-app { grid-template-columns: minmax(0, 1fr) 300px; grid-template-areas: "left pay"; }
  .amo-park .amo-park-list, .amo-park .amo-park-plan { grid-area: left; border: 0; }
  .amo-park[data-view="list"] .amo-park-plan { display: none; }
  .amo-park:not([data-view="list"]) .amo-park-list { display: none; }
  .amo-park .amo-park-legend .keys { display: none; }
}
@container (max-width: 759px) {
  .amo-park .amo-park-tabs [data-view="pay"] { display: block; }
  .amo-park .amo-park-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "left"; }
  .amo-park .amo-park-pay { grid-area: left; border: 0; }
  .amo-park:not([data-view="pay"]) .amo-park-pay { display: none; }
  .amo-park[data-view="pay"] .amo-park-plan { display: none; }
  .amo-park .amo-park-planhead { padding: 12px 14px 8px; }
  .amo-park .amo-park-floor { padding: 4px 6px; }
  .amo-park .amo-park-legend { padding: 6px 14px 10px; gap: 4px 10px; }
  .amo-park .amo-park-facts { grid-template-columns: 1fr 1fr; }
}

@media (prefers-reduced-motion: reduce) {
  .amo-park {
    & *, & *::before, & *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
    & .amo-park-payhead .live i { animation: none; }
  }
}

