/* ── Bayfinder · find a bay, set a duration, run the session ───────────────
   Every car park has a real tariff (stepped hours, a first-hours band, a
   flat hourly rate) with daily caps and maximum stays, and the price on the
   dial, the itemised lines and the end-of-session charge all come from the
   same function, so the lines always sum to the total. The rotary dial is a
   role=slider: one registered <angle> custom property drives both the
   conic-gradient arc and the knob, so keyboard steps glide while dragging
   tracks the pointer exactly. Floor plans are generated per level from a
   seeded PRNG, and the free counts in the list are counted from those bays. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const gbp = p => '£' + (p / 100).toFixed(2);
const hm = m => { m = Math.floor(m); return String(Math.floor(m / 60) % 24).padStart(2, '0') + ':' + String(((m % 60) + 60) % 60).padStart(2, '0'); };
const durTxt = m => { m = Math.round(m); const h = Math.floor(m / 60), r = m % 60; return (h ? h + ' h' : '') + (h && r ? ' ' : '') + (r || !h ? r + ' min' : ''); };
const hms = m => { const s = Math.max(0, Math.round(m * 60)); return Math.floor(s / 3600) + ':' + String(Math.floor(s / 60) % 60).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0'); };
const ico = p => '<svg viewBox="0 0 24 24" aria-hidden="true">' + p + '</svg>';
const I = {
  bolt: '<path d="M13 3 5 13.5h6L10 21l8-10.5h-6Z"/>',
  roof: '<path d="M3 11 12 4l9 7M5.5 9.5V20h13V9.5"/>',
  clock: '<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>',
  acc: '<circle cx="11" cy="4.5" r="1.7"/><path d="M10 8v6h5l2.5 5M10 11h5"/><path d="M8 11.5a5 5 0 1 0 6.5 6.3"/>',
  walk: '<circle cx="13" cy="4.5" r="1.8"/><path d="m9 21 2.5-6 3 2.5V21M7.5 11.5 10.5 8h3.5l2.5 4 2.5.8M11.5 15l-1-5"/>',
  car: '<path d="M5 16.5V12l2-5h10l2 5v4.5"/><path d="M4 12h16v4.5H4z"/><circle cx="7.5" cy="16.5" r="1.6"/><circle cx="16.5" cy="16.5" r="1.6"/>',
  bell: '<path d="M6 16.5V11a6 6 0 0 1 12 0v5.5l1.5 2h-15Z"/><path d="M10 20.5a2 2 0 0 0 4 0"/>',
  chev: '<path d="m6 9 6 6 6-6"/>',
  check: '<path d="m5 12.5 4.5 4.5L19 7.5"/>',
  stop: '<rect x="6.5" y="6.5" width="11" height="11" rx="2"/>',
  plus: '<path d="M12 6v12M6 12h12"/>',
  lift: '<rect x="5" y="3.5" width="14" height="17" rx="2"/><path d="m9 9 3-3 3 3M9 15l3 3 3-3"/>',
  ticket: '<path d="M4 7.5h16v3a2 2 0 0 0 0 3v3H4v-3a2 2 0 0 0 0-3Z"/><path d="M14 7.5v9" stroke-dasharray="1.5 2"/>',
};

/* ── car parks and tariffs (pence, minutes) ──────────────────────────── */
const PARKS = [
  { id: 'halden', name: 'Halden Street Garage', addr: '14 Halden Street', m: 220, levels: ['L-1', 'L0', 'L1'], occ: [.92, .72, .55], ev: 1, cov: 1, h24: 1, t: { kind: 'step', first: 240, next: 180, cap: 1400 }, max: 720, note: 'Open 24 hours' },
  { id: 'corso', name: 'Corso Station Car Park', addr: 'Platform Road', m: 450, levels: ['L0', 'L1', 'L2', 'Roof'], occ: [.96, .86, .7, .38], cov: 1, h24: 1, t: { kind: 'step', first: 300, next: 220, cap: 1800 }, max: 720, note: 'Open 24 hours · roof level uncovered' },
  { id: 'tanner', name: 'Tanner Yard', addr: 'Tanner Street', m: 300, levels: ['Yard'], occ: [.6], t: { kind: 'flat', per: 160 }, max: 240, note: '08:00–20:00 · maximum stay 4 hours' },
  { id: 'river', name: 'Riverside Multi-storey', addr: 'North Quay', m: 680, levels: ['L0', 'L1', 'L2'], occ: [.52, .4, .28], ev: 1, cov: 1, t: { kind: 'band', band: 120, bandP: 350, next: 150, cap: 1200 }, max: 720, note: '06:00–midnight' },
  { id: 'market', name: 'Market Hall Basement', addr: 'Market Hall', m: 900, levels: ['B1', 'B2'], occ: [1, 1], ev: 1, cov: 1, t: { kind: 'hour', per: 280, cap: 1600 }, max: 720, note: '07:00–21:00' },
];
const PB = Object.fromEntries(PARKS.map(p => [p.id, p]));
function tariff(p, m) {
  const t = p.t, L = [], hrs = n => n + ' hour' + (n === 1 ? '' : 's');
  m = Math.max(1, Math.ceil(m));
  if (t.kind === 'step') { L.push(['First hour', t.first]); if (m > 60) { const n = Math.ceil((m - 60) / 60); L.push([hrs(n) + ' more × ' + gbp(t.next), n * t.next]); } }
  else if (t.kind === 'band') { L.push(['Up to 2 hours', t.bandP]); if (m > t.band) { const n = Math.ceil((m - t.band) / 60); L.push([hrs(n) + ' more × ' + gbp(t.next), n * t.next]); } }
  else { const n = Math.ceil(m / 60), per = t.per; L.push([hrs(n) + ' × ' + gbp(per), n * per]); }
  const sum = L.reduce((s, l) => s + l[1], 0);
  if (t.cap && sum > t.cap) L.push(['Daily maximum ' + gbp(t.cap), t.cap - sum]);
  return { lines: L, total: L.reduce((s, l) => s + l[1], 0) };
}
const rateTxt = p => p.t.kind === 'step' ? gbp(p.t.first) + ' first hour' : p.t.kind === 'band' ? gbp(p.t.bandP) + ' up to 2 h' : gbp(p.t.per) + ' per hour';

/* ── floor plans: four rows of twelve bays around two aisles ──────────── */
const BW = 40, BD = 62, X0 = 76;
const ROWS = [{ r: 'A', y: 26, face: 1 }, { r: 'B', y: 150, face: -1 }, { r: 'C', y: 212, face: 1 }, { r: 'D', y: 336, face: -1 }];
const AISLE = { A: 119, B: 119, C: 305, D: 305 };
const COLORS = ['oklch(0.6 0.02 250)', 'oklch(0.45 0.08 255)', 'oklch(0.72 0.01 90)', 'oklch(0.5 0.12 25)', 'oklch(0.35 0.02 250)', 'oklch(0.62 0.06 160)', 'oklch(0.85 0.01 90)', 'oklch(0.55 0.1 60)'];
function rng(a) { return () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
const PLANS = {};
PARKS.forEach((p, pi) => p.levels.forEach((lv, li) => {
  const R = rng(97 + pi * 13 + li * 7), bays = [];
  ROWS.forEach(row => { for (let k = 0; k < 12; k++) {
    const id = row.r + String(k + 1).padStart(2, '0');
    const acc = (row.r === 'A' && k < 2) || (row.r === 'D' && k < 1);
    const ev = !!p.ev && ((row.r === 'D' && k >= 9) || (row.r === 'B' && k >= 10));
    bays.push({ id, row: row.r, k, x: X0 + k * BW, y: row.y, face: row.face, acc, ev, taken: R() < p.occ[li] + (acc ? .1 : 0), color: COLORS[Math.floor(R() * COLORS.length)], tilt: (R() - .5) * 5 });
  } });
  PLANS[p.id + '|' + lv] = bays;
}));
const freeIn = (p, lv) => PLANS[p.id + '|' + lv].filter(b => !b.taken && !b.mine).length;
const freeAll = p => p.levels.reduce((n, lv) => n + freeIn(p, lv), 0);
const evFree = p => p.levels.reduce((n, lv) => n + PLANS[p.id + '|' + lv].filter(b => b.ev && !b.taken).length, 0);
const total = p => p.levels.length * 48;
const ground = p => Math.max(0, p.levels.findIndex(l => /^(L0|Yard|B1)$/.test(l)));

/* ── state ───────────────────────────────────────────────────────────── */
const S = {
  park: 'halden', level: 'L0', bay: null, dur: 135, plate: 'KD19 XNP', sort: 'near', feat: { ev: false, cov: false, h24: false },
  clock: 15 * 60 + 10, sess: null, speed: 60, remind: true, reminded: false, receipt: null, view: 'plan', drag: false,
};
const VEH = [{ plate: 'KD19 XNP', name: 'Grey hatchback' }, { plate: 'LM23 TOA', name: 'Electric · charging', ev: 1 }];
const P = () => PB[S.park];

/* ── list ────────────────────────────────────────────────────────────── */
function renderList() {
  const SO = [['near', 'Nearest'], ['cheap', 'Cheapest'], ['space', 'Most space']];
  $('[data-sorts]').innerHTML = SO.map(([k, t]) => '<button type="button" role="radio" data-sort="' + k + '" aria-checked="' + (S.sort === k) + '">' + t + '</button>').join('');
  $('[data-feats]').innerHTML = [['ev', 'EV charging', I.bolt], ['cov', 'Covered', I.roof], ['h24', '24 hours', I.clock]].map(([k, t, ic]) => '<button type="button" data-feat="' + k + '" aria-pressed="' + S.feat[k] + '">' + ico(ic) + t + '</button>').join('');
  let L = PARKS.filter(p => (!S.feat.ev || p.ev) && (!S.feat.cov || p.cov) && (!S.feat.h24 || p.h24));
  const dur = Math.min(S.dur, 240);
  L.sort((a, b) => S.sort === 'near' ? a.m - b.m : S.sort === 'cheap' ? tariff(a, dur).total - tariff(b, dur).total : freeAll(b) - freeAll(a));
  $('[data-cards]').innerHTML = L.length ? L.map((p, i) => {
    const f = freeAll(p), tot = total(p), full = f === 0, cost = tariff(p, Math.min(S.dur, p.max));
    return '<div class="amo-park-card' + (full ? ' full' : '') + '" role="option" data-park="' + p.id + '" aria-selected="' + (S.park === p.id) + '" tabindex="' + (S.park === p.id ? 0 : -1) + '" style="--i:' + i + '">' +
      '<div class="t"><b>' + esc(p.name) + '</b><span class="pr">' + gbp(cost.total) + '<small>' + durTxt(Math.min(S.dur, p.max)) + '</small></span></div>' +
      '<div class="s">' + ico(I.walk) + p.m + ' m · ' + esc(rateTxt(p)) + '</div>' +
      '<div class="occ" style="--f:' + (f / tot * 100).toFixed(1) + '%"><i></i><span>' + (full ? '<b>Full</b>' : '<b>' + f + '</b> of ' + tot + ' free') + '</span></div>' +
      '<div class="tags">' + (p.ev ? '<span class="ev">' + ico(I.bolt) + evFree(p) + ' EV free</span>' : '') + (p.cov ? '<span>Covered</span>' : '<span>Open air</span>') + (p.h24 ? '<span>24 h</span>' : '') + (p.max < 720 ? '<span>Max ' + p.max / 60 + ' h</span>' : '') + '</div></div>';
  }).join('') : '<p class="amo-park-none">No car parks match. Turn a filter off.</p>';
}

/* ── floor plan ──────────────────────────────────────────────────────── */
function renderPlan() {
  const p = P(), bays = PLANS[p.id + '|' + S.level], gi = ground(p), li = p.levels.indexOf(S.level), isG = li === gi;
  $('[data-planhead]').innerHTML = '<div class="ttl"><span class="k">' + esc(p.addr) + '</span><h2>' + esc(p.name) + '</h2><p>' + esc(p.note) + '</p></div>' +
    '<div class="amo-park-levels" role="tablist" aria-label="Levels">' + p.levels.map(lv => { const n = freeIn(p, lv); return '<button type="button" role="tab" data-level="' + lv + '" aria-selected="' + (lv === S.level) + '"><b>' + lv + '</b><small>' + (n ? n + ' free' : 'full') + '</small></button>'; }).join('') + '</div>';
  const sel = S.bay && S.bay.park === p.id && S.bay.level === S.level ? bays.find(b => b.id === S.bay.id) : null;
  const tabTarget = sel || bays.find(b => !b.taken);
  let h = '<svg class="amo-park-svg" viewBox="0 0 700 430" role="group" aria-label="' + esc(p.name + ' level ' + S.level + ', ' + freeIn(p, S.level) + ' free bays') + '">';
  h += '<rect class="slab" x="6" y="6" width="688" height="418" rx="14"/>';
  h += '<rect class="aisle" x="20" y="88" width="560" height="62" rx="4"/><rect class="aisle" x="20" y="274" width="560" height="62" rx="4"/><rect class="aisle" x="20" y="88" width="50" height="248" rx="4"/>';
  [119, 305].forEach(y => { for (let x = 110; x < 560; x += 70) h += '<path class="arrow" d="M' + x + ' ' + y + 'h22m-6 -5 6 5-6 5"/>'; });
  h += '<path class="pillar" d="M' + (X0 + 4 * BW - 3) + ' 210h6v6h-6zM' + (X0 + 8 * BW - 3) + ' 210h6v6h-6z"/>';
  /* core: ramps, lift and pay station on the right */
  h += '<g class="core"><rect x="592" y="20" width="90" height="140" rx="8"/><path class="ramp" d="M602 40h70M602 60h70M602 80h70M602 100h70M602 120h70M602 140h70"/><text x="637" y="34" text-anchor="middle">' + (li < p.levels.length - 1 ? 'RAMP UP ↑' : 'TOP LEVEL') + '</text>' +
    '<rect x="592" y="174" width="90" height="74" rx="8"/><text x="637" y="203" text-anchor="middle">LIFT</text><text x="637" y="220" text-anchor="middle" class="sm">+ stairs</text>' +
    '<rect x="592" y="262" width="90" height="74" rx="8"/><text x="637" y="291" text-anchor="middle">' + (li > 0 ? 'RAMP DOWN ↓' : 'PAY STATION') + '</text><text x="637" y="308" text-anchor="middle" class="sm">' + (li > 0 ? 'to ' + p.levels[li - 1] : 'cash · card') + '</text></g>';
  h += isG ? '<g class="gate"><path d="M6 106v26" /><text x="34" y="80" text-anchor="middle">ENTRY</text><path class="arrow in" d="M-4 119h22m-6 -5 6 5-6 5"/></g>' : '';
  /* route from the entry (or the ramp) to your bay */
  if (sel) {
    const ax = AISLE[sel.row], bx = sel.x + BW / 2, by = sel.y + BD / 2, sx = isG ? 12 : 588, sy = 119;
    const d = 'M' + sx + ' ' + sy + (ax === 305 ? (isG ? 'L45 119L45 305' : 'L588 305') : '') + 'L' + bx + ' ' + ax + 'L' + bx + ' ' + by;
    h += '<path class="route" pathLength="1" d="' + d + '"/>';
  }
  bays.forEach(b => {
    const st = b.taken ? 'taken' : 'free', mine = sel === b, cx = b.x + BW / 2, cy = b.y + BD / 2;
    const lbl = 'Bay ' + b.id + ', ' + (b.taken ? 'taken' : 'free') + (b.ev ? ', EV charger' : '') + (b.acc ? ', accessible' : '');
    h += '<g class="bay ' + st + (b.ev ? ' ev' : '') + (b.acc ? ' acc' : '') + (mine ? ' mine' : '') + '" data-bay="' + b.id + '"' + (b.taken ? ' aria-hidden="true"' : ' role="button" aria-pressed="' + mine + '" tabindex="' + (b === tabTarget ? 0 : -1) + '" aria-label="' + esc(lbl) + '"') + '>' +
      '<rect class="cell" x="' + (b.x + 2) + '" y="' + (b.y + 2) + '" width="' + (BW - 4) + '" height="' + (BD - 4) + '" rx="3"/>' +
      '<path class="paint" d="M' + b.x + ' ' + (b.face > 0 ? b.y : b.y + BD) + 'v' + (b.face > 0 ? BD : -BD) + 'M' + (b.x + BW) + ' ' + (b.face > 0 ? b.y : b.y + BD) + 'v' + (b.face > 0 ? BD : -BD) + '"/>';
    if (b.taken) h += '<g class="car" transform="translate(' + cx + ' ' + cy + ') rotate(' + b.tilt.toFixed(1) + ')"><rect x="-13" y="-24" width="26" height="48" rx="7" style="fill:' + b.color + '"/><rect class="gl" x="-10" y="' + (b.face > 0 ? 6 : -14) + '" width="20" height="8" rx="2"/><rect class="gl" x="-9" y="' + (b.face > 0 ? -18 : 12) + '" width="18" height="5" rx="2"/></g>';
    else if (b.ev) h += '<path class="sym" transform="translate(' + (cx - 9) + ' ' + (cy - 9) + ') scale(.75)" d="' + 'M13 3 5 13.5h6L10 21l8-10.5h-6Z' + '"/>';
    else if (b.acc) h += '<g class="sym" transform="translate(' + (cx - 9) + ' ' + (cy - 9) + ') scale(.75)">' + I.acc + '</g>';
    if (mine) h += '<g class="pin" transform="translate(' + cx + ' ' + cy + ')"><circle r="15"/><text y="5" text-anchor="middle">P</text></g>';
    h += '<text class="id" x="' + cx + '" y="' + (b.face > 0 ? b.y + BD - 6 : b.y + 13) + '" text-anchor="middle">' + b.id + '</text></g>';
  });
  h += '</svg>';
  const lb = bays.filter(b => !b.taken && !b.mine);
  h += '<dl class="amo-park-facts"><div><dt>Free here</dt><dd>' + lb.length + ' of 48</dd></div><div><dt>EV chargers</dt><dd>' + (p.ev ? lb.filter(b => b.ev).length + ' free · 22 kW' : 'none') + '</dd></div><div><dt>Accessible</dt><dd>' + lb.filter(b => b.acc).length + ' free · by the entry</dd></div><div><dt>Headroom</dt><dd>' + (p.cov ? '2.10 m' : 'open air') + '</dd></div></dl>';
  $('[data-floor]').innerHTML = h;
  if (sel && !RM.matches) { const r = $('.amo-park-svg .route'); if (r) r.animate([{ strokeDashoffset: 1 }, { strokeDashoffset: 0 }], { duration: 700, easing: 'cubic-bezier(.3,.7,.2,1)' }); }
}

/* ── the pay panel ───────────────────────────────────────────────────── */
function dialAngle(m) { return m / 720 * 360; }
function renderPay() {
  const p = P(), box = $('[data-pay]');
  if (S.sess) { box.innerHTML = sessionHTML(); paintSession(); return; }
  if (S.receipt) { box.innerHTML = receiptHTML(); return; }
  const dur = Math.min(S.dur, p.max), t = tariff(p, dur), full = freeAll(p) === 0, b = S.bay && S.bay.park === p.id ? S.bay : null;
  box.innerHTML = '<header class="amo-park-payhead"><span class="k">Park at</span><b>' + esc(p.name) + '</b><span class="bay">' + (b ? 'Bay ' + b.level + ' · ' + b.id : 'Any free bay') + '</span></header>' +
    '<div class="amo-park-veh" role="radiogroup" aria-label="Vehicle">' + VEH.map(v => '<button type="button" role="radio" data-plate="' + v.plate + '" aria-checked="' + (S.plate === v.plate) + '"><span class="plate">' + v.plate + '</span><small>' + v.name + '</small></button>').join('') + '</div>' +
    '<div class="amo-park-dial' + (S.drag ? ' drag' : '') + '" data-dial role="slider" tabindex="0" aria-label="Parking duration" aria-valuemin="15" aria-valuemax="' + p.max + '" aria-valuenow="' + dur + '" aria-valuetext="' + durTxt(dur) + ', ' + gbp(t.total) + '" style="--amo-park-a:' + dialAngle(dur) + 'deg;--amo-park-max:' + dialAngle(p.max) + 'deg">' +
      '<div class="ring"><i class="arc"></i><i class="ticks"></i>' + (p.max < 720 ? '<i class="nogo"></i>' : '') + '<span class="knob"><i></i></span></div>' +
      '<div class="mid"><span class="d" data-dur>' + durTxt(dur) + '</span><span class="u">until <b data-until>' + hm(S.clock + dur) + '</b></span><span class="c" data-cost>' + gbp(t.total) + '</span></div>' +
      [12, 3, 6, 9].map((n, i) => '<span class="hr h' + i + '">' + n + 'h</span>').join('') + '</div>' +
    '<div class="amo-park-quick" role="group" aria-label="Quick durations">' + [30, 60, 120, 180, 480].filter(m => m <= p.max).map(m => '<button type="button" data-quick="' + m + '" aria-pressed="' + (dur === m) + '">' + durTxt(m) + '</button>').join('') + '</div>' +
    '<div class="amo-park-lines" data-lines>' + linesHTML(t) + '</div>' +
    '<button type="button" class="amo-park-cta" data-act="start"' + (full ? ' disabled title="This car park is full"' : '') + '><span>Start parking</span><span data-ctacost>' + gbp(t.total) + '</span></button>' +
    '<p class="amo-park-fine">You only pay for the time you use — ending early charges the tariff for actual minutes. <kbd>←</kbd><kbd>→</kbd> 15 min · <kbd>PgUp</kbd> 1 h</p>';
}
const linesHTML = t => t.lines.map(l => '<div><span>' + esc(l[0]) + '</span><span>' + (l[1] < 0 ? '−' + gbp(-l[1]) : gbp(l[1])) + '</span></div>').join('') + '<div class="t"><span>Total</span><span>' + gbp(t.total) + '</span></div>';
function setDur(m, fromDrag) {
  const p = P(); m = Math.max(15, Math.min(p.max, Math.round(m / 15) * 15));
  if (m === S.dur && !fromDrag) return;
  S.dur = m;
  const d = $('[data-dial]'); if (!d) return;
  const t = tariff(p, m);
  d.style.setProperty('--amo-park-a', dialAngle(m) + 'deg');
