function renderListPrices() { $$('[data-park]').forEach(c => { const p = PB[c.dataset.park], m = Math.min(S.dur, p.max), pr = c.querySelector('.pr'); if (pr) pr.innerHTML = gbp(tariff(p, m).total) + '<small>' + durTxt(m) + '</small>'; }); }

/* session */
function sessionHTML() {
