    '<button type="button" role="switch" data-act="speed" aria-checked="' + (S.speed === 60) + '"><i></i>' + ico(I.clock) + 'Demo clock ×60</button></div>' +
    '<button type="button" class="amo-park-cta stop" data-act="end">' + ico(I.stop) + '<span>End parking</span><span data-endcost>£0.00</span></button>';
}
function paintSession() {
  const s = S.sess; if (!s) return;
