    '<div class="amo-park-paid"><span class="amt">' + gbp(r.t.total) + '</span><span>for ' + durTxt(r.mins) + ' parked</span></div>' +
    '<div class="amo-park-lines">' + linesHTML(r.t) + '</div>' +
    (r.est > r.mins ? '<p class="amo-park-save">' + ico(I.check) + 'You booked ' + durTxt(r.est) + ' (' + gbp(r.estP) + ') and left early — saved ' + gbp(r.estP - r.t.total) + '.</p>' : '') +
    '<button type="button" class="amo-park-cta" data-act="again"><span>Park again</span>' + ico(I.car) + '</button>';
