/* ── actions ─────────────────────────────────────────────────────────── */
function render() { renderList(); renderPlan(); renderPay(); root.dataset.view = S.view; $$('.amo-park-tabs [role=tab]').forEach(b => b.setAttribute('aria-selected', String(b.dataset.view === S.view))); }
