/* ── toast ───────────────────────────────────────────────────────────── */
let toastT = 0;
function toast(msg) { const t = $('[data-toast]'); t.textContent = msg; t.hidden = false; clearTimeout(toastT); toastT = setTimeout(() => { if (root.isConnected) t.hidden = true; }, 3000); }

/* ── events ──────────────────────────────────────────────────────────── */
root.addEventListener('click', e => {
  const t = e.target;
