  const pk = t.closest('[data-park]'); if (pk) { pickPark(pk.dataset.park); if (root.clientWidth < 760) { S.view = 'plan'; render(); } return; }
  const lv = t.closest('[data-level]'); if (lv) { pickLevel(lv.dataset.level); return; }
  const bay = t.closest('[data-bay]'); if (bay) { pickBay(bay.dataset.bay); return; }
  const pl = t.closest('[data-plate]'); if (pl) { S.plate = pl.dataset.plate; renderPay(); return; }
  const q = t.closest('[data-quick]'); if (q) { setDur(+q.dataset.quick); return; }
  const ex = t.closest('[data-ext]');
