  else if (a === 'speed') { S.speed = S.speed === 60 ? 1 : 60; b.setAttribute('aria-checked', String(S.speed === 60)); toast(S.speed === 60 ? 'Demo clock: one second is one minute' : 'Clock running in real time'); }
});
/* the dial: pointer angle → minutes, continuous so it never jumps across 12 o'clock */
root.addEventListener('pointerdown', e => {
  const d = e.target.closest('[data-dial]'); if (!d || e.button !== 0) return;
  e.preventDefault(); d.focus({ preventScroll: true });
