    const step = { ArrowRight: 15, ArrowUp: 15, ArrowLeft: -15, ArrowDown: -15, PageUp: 60, PageDown: -60 }[e.key];
    if (step) { e.preventDefault(); setDur(S.dur + step); return; }
    if (e.key === 'Home') { e.preventDefault(); setDur(15); return; }
