    const n = free[(i + (e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : -1) + free.length) % free.length];
    $$('[data-bay][tabindex="0"]').forEach(x => x.setAttribute('tabindex', '-1'));
