    const items = $$('[role=radio], [role=option], [role=tab]', grp), i = items.indexOf(t.closest('[role=radio], [role=option], [role=tab]'));
    if (i >= 0) { e.preventDefault(); const n = items[(i + (e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length]; n.click(); const key = Object.keys(n.dataset)[0]; requestAnimationFrame(() => { if (!root.isConnected) return; $('[data-' + key + '="' + n.dataset[key] + '"]')?.focus(); }); return; }
  }
  if ((e.key === 'Enter' || e.key === ' ') && t.closest('[data-park]')) { e.preventDefault(); pickPark(t.closest('[data-park]').dataset.park); return; }
  if (t.matches('input') || e.metaKey || e.ctrlKey || e.altKey) return;
  if ((e.key === 'Enter' || e.key === ' ') && t.closest('button')) return;
