  if (k === 'l') { const p = P(), i = p.levels.indexOf(S.level); pickLevel(p.levels[(i + 1) % p.levels.length]); }
  else if (k === '[' || k === ']') { const L = $$('[data-park]').map(x => x.dataset.park), i = L.indexOf(S.park); const n = L[(i + (k === ']' ? 1 : -1) + L.length) % L.length]; if (n) pickPark(n); }
