css:
.amo-dispatch {
  /* re-theme with these four; job colours by vehicle class are below */
  --amo-dispatch-bg: oklch(0.2 0.006 260);
  --amo-dispatch-ink: oklch(0.94 0.006 260);
  --amo-dispatch-accent: oklch(0.85 0.17 125);
  --amo-dispatch-bad: oklch(0.68 0.19 25);
  --amo-dispatch-bike: oklch(0.78 0.11 180);
  --amo-dispatch-van: oklch(0.82 0.13 80);
  --amo-dispatch-truck: oklch(0.7 0.13 35);

  --amo-dispatch-surf: color-mix(in oklch, var(--amo-dispatch-ink) 5%, var(--amo-dispatch-bg));
  --amo-dispatch-surf2: color-mix(in oklch, var(--amo-dispatch-ink) 9%, var(--amo-dispatch-bg));
  --amo-dispatch-line: color-mix(in oklch, var(--amo-dispatch-ink) 9%, transparent);
  --amo-dispatch-line2: color-mix(in oklch, var(--amo-dispatch-ink) 17%, transparent);
  --amo-dispatch-mute: color-mix(in oklch, var(--amo-dispatch-ink) 60%, var(--amo-dispatch-bg));
  --amo-dispatch-faint: color-mix(in oklch, var(--amo-dispatch-ink) 38%, var(--amo-dispatch-bg));
  --amo-dispatch-on: oklch(0.22 0.03 125);
  --amo-dispatch-ease: cubic-bezier(.2, .8, .2, 1);
  --amo-dispatch-spring: linear(0, 0.14 6%, 0.47 13%, 0.82 21%, 1.02 29%, 1.05 36%, 1.03 45%, 1.005 58%, 1);

  position: relative; width: 100%; height: var(--amo-dispatch-h, 680px); box-sizing: border-box;
  container-type: inline-size; overflow: clip; isolation: isolate; display: flex; flex-direction: column; border-radius: 18px;
  background: var(--amo-dispatch-bg); color: var(--amo-dispatch-ink); color-scheme: dark; accent-color: var(--amo-dispatch-accent);
  font: 12.5px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--amo-dispatch-accent); outline-offset: 2px; }
  & button { font: inherit; color: inherit; cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .38; }
  & h2, & h3, & p, & dl, & dd { margin: 0; padding: 0; }
  & [hidden] { display: none !important; }
  & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-grid; place-items: center; min-width: 17px; height: 17px; padding: 0 4px; border-radius: 4px; font: 650 9.5px/1 ui-monospace, Menlo, monospace; color: var(--amo-dispatch-mute); box-shadow: inset 0 0 0 1px var(--amo-dispatch-line2); }
  &.dragging, &.dragging * { cursor: grabbing !important; user-select: none; }
}

/* ── top bar ──────────────────────────────────────── */
.amo-dispatch .amo-dispatch-top { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 18px; padding: 10px 14px; border-bottom: 1px solid var(--amo-dispatch-line); }
.amo-dispatch .amo-dispatch-id { display: flex; align-items: center; gap: 10px; & b { display: block; font-size: 14.5px; font-weight: 760; letter-spacing: -.015em; white-space: nowrap; } & small { display: block; font-size: 11.5px; color: var(--amo-dispatch-mute); white-space: nowrap; } }
.amo-dispatch .amo-dispatch-logo { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 9px; background: var(--amo-dispatch-accent); color: var(--amo-dispatch-on); & svg { width: 20px; height: 20px; stroke-width: 2.2; } }
.amo-dispatch .amo-dispatch-kpis {
  display: flex; justify-content: center; gap: 4px; min-width: 0;
  & div { padding: 4px 12px; border-left: 1px solid var(--amo-dispatch-line); min-width: 0; }
  & div:first-child { border: 0; }
  & dt { font-size: 10px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--amo-dispatch-faint); white-space: nowrap; }
  & dd { display: flex; align-items: baseline; gap: 6px; font-size: 12px; color: var(--amo-dispatch-mute); white-space: nowrap; font-variant-numeric: tabular-nums; }
  & dd b { font-size: 17px; font-weight: 750; color: var(--amo-dispatch-ink); letter-spacing: -.02em; }
  & .warn dd b { color: var(--amo-dispatch-van); } & .bad dd b { color: var(--amo-dispatch-bad); } & .good dd b { color: var(--amo-dispatch-accent); }
  & dd button { font-size: 11px; font-weight: 650; color: var(--amo-dispatch-bad); text-decoration: underline; text-underline-offset: 2px; }
}
.amo-dispatch .amo-dispatch-acts { display: flex; align-items: center; gap: 6px; }
.amo-dispatch .amo-dispatch-zoom { display: flex; gap: 2px; padding: 2px; border-radius: 10px; background: var(--amo-dispatch-surf); & .amo-dispatch-btn { width: 30px; height: 30px; padding: 0; background: none; } }
.amo-dispatch .amo-dispatch-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 34px; padding: 0 10px; border-radius: 9px; background: var(--amo-dispatch-surf2); font-weight: 650; white-space: nowrap;
  transition: background .15s, scale .3s var(--amo-dispatch-spring);
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--amo-dispatch-ink) 15%, var(--amo-dispatch-bg)); }
  &:active:not(:disabled) { scale: .96; }
  &.pri { background: var(--amo-dispatch-accent); color: var(--amo-dispatch-on); }
  &.pri:hover:not(:disabled) { background: color-mix(in oklch, var(--amo-dispatch-accent), white 15%); }
  &.pri kbd { color: inherit; box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--amo-dispatch-on) 35%, transparent); }
}

/* ── shell ────────────────────────────────────────── */
.amo-dispatch .amo-dispatch-tabs { display: none; }
.amo-dispatch .amo-dispatch-app { position: relative; flex: 1; min-height: 0; display: grid; grid-template-columns: clamp(230px, 24cqi, 280px) minmax(0, 1fr); grid-template-rows: minmax(0, 1fr); grid-template-areas: "queue board"; }
.amo-dispatch .amo-dispatch-queue {
  grid-area: queue; min-height: 0; display: flex; flex-direction: column; border-right: 1px solid var(--amo-dispatch-line); transition: background .2s, box-shadow .2s;
  & > header { display: grid; gap: 8px; padding: 12px 12px 8px; }
  & h2 { display: flex; align-items: baseline; gap: 6px; font-size: 11px; font-weight: 750; letter-spacing: .09em; text-transform: uppercase; color: var(--amo-dispatch-faint); }
  & h2 span { font-size: 14px; color: var(--amo-dispatch-van); font-variant-numeric: tabular-nums; letter-spacing: 0; }
  &.drop { background: color-mix(in oklch, var(--amo-dispatch-accent) 7%, var(--amo-dispatch-bg)); box-shadow: inset 0 0 0 2px color-mix(in oklch, var(--amo-dispatch-accent) 50%, transparent); }
}
.amo-dispatch .amo-dispatch-chips {
  display: flex; flex-wrap: wrap; gap: 4px;
  & button { display: inline-flex; align-items: center; gap: 4px; height: 24px; padding: 0 8px; border-radius: 99px; font-size: 11.5px; font-weight: 600; color: var(--amo-dispatch-mute); box-shadow: inset 0 0 0 1px var(--amo-dispatch-line2); }
  & button span { font-size: 10.5px; opacity: .7; font-variant-numeric: tabular-nums; }
  & button:hover { color: var(--amo-dispatch-ink); }
