@keyframes amo-dispatch-in { from { opacity: 0; translate: 0 6px; } }
.amo-dispatch .amo-dispatch-empty { display: flex; align-items: center; gap: 6px; padding: 18px 6px; color: var(--amo-dispatch-mute); & svg { color: var(--amo-dispatch-accent); } }
.amo-dispatch .amo-dispatch-hint { padding: 8px 12px 10px; border-top: 1px solid var(--amo-dispatch-line); font-size: 11px; line-height: 1.7; color: var(--amo-dispatch-faint); text-wrap: pretty; }

/* ── timeline ─────────────────────────────────────── */
.amo-dispatch .amo-dispatch-board { grid-area: board; position: relative; min-width: 0; min-height: 0; }
.amo-dispatch .amo-dispatch-scroll { position: absolute; inset: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; }
.amo-dispatch .amo-dispatch-grid { position: relative; width: max-content; min-width: 100%; padding-bottom: 8px; }
.amo-dispatch .amo-dispatch-hours {
  position: sticky; top: 0; z-index: 4; display: grid; grid-template-columns: var(--headw) auto; height: 30px; background: var(--amo-dispatch-bg); border-bottom: 1px solid var(--amo-dispatch-line);
  & .corner { position: sticky; left: 0; z-index: 2; display: flex; align-items: center; padding-left: 12px; background: var(--amo-dispatch-bg); font-size: 10px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--amo-dispatch-faint); border-right: 1px solid var(--amo-dispatch-line); }
  & .track { position: relative; }
  & .hr { position: absolute; top: 9px; translate: -50% 0; font: 600 10.5px/1 ui-monospace, Menlo, monospace; color: var(--amo-dispatch-faint); font-variant-numeric: tabular-nums; }
  & .hr:first-child { translate: 2px 0; } & .hr:last-child { translate: -100% 0; }
}
.amo-dispatch .amo-dispatch-lane {
  display: grid; grid-template-columns: var(--headw) auto; border-bottom: 1px solid var(--amo-dispatch-line);
  animation: amo-dispatch-in .45s var(--amo-dispatch-ease) backwards; animation-delay: calc(var(--i) * 30ms);
  & .head { position: sticky; left: 0; z-index: 3; display: flex; align-items: center; gap: 8px; padding: 0 10px; background: var(--amo-dispatch-bg); border-right: 1px solid var(--amo-dispatch-line); }
  & .nm { position: relative; min-width: 0; flex: 1; }
  & .nm b { display: block; font-size: 12.5px; font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .nm small { display: block; font-size: 10.5px; color: var(--amo-dispatch-mute); font-variant-numeric: tabular-nums; white-space: nowrap; }
  & .ut { display: block; height: 3px; margin-top: 4px; border-radius: 2px; background: linear-gradient(90deg, var(--amo-dispatch-accent) var(--u), var(--amo-dispatch-line2) var(--u)); }
  & .body { position: relative; height: 58px; background: repeating-linear-gradient(90deg, var(--amo-dispatch-line) 0 1px, transparent 1px var(--hp)); }
  & .off { position: absolute; top: 0; bottom: 0; background: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--amo-dispatch-ink) 4%, transparent) 0 5px, transparent 5px 10px), color-mix(in oklch, black 18%, transparent); }
  &:hover .body { background-color: color-mix(in oklch, var(--amo-dispatch-ink) 2%, transparent); }
}
.amo-dispatch .vb { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; flex: none; background: color-mix(in oklch, var(--c) 16%, var(--amo-dispatch-bg)); color: var(--c); --c: var(--amo-dispatch-van);
  &.bike { --c: var(--amo-dispatch-bike); } &.truck { --c: var(--amo-dispatch-truck); } }
.amo-dispatch .amo-dispatch-job {
  --c: var(--amo-dispatch-van);
  position: absolute; top: 6px; bottom: 6px; display: grid; align-content: center; gap: 0; padding: 0 7px 0 9px; border-radius: 8px; overflow: hidden; cursor: grab; touch-action: none; user-select: none;
  background: color-mix(in oklch, var(--c) 20%, var(--amo-dispatch-bg)); box-shadow: inset 3px 0 0 var(--c), inset 0 0 0 1px color-mix(in oklch, var(--c) 35%, transparent);
  transition: box-shadow .2s, opacity .2s, filter .2s;
  &.bike { --c: var(--amo-dispatch-bike); } &.truck { --c: var(--amo-dispatch-truck); }
  & b { display: flex; align-items: center; gap: 3px; font: 700 11px/1.2 ui-monospace, Menlo, monospace; color: color-mix(in oklch, var(--c), white 30%); white-space: nowrap; }
  & b svg { width: 11px; height: 11px; }
  & span { font-size: 11.5px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { font-size: 10px; color: var(--amo-dispatch-mute); font-variant-numeric: tabular-nums; white-space: nowrap; }
  &.tiny span, &.tiny small { display: none; }
  &:hover { filter: brightness(1.12); }
  &.done { opacity: .5; cursor: pointer; }
  &.live { cursor: pointer; background: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--c) 30%, var(--amo-dispatch-bg)) 0 6px, color-mix(in oklch, var(--c) 20%, var(--amo-dispatch-bg)) 6px 12px); background-size: 200% 100%; animation: amo-dispatch-live 3s linear infinite; }
  &.bad { box-shadow: inset 3px 0 0 var(--amo-dispatch-bad), inset 0 0 0 1.5px var(--amo-dispatch-bad); }
  &.bad b { color: color-mix(in oklch, var(--amo-dispatch-bad), white 25%); }
  &.sel { box-shadow: inset 3px 0 0 var(--c), 0 0 0 2px var(--amo-dispatch-ink), 0 8px 20px -6px black; z-index: 2; }
