}
@keyframes amo-dispatch-live { to { background-position: -34px 0; } }
.amo-dispatch .amo-dispatch-now {
  position: absolute; top: 0; bottom: 0; z-index: 3; width: 2px; translate: -1px 0; background: var(--amo-dispatch-bad); pointer-events: none;
  & span { position: sticky; top: 6px; display: block; translate: -50% 0; width: max-content; padding: 2px 5px; border-radius: 5px; background: var(--amo-dispatch-bad); color: white; font: 700 10px/1.2 ui-monospace, Menlo, monospace; }
}
.amo-dispatch .amo-dispatch-preview {
  position: absolute; top: 6px; bottom: 6px; z-index: 4; display: grid; align-content: center; padding: 0 7px; border-radius: 8px; pointer-events: none;
  border: 2px dashed var(--amo-dispatch-accent); background: color-mix(in oklch, var(--amo-dispatch-accent) 14%, transparent); overflow: hidden;
  & span { font: 700 10.5px/1.2 ui-monospace, Menlo, monospace; white-space: nowrap; }
  & em { font-style: normal; font-size: 10.5px; white-space: nowrap; color: var(--amo-dispatch-mute); }
  &.warn { border-color: var(--amo-dispatch-van); background: color-mix(in oklch, var(--amo-dispatch-van) 14%, transparent); }
  &.warn em { color: var(--amo-dispatch-van); }
