  display: grid; align-content: start; gap: 12px; padding: 14px; border-radius: 14px;
  background: var(--amo-dispatch-bg); box-shadow: 0 0 0 1px var(--amo-dispatch-line2), 0 30px 60px -20px black;
  transition: translate .4s var(--amo-dispatch-ease), opacity .25s; @starting-style { translate: 24px 0; opacity: 0; }
  & header { display: grid; grid-template-columns: 34px minmax(0, 1fr) 28px; gap: 10px; align-items: center; }
  & header b { display: block; font-size: 14px; font-weight: 720; line-height: 1.25; text-wrap: balance; }
  & header small { display: block; font-size: 12px; color: var(--amo-dispatch-mute); }
