  & .now .k { font-size: 10px; font-weight: 750; letter-spacing: .09em; text-transform: uppercase; color: var(--amo-dispatch-accent); }
  & .now b { font-size: 13.5px; } & .now span { font-size: 12px; color: var(--amo-dispatch-mute); font-variant-numeric: tabular-nums; }
  & .lockd { display: flex; gap: 6px; align-items: center; color: var(--amo-dispatch-mute); }
  & .nudge { display: grid; grid-template-columns: 1fr 1fr 1.2fr; gap: 6px; }
  & .nudge button { display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 32px; border-radius: 9px; background: var(--amo-dispatch-surf2); font-weight: 650; font-size: 12px; }
  & .nudge button:hover:not(:disabled) { background: color-mix(in oklch, var(--amo-dispatch-ink) 15%, var(--amo-dispatch-bg)); }
  & h3 { font-size: 10px; font-weight: 750; letter-spacing: .09em; text-transform: uppercase; color: var(--amo-dispatch-faint); margin-bottom: -6px; }
  & .cands { display: grid; gap: 2px; }
  & .cands button { display: grid; grid-template-columns: 28px minmax(0, 1fr) auto; align-items: center; gap: 8px; padding: 5px 6px; border-radius: 9px; text-align: left; }
  & .cands button:hover:not(:disabled) { background: var(--amo-dispatch-surf2); }
  & .cands em { font-style: normal; font-size: 11.5px; color: var(--amo-dispatch-accent); font-variant-numeric: tabular-nums; }
  & .cands button:disabled em { color: var(--amo-dispatch-mute); }
}

/* toast */
.amo-dispatch .amo-dispatch-toast {
  position: absolute; left: 50%; bottom: 16px; z-index: 40; translate: -50% 0; max-width: calc(100% - 32px); padding: 9px 14px; border-radius: 10px;
  background: var(--amo-dispatch-ink); color: var(--amo-dispatch-bg); font-weight: 600; box-shadow: 0 16px 36px -12px black;
  transition: opacity .25s, translate .45s var(--amo-dispatch-spring); @starting-style { opacity: 0; translate: -50% 12px; }
  &.bad { background: var(--amo-dispatch-bad); color: white; }
}

/* ── responsive ───────────────────────────────────── */
@container (max-width: 1100px) {
  .amo-dispatch .amo-dispatch-kpis div:nth-child(4) { display: none; }
  .amo-dispatch .amo-dispatch-acts .pri span { display: none; }
}
@container (max-width: 959px) {
  .amo-dispatch .amo-dispatch-kpis div:nth-child(1) { display: none; }
  .amo-dispatch .amo-dispatch-acts kbd { display: none; }
  .amo-dispatch .amo-dispatch-id small { display: none; }
}
@container (max-width: 759px) {
  .amo-dispatch .amo-dispatch-top { grid-template-columns: minmax(0, 1fr) auto; gap: 8px; padding: 8px 10px; }
  .amo-dispatch .amo-dispatch-kpis { grid-row: 2; grid-column: 1 / -1; justify-content: flex-start; }
  .amo-dispatch .amo-dispatch-kpis div { padding: 2px 10px; }
  .amo-dispatch .amo-dispatch-id b { font-size: 13.5px; }
  .amo-dispatch .amo-dispatch-zoom { display: none; }
  .amo-dispatch .amo-dispatch-tabs {
    display: flex; gap: 4px; padding: 6px 10px; border-bottom: 1px solid var(--amo-dispatch-line);
    & button { flex: 1; height: 32px; border-radius: 8px; font-weight: 650; color: var(--amo-dispatch-mute); }
    & button span { color: var(--amo-dispatch-van); }
    & button[aria-selected="true"] { background: var(--amo-dispatch-surf2); color: var(--amo-dispatch-ink); }
  }
  .amo-dispatch .amo-dispatch-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "main"; }
  .amo-dispatch .amo-dispatch-queue, .amo-dispatch .amo-dispatch-board { grid-area: main; border: 0; }
  .amo-dispatch[data-view="board"] .amo-dispatch-queue { display: none; }
  .amo-dispatch[data-view="queue"] .amo-dispatch-board { visibility: hidden; }
  .amo-dispatch .amo-dispatch-drawer { grid-area: main; margin: 0; width: 100%; border-radius: 0; }
  .amo-dispatch .amo-dispatch-lane .head { padding: 0 6px; gap: 6px; }
  .amo-dispatch .amo-dispatch-lane .vb { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .amo-dispatch {
    & *, & *::before, & *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
    & .amo-dispatch-job.live { animation: none; }
  }
}

