.amo-locker {
  /* re-theme with these four */
  --amo-locker-wall: oklch(0.955 0.008 85);
  --amo-locker-ink: oklch(0.23 0.015 60);
  --amo-locker-accent: oklch(0.86 0.16 92);
  --amo-locker-metal: oklch(0.85 0.022 165);

  --amo-locker-card: color-mix(in oklch, var(--amo-locker-wall), white 75%);
  --amo-locker-line: color-mix(in oklch, var(--amo-locker-ink) 10%, transparent);
  --amo-locker-line2: color-mix(in oklch, var(--amo-locker-ink) 18%, transparent);
  --amo-locker-hover: color-mix(in oklch, var(--amo-locker-ink) 5%, transparent);
  --amo-locker-mute: color-mix(in oklch, var(--amo-locker-ink) 60%, var(--amo-locker-wall));
  --amo-locker-faint: color-mix(in oklch, var(--amo-locker-ink) 40%, var(--amo-locker-wall));
  --amo-locker-frame: color-mix(in oklch, var(--amo-locker-metal), var(--amo-locker-ink) 38%);
  --amo-locker-ok: oklch(0.62 0.15 150);
  --amo-locker-bad: oklch(0.58 0.19 28);
  --amo-locker-ease: cubic-bezier(.2, .8, .2, 1);
  --amo-locker-spring: linear(0, 0.14 6%, 0.47 13%, 0.82 21%, 1.02 29%, 1.05 36%, 1.03 45%, 1.005 58%, 1);
  --amo-locker-swing: linear(0, 0.06 4%, 0.25 10%, 0.62 20%, 0.9 30%, 1.03 40%, 1.05 48%, 1.02 60%, 1);

  position: relative; width: 100%; height: var(--amo-locker-h, 680px); box-sizing: border-box;
  container-type: inline-size; overflow: clip; isolation: isolate; display: flex; flex-direction: column; border-radius: 18px;
  background: var(--amo-locker-wall); color: var(--amo-locker-ink); color-scheme: light; accent-color: var(--amo-locker-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; box-shadow: inset 0 0 0 1px var(--amo-locker-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 3px solid color-mix(in oklch, var(--amo-locker-accent), var(--amo-locker-ink) 30%); outline-offset: 2px; }
  & button { font: inherit; color: inherit; cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; }
  & h2, & p, & ol { margin: 0; padding: 0; }
  & ol { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 5px; font: 650 10px/1 ui-monospace, Menlo, monospace; box-shadow: inset 0 0 0 1px currentColor; opacity: .55; }
  & .k { font-size: 10.5px; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; color: var(--amo-locker-faint); }
}
.amo-locker .amo-locker-tabs { display: none; }
.amo-locker .amo-locker-app { position: relative; flex: 1; min-height: 0; display: grid; grid-template-columns: clamp(300px, 30cqi, 340px) minmax(0, 1fr) clamp(220px, 22cqi, 260px); grid-template-areas: "kiosk wall phone"; }

/* ── kiosk ────────────────────────────────────────── */
.amo-locker .amo-locker-kiosk { grid-area: kiosk; min-height: 0; display: flex; flex-direction: column; gap: 12px; padding: 16px; background: var(--amo-locker-card); border-right: 1px solid var(--amo-locker-line); overflow-y: auto; scrollbar-width: none; }
.amo-locker .amo-locker-brand {
  display: flex; align-items: center; gap: 10px;
  & > span:nth-child(2) { flex: 1; min-width: 0; }
  & b { display: block; font-size: 17px; font-weight: 820; letter-spacing: -.035em; line-height: 1.1; }
  & small { display: block; font-size: 11.5px; color: var(--amo-locker-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.amo-locker .amo-locker-logo { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 10px; background: var(--amo-locker-accent); color: var(--amo-locker-ink); & svg { width: 20px; height: 20px; stroke-width: 2; } }
.amo-locker .amo-locker-a11y {
  display: inline-flex; align-items: center; gap: 5px; height: 30px; padding: 0 9px; border-radius: 99px; font-size: 11.5px; font-weight: 650; color: var(--amo-locker-mute); box-shadow: inset 0 0 0 1px var(--amo-locker-line2);
  & svg { width: 15px; height: 15px; }
  &:hover { color: var(--amo-locker-ink); }
  &[aria-pressed="true"] { background: var(--amo-locker-ink); color: var(--amo-locker-card); box-shadow: none; }
}
.amo-locker .amo-locker-msgbtn { display: none; position: relative; place-items: center; width: 34px; height: 30px; border-radius: 99px; box-shadow: inset 0 0 0 1px var(--amo-locker-line2);
  & span { position: absolute; top: -4px; right: -4px; min-width: 16px; height: 16px; padding: 0 4px; border-radius: 99px; background: var(--amo-locker-bad); color: white; font-size: 10px; font-weight: 800; display: grid; place-items: center; }
  &[aria-expanded="true"] { background: var(--amo-locker-hover); } }
.amo-locker .amo-locker-modes {
  display: grid; grid-template-columns: 1fr 1fr; padding: 4px; border-radius: 14px; background: color-mix(in oklch, var(--amo-locker-ink) 6%, var(--amo-locker-card));
  & button { display: inline-flex; align-items: center; justify-content: center; gap: 7px; height: 38px; border-radius: 10px; font-weight: 700; color: var(--amo-locker-mute); transition: background .2s, color .2s; }
  & button:hover:not(:disabled) { color: var(--amo-locker-ink); }
  & button:disabled { opacity: .4; }
  & [aria-selected="true"] { background: var(--amo-locker-card); color: var(--amo-locker-ink); box-shadow: 0 1px 3px var(--amo-locker-line2); }
}
.amo-locker .amo-locker-screen { flex: 1; display: flex; flex-direction: column; gap: 12px; }
.amo-locker .amo-locker-copy { display: grid; gap: 4px; & h2 { font-size: clamp(19px, 2cqi, 22px); font-weight: 790; letter-spacing: -.035em; line-height: 1.15; text-wrap: balance; } & p { color: var(--amo-locker-mute); text-wrap: pretty; } }
.amo-locker .amo-locker-code {
  display: flex; gap: 6px; justify-content: center;
  & span { position: relative; display: grid; place-items: center; width: 40px; height: 52px; border-radius: 11px; background: color-mix(in oklch, var(--amo-locker-ink) 5%, var(--amo-locker-card)); box-shadow: inset 0 0 0 1.5px var(--amo-locker-line2); font: 750 24px/1 ui-monospace, Menlo, monospace; transition: box-shadow .2s, background .2s; }
  & span.gap { margin-left: 10px; }
  & span.on { background: var(--amo-locker-card); box-shadow: inset 0 0 0 2px var(--amo-locker-ink); animation: amo-locker-pop .3s var(--amo-locker-spring); }
  & span.cur::after { content: ""; position: absolute; width: 2px; height: 24px; border-radius: 1px; background: var(--amo-locker-ink); animation: amo-locker-caret 1s steps(1) infinite; }
  &.err span { box-shadow: inset 0 0 0 2px var(--amo-locker-bad); }
}
@keyframes amo-locker-pop { from { scale: .7; } }
@keyframes amo-locker-caret { 50% { opacity: 0; } }
.amo-locker .amo-locker-msg { display: flex; align-items: center; justify-content: center; gap: 6px; min-height: 36px; font-size: 12.5px; text-align: center; text-wrap: pretty; color: var(--amo-locker-mute); &.bad { color: var(--amo-locker-bad); font-weight: 600; } & b { font-variant-numeric: tabular-nums; } }
.amo-locker .amo-locker-keys {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 7px;
  & button { height: 48px; border-radius: 13px; font: 650 20px/1 system-ui, sans-serif; background: linear-gradient(var(--amo-locker-card), color-mix(in oklch, var(--amo-locker-ink) 4%, var(--amo-locker-card))); box-shadow: inset 0 0 0 1px var(--amo-locker-line2), 0 2px 0 var(--amo-locker-line2); transition: translate .12s, box-shadow .12s, background .2s; display: grid; place-items: center; font-variant-numeric: tabular-nums; }
  & button:hover:not(:disabled) { background: color-mix(in oklch, var(--amo-locker-accent) 22%, var(--amo-locker-card)); }
  & button:active:not(:disabled) { translate: 0 2px; box-shadow: inset 0 0 0 1px var(--amo-locker-line2), 0 0 0 var(--amo-locker-line2); }
  & button.fn { font-size: 13px; font-weight: 700; color: var(--amo-locker-mute); }
  & button:disabled { opacity: .4; }
  & svg { width: 22px; height: 22px; }
}
.amo-locker .amo-locker-go {
  display: flex; align-items: center; justify-content: center; gap: 8px; height: 52px; border-radius: 14px; background: var(--amo-locker-accent); color: var(--amo-locker-ink); font-weight: 780; font-size: 15.5px;
  box-shadow: inset 0 -2px 0 color-mix(in oklch, var(--amo-locker-accent), var(--amo-locker-ink) 25%); transition: background .2s, scale .3s var(--amo-locker-spring), opacity .2s;
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--amo-locker-accent), white 18%); }
  &:active:not(:disabled) { scale: .98; }
  &:disabled { opacity: .45; background: color-mix(in oklch, var(--amo-locker-ink) 8%, var(--amo-locker-card)); box-shadow: none; }
}
.amo-locker .amo-locker-link { display: inline-flex; align-items: center; justify-content: center; gap: 6px; padding: 6px; border-radius: 8px; font-size: 12.5px; font-weight: 600; color: var(--amo-locker-mute); &:hover { color: var(--amo-locker-ink); background: var(--amo-locker-hover); } }
.amo-locker .amo-locker-open {
  display: flex; flex-direction: column; gap: 12px; animation: amo-locker-rise .5s var(--amo-locker-ease);
  & .big { display: flex; align-items: baseline; gap: 10px; }
  & .big span { font-size: 18px; font-weight: 700; color: var(--amo-locker-mute); }
  & .big b { font: 820 clamp(64px, 7.5cqi, 84px)/0.9 ui-monospace, Menlo, monospace; letter-spacing: -.06em; }
  & p { font-size: 14px; text-wrap: pretty; }
}
@keyframes amo-locker-rise { from { opacity: 0; translate: 0 10px; } }
.amo-locker .amo-locker-steps {
  display: grid; gap: 6px;
  & li { display: flex; align-items: center; gap: 8px; font-size: 12.5px; color: var(--amo-locker-mute); }
  & li i { display: grid; place-items: center; width: 20px; height: 20px; border-radius: 50%; font-style: normal; font-size: 11px; font-weight: 800; box-shadow: inset 0 0 0 1.5px var(--amo-locker-line2); }
  & li svg { width: 20px; height: 20px; padding: 3px; border-radius: 50%; background: var(--amo-locker-ok); color: white; stroke-width: 2.6; }
  & li.cur { color: var(--amo-locker-ink); font-weight: 650; }
  & li.cur i { background: var(--amo-locker-accent); box-shadow: none; }
}
.amo-locker .amo-locker-done {
  display: flex; flex-direction: column; align-items: flex-start; gap: 10px; animation: amo-locker-rise .5s var(--amo-locker-ease);
  & .tick { display: grid; place-items: center; width: 64px; height: 64px; border-radius: 50%; background: var(--amo-locker-ok); color: white; animation: amo-locker-pop .5s var(--amo-locker-spring); }
  & .tick svg { width: 34px; height: 34px; stroke-width: 2.4; stroke-dasharray: 24; stroke-dashoffset: 24; animation: amo-locker-draw .5s .2s var(--amo-locker-ease) forwards; }
  & h2 { font-size: 22px; font-weight: 800; letter-spacing: -.035em; text-wrap: balance; }
  & p { color: var(--amo-locker-mute); text-wrap: pretty; }
  & .amo-locker-go { align-self: stretch; margin-top: 6px; }
}
@keyframes amo-locker-draw { to { stroke-dashoffset: 0; } }

/* ── the wall ─────────────────────────────────────── */
.amo-locker .amo-locker-wallwrap { grid-area: wall; min-width: 0; min-height: 0; display: flex; flex-direction: column; gap: 10px; padding: 16px 18px 14px; }
.amo-locker .amo-locker-wallhead {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 10px; flex-wrap: wrap;
  & b { display: block; font-size: 15px; font-weight: 750; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
  & .legend { display: flex; gap: 12px; font-size: 11.5px; color: var(--amo-locker-mute); }
  & .legend span { display: inline-flex; align-items: center; gap: 5px; }
  & .legend i { width: 8px; height: 8px; border-radius: 50%; }
  & .legend .free { background: var(--amo-locker-ok); } & .legend .full { background: oklch(0.7 0.13 60); } & .legend .mine { background: var(--amo-locker-accent); box-shadow: 0 0 0 3px color-mix(in oklch, var(--amo-locker-accent) 40%, transparent); }
}
.amo-locker .amo-locker-wall {
  flex: 1; min-height: 0; display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); grid-template-rows: repeat(8, minmax(0, 1fr)) auto; gap: 6px; padding: 10px 10px 0;
  border-radius: 14px; background: linear-gradient(var(--amo-locker-frame), color-mix(in oklch, var(--amo-locker-frame), black 12%));
  box-shadow: inset 0 0 0 1px color-mix(in oklch, black 15%, transparent), 0 24px 40px -24px color-mix(in oklch, var(--amo-locker-ink) 60%, transparent);
}
.amo-locker .amo-locker-plinth { grid-column: 1 / -1; grid-row: 9; padding: 7px 4px 8px; text-align: center; font: 700 9.5px/1 system-ui, sans-serif; letter-spacing: .3em; color: color-mix(in oklch, white 60%, var(--amo-locker-frame)); }
.amo-locker .amo-locker-door {
  position: relative; min-height: 0; border-radius: 5px; perspective: 700px;
  background: radial-gradient(120% 90% at 50% 0%, oklch(0.34 0.01 70), oklch(0.2 0.01 70));
  & .in { position: absolute; inset: 0; border-radius: inherit; display: grid; place-items: center; box-shadow: inset 0 6px 14px black; overflow: hidden; transition: background .4s; }
  & .leaf {
    position: absolute; inset: 0; border-radius: inherit; transform-origin: 0 50%; transform-style: preserve-3d;
    background: repeating-linear-gradient(180deg, color-mix(in oklch, white 7%, transparent) 0 1px, transparent 1px 3px), linear-gradient(160deg, color-mix(in oklch, var(--amo-locker-metal), white calc(18% + var(--t) * 10%)), color-mix(in oklch, var(--amo-locker-metal), black 6%));
    box-shadow: inset 0 0 0 1px color-mix(in oklch, black 14%, transparent), inset 0 1px 0 color-mix(in oklch, white 50%, transparent);
    transition: transform .95s var(--amo-locker-swing), box-shadow .4s, filter .4s;
  }
  & .num { position: absolute; left: 6px; top: 6px; padding: 2px 5px; border-radius: 4px; background: color-mix(in oklch, var(--amo-locker-ink) 82%, transparent); color: var(--amo-locker-wall); font: 750 10.5px/1.1 ui-monospace, Menlo, monospace; }
  & .led { position: absolute; right: 7px; top: 8px; width: 6px; height: 6px; border-radius: 50%; background: oklch(0.7 0.13 60); box-shadow: 0 0 6px oklch(0.7 0.13 60); }
  & .handle { position: absolute; right: 7px; top: 50%; width: 4px; height: min(44%, 46px); translate: 0 -50%; border-radius: 2px; background: linear-gradient(90deg, color-mix(in oklch, var(--amo-locker-ink) 45%, var(--amo-locker-metal)), color-mix(in oklch, white 40%, var(--amo-locker-metal))); box-shadow: 1px 1px 2px color-mix(in oklch, black 25%, transparent); }
  & .vent { position: absolute; left: 8px; right: 22px; bottom: 7px; height: 5px; background: repeating-linear-gradient(90deg, color-mix(in oklch, black 28%, transparent) 0 6px, transparent 6px 9px); border-radius: 1px; opacity: .55; }
  &.sS .vent { display: none; }
  &.free .led { background: var(--amo-locker-ok); box-shadow: 0 0 6px var(--amo-locker-ok); }
  &.mine { z-index: 2; }
  &.mine .leaf { box-shadow: inset 0 0 0 1px color-mix(in oklch, black 14%, transparent), 0 0 0 3px var(--amo-locker-accent), 0 0 24px color-mix(in oklch, var(--amo-locker-accent) 75%, transparent); animation: amo-locker-glow 1.2s ease-in-out infinite; }
  &.mine .led { background: var(--amo-locker-accent); box-shadow: 0 0 8px var(--amo-locker-accent); }
  &.lowpick .num { background: var(--amo-locker-accent); color: var(--amo-locker-ink); }
  &.open { z-index: 5; }
  &.open .in { background: radial-gradient(90% 70% at 50% 0%, oklch(0.93 0.04 85), oklch(0.72 0.03 70)); box-shadow: inset 0 8px 16px color-mix(in oklch, black 35%, transparent); }
  &.open .leaf { transform: rotateY(-104deg); cursor: pointer; box-shadow: inset 0 0 0 1px color-mix(in oklch, black 14%, transparent), 12px 0 24px -6px color-mix(in oklch, black 40%, transparent); animation: none; filter: brightness(.92); }
  &.open .leaf:hover { filter: brightness(1); }
}
@keyframes amo-locker-glow { 50% { box-shadow: inset 0 0 0 1px color-mix(in oklch, black 14%, transparent), 0 0 0 3px var(--amo-locker-accent), 0 0 8px color-mix(in oklch, var(--amo-locker-accent) 40%, transparent); } }
.amo-locker .amo-locker-door .parcel {
  position: relative; width: 66%; height: min(72%, 92px); border-radius: 3px;
  background: linear-gradient(170deg, oklch(0.74 0.07 72), oklch(0.62 0.07 65)); box-shadow: 0 6px 10px -4px black;
  &::before { content: ""; position: absolute; left: 44%; top: 0; bottom: 0; width: 12%; background: color-mix(in oklch, oklch(0.85 0.05 80) 70%, transparent); }
  & i { position: absolute; right: 10%; bottom: 14%; width: 34%; height: 26%; max-height: 22px; border-radius: 2px; background: repeating-linear-gradient(180deg, oklch(0.4 0 0) 0 1px, transparent 1px 4px) 4px 4px / calc(100% - 8px) calc(100% - 8px) no-repeat, white; }
  &.out { animation: amo-locker-take .42s var(--amo-locker-ease) forwards; }
  &.put { animation: amo-locker-put .5s var(--amo-locker-ease) backwards; }
}
.amo-locker .amo-locker-door.sS .parcel { height: 64%; }
@keyframes amo-locker-take { to { scale: 1.25; translate: 0 -10%; opacity: 0; } }
@keyframes amo-locker-put { from { scale: 1.3; translate: 0 20%; opacity: 0; } }

/* ── phone ────────────────────────────────────────── */
.amo-locker .amo-locker-phone {
  grid-area: phone; min-height: 0; display: flex; flex-direction: column; gap: 10px; margin: 14px 14px 14px 0; padding: 14px 12px; border-radius: 26px; overflow-y: auto; scrollbar-width: none;
  background: var(--amo-locker-card); box-shadow: inset 0 0 0 6px color-mix(in oklch, var(--amo-locker-ink) 88%, transparent), 0 20px 40px -24px var(--amo-locker-ink);
  & header { display: flex; align-items: center; justify-content: space-between; padding: 6px 8px 0; }
  & .x { display: none; place-items: center; width: 28px; height: 28px; border-radius: 50%; background: var(--amo-locker-hover); }
  & ol { display: grid; gap: 8px; padding: 0 4px; }
  & li { display: grid; gap: 3px; padding: 9px 11px; border-radius: 16px 16px 16px 4px; background: color-mix(in oklch, var(--amo-locker-ink) 6%, var(--amo-locker-card)); animation: amo-locker-rise .4s var(--amo-locker-ease) backwards; animation-delay: calc(var(--i) * 60ms); }
  & .who { display: flex; justify-content: space-between; gap: 6px; font-size: 11.5px; }
  & .who small { color: var(--amo-locker-faint); }
  & li p { font-size: 12px; line-height: 1.45; text-wrap: pretty; }
  & .code { padding: 1px 6px; border-radius: 6px; background: var(--amo-locker-accent); font: 750 12px/1.4 ui-monospace, Menlo, monospace; letter-spacing: .04em; transition: scale .25s var(--amo-locker-spring); }
  & .code:hover:not(:disabled) { scale: 1.06; }
  & .code:disabled { background: var(--amo-locker-line); color: var(--amo-locker-faint); text-decoration: line-through; }
  & .hint { padding: 0 8px; font-size: 11px; color: var(--amo-locker-faint); text-align: center; }
}

/* toast */
.amo-locker .amo-locker-toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 9; translate: -50% 0; max-width: calc(100% - 32px); padding: 10px 16px; border-radius: 12px;
  background: var(--amo-locker-ink); color: var(--amo-locker-wall); font-weight: 600; box-shadow: 0 16px 36px -12px color-mix(in oklch, var(--amo-locker-ink) 55%, transparent);
  transition: opacity .25s, translate .45s var(--amo-locker-spring); @starting-style { opacity: 0; translate: -50% 12px; }
}

/* ── responsive ───────────────────────────────────── */
@container (max-width: 1099px) {
  .amo-locker .amo-locker-app { grid-template-columns: clamp(290px, 38cqi, 330px) minmax(0, 1fr); grid-template-areas: "kiosk wall"; }
  .amo-locker .amo-locker-msgbtn { display: grid; }
  .amo-locker .amo-locker-phone { grid-area: wall; z-index: 6; justify-self: end; align-self: start; width: min(260px, calc(100% - 20px)); max-height: calc(100% - 20px); margin: 10px; display: none; }
  .amo-locker[data-phone="1"] .amo-locker-phone { display: flex; animation: amo-locker-rise .35s var(--amo-locker-ease); }
  .amo-locker .amo-locker-phone .x { display: grid; }
  .amo-locker .amo-locker-code span { width: 37px; }
}
@container (max-width: 759px) {
  .amo-locker .amo-locker-tabs {
    display: flex; gap: 4px; padding: 8px 10px; border-bottom: 1px solid var(--amo-locker-line);
    & button { flex: 1; height: 34px; border-radius: 9px; font-weight: 650; color: var(--amo-locker-mute); }
    & button[aria-selected="true"] { background: var(--amo-locker-ink); color: var(--amo-locker-wall); }
  }
  .amo-locker .amo-locker-msgbtn { display: none; }
  .amo-locker .amo-locker-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "one"; }
  .amo-locker .amo-locker-kiosk, .amo-locker .amo-locker-wallwrap, .amo-locker .amo-locker-phone { grid-area: one; border: 0; }
  .amo-locker .amo-locker-phone { display: flex; justify-self: stretch; width: auto; margin: 12px; }
  .amo-locker:not([data-view="kiosk"]) .amo-locker-kiosk { display: none; }
  .amo-locker:not([data-view="wall"]) .amo-locker-wallwrap { visibility: hidden; }
  .amo-locker:not([data-view="phone"]) .amo-locker-phone { display: none; }
  .amo-locker .amo-locker-wallwrap { padding: 12px; }
  .amo-locker .amo-locker-brand small { white-space: normal; }
}
@container (max-width: 420px) {
  .amo-locker .amo-locker-code span { width: 36px; height: 48px; font-size: 21px; }
  .amo-locker .amo-locker-a11y span { display: none; }
  .amo-locker .amo-locker-door .num { font-size: 9px; padding: 1px 3px; left: 3px; top: 3px; }
  .amo-locker .amo-locker-door .handle { right: 4px; width: 3px; }
}

@media (prefers-reduced-motion: reduce) {
  .amo-locker {
    & *, & *::before, & *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
    & .amo-locker-door.mine .leaf { animation: none; }
    & .amo-locker-code span.cur::after { animation: none; }
  }
}

js:
/* ── Cubby · parcel locker kiosk ───────────────────────────────────────────
   The wall is a CSS grid where each door spans the rows its size needs, and
   every door is two layers: the compartment and a hinged leaf with its own
   perspective, so opening is a rotateY around the left edge that swings out
   over its neighbours. A valid code lights the matching doors, opens them
   one at a time, and closing a door (from the kiosk or by pushing the leaf
   on the wall) moves to the next. Three wrong codes lock the keypad for 30
   seconds. Returns find the best free door of the right size, preferring
   wheelchair-height doors when Lower doors is on. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const ico = p => '<svg viewBox="0 0 24 24" aria-hidden="true">' + p + '</svg>';
const I = {
  box: '<path d="M4 7.5 12 3l8 4.5v9L12 21l-8-4.5Z"/><path d="m4 7.5 8 4.5 8-4.5M12 12v9"/>',
  back: '<path d="M9 7 4 12l5 5M4 12h11a5 5 0 0 1 0 10h-1"/>',
  del: '<path d="M9 5h11v14H9l-6-7Z"/><path d="m12.5 9.5 5 5M17.5 9.5l-5 5"/>',
  check: '<path d="m5 12.5 4.5 4.5L19 7.5"/>',
  door: '<rect x="5" y="3" width="14" height="18" rx="1.5"/><path d="M15 12h.01"/>',
  lock: '<rect x="5" y="10.5" width="14" height="10" rx="2"/><path d="M8 10.5V7.5a4 4 0 0 1 8 0v3"/>',
  msg: '<path d="M5 18.5V7a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2v7a2 2 0 0 1-2 2H8Z"/>',
  ret: '<path d="M4 9h11a5 5 0 0 1 0 10H9"/><path d="m8 5-4 4 4 4"/>',
  help: '<circle cx="12" cy="12" r="8.5"/><path d="M9.6 9.5a2.5 2.5 0 1 1 3.4 2.3c-.6.3-1 .8-1 1.5v.4M12 16.8v.01"/>',
};

/* ── the wall: six columns, eight row-units tall ─────────────────────── */
const SIZE = { S: { h: 1, name: 'Small', dims: '9 × 38 × 64 cm' }, M: { h: 2, name: 'Medium', dims: '19 × 38 × 64 cm' }, L: { h: 3, name: 'Large', dims: '39 × 38 × 64 cm' } };
const COLS = [['L', 'M', 'S', 'M'], ['S', 'S', 'M', 'S', 'L'], ['M', 'M', 'M', 'M'], ['S', 'M', 'L', 'S', 'S'], ['L', 'L', 'M'], ['M', 'S', 'S', 'S', 'L']];
function rng(a) { return () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
const R = rng(42), DOORS = [];
COLS.forEach((col, c) => { let r = 1; col.forEach(sz => { DOORS.push({ n: DOORS.length + 1, c: c + 1, r, size: sz, state: R() < .62 ? 'full' : 'free', tint: R() }); r += SIZE[sz].h; }); });
const DN = n => DOORS[n - 1];
/* codes that the phone has received */
const CODES = {
  '482913': { kind: 'collect', who: 'Ashgrove Books', items: [{ door: 12, what: 'Book parcel · 0.8 kg' }], by: 'Tue 6 Oct' },
  '771206': { kind: 'collect', who: 'Halcyon Bikes', items: [{ door: 16, what: 'Bike wheel · 2.9 kg' }, { door: 22, what: 'Tyres and tubes · 1.4 kg' }], by: 'Mon 5 Oct' },
  '305588': { kind: 'expired', who: 'Wren Coffee Roasters', note: 'This parcel wasn’t collected by 30 Sep and has gone back to Wren Coffee Roasters.' },
  '640217': { kind: 'return', who: 'Fernway Outdoor', size: 'M', what: 'Waterproof jacket return', track: 'CB 7Q4 218' },
};
Object.values(CODES).forEach(c => (c.items || []).forEach(it => { DN(it.door).state = 'full'; DN(it.door).code = true; }));
const MSGS = [
  { from: 'Cubby', at: '08:12', code: '482913', text: 'Your parcel from Ashgrove Books is ready at Cubby Linden Street. Collect by Tue 6 Oct with code' },
  { from: 'Cubby', at: 'Yesterday', code: '771206', text: '2 parcels from Halcyon Bikes are waiting at Cubby Linden Street. Collect by Mon 5 Oct with code' },
  { from: 'Fernway Outdoor', at: 'Yesterday', code: '640217', text: 'Your return is approved — no label needed. Drop it at any Cubby with code' },
  { from: 'Cubby', at: '28 Sep', code: '305588', text: 'Reminder: your Wren Coffee Roasters parcel must be collected by 30 Sep. Code' },
];

/* ── state ───────────────────────────────────────────────────────────── */
const S = { mode: 'collect', step: 'enter', code: '', tries: 3, lockUntil: 0, job: null, idx: 0, low: false, view: 'kiosk', phone: false, err: '' };
const fmt = c => c.slice(0, 3) + ' ' + c.slice(3);

/* ── wall ────────────────────────────────────────────────────────────── */
const doorCls = d => 'amo-locker-door s' + d.size + ' ' + d.state + (d.mine ? ' mine' : '') + (d.open ? ' open' : '') + (d.low ? ' lowpick' : '');
const parcelHTML = d => d.parcel ? '<span class="parcel ' + d.parcel + '"><i></i></span>' : '';
function doorHTML(d) {
  return '<div class="' + doorCls(d) + '" data-door="' + d.n + '" style="grid-column:' + d.c + ';grid-row:' + d.r + ' / span ' + SIZE[d.size].h + ';--t:' + d.tint.toFixed(2) + '">' +
    '<div class="in">' + parcelHTML(d) + '</div>' +
    '<div class="leaf"' + (d.open ? ' role="button" tabindex="0" data-close="' + d.n + '" aria-label="Close door ' + d.n + '" title="Push to close"' : ' aria-hidden="true"') + '>' +
    '<span class="num">' + String(d.n).padStart(2, '0') + '</span><i class="led"></i><i class="handle"></i><i class="vent"></i></div></div>';
}
function renderWallHead() {
  const free = DOORS.filter(d => d.state === 'free').length;
  $('[data-wallhead]').innerHTML = '<div><span class="k">Locker 0417 · Linden Street</span><b>' + DOORS.length + ' doors · ' + free + ' free</b></div><div class="legend" aria-hidden="true"><span><i class="free"></i>Free</span><span><i class="full"></i>In use</span><span><i class="mine"></i>Yours</span></div>';
}
function renderWall() {
  renderWallHead();
  $('[data-wall]').innerHTML = DOORS.map(doorHTML).join('') + '<div class="amo-locker-plinth" aria-hidden="true">CUBBY · 24 h · CCTV in operation</div>';
}
/* update a door in place, so the leaf keeps its element and its transform transitions */
function setDoor(n, patch) {
  const d = DN(n), had = d.parcel;
  Object.assign(d, patch);
  const el = $('[data-door="' + n + '"]'); if (!el) { renderWall(); return; }
  el.className = doorCls(d);
  if (d.parcel !== had) el.querySelector('.in').innerHTML = parcelHTML(d);
  const leaf = el.querySelector('.leaf');
  if (d.open) { leaf.setAttribute('role', 'button'); leaf.setAttribute('tabindex', '0'); leaf.dataset.close = n; leaf.setAttribute('aria-label', 'Close door ' + n); leaf.title = 'Push to close'; leaf.removeAttribute('aria-hidden'); }
  else { ['role', 'tabindex', 'data-close', 'aria-label', 'title'].forEach(x => leaf.removeAttribute(x)); leaf.setAttribute('aria-hidden', 'true'); }
}

/* ── kiosk ───────────────────────────────────────────────────────────── */
function codeBoxes() {
  return '<div class="amo-locker-code' + (S.err ? ' err' : '') + '" data-codebox role="group" aria-label="Code, ' + S.code.length + ' of 6 digits">' + [0, 1, 2, 3, 4, 5].map(i => '<span class="' + (i < S.code.length ? 'on' : '') + (i === S.code.length ? ' cur' : '') + (i === 3 ? ' gap' : '') + '">' + (S.code[i] || '') + '</span>').join('') + '</div>';
}
function keypad(disabled) {
  const keys = ['1', '2', '3', '4', '5', '6', '7', '8', '9', 'clear', '0', 'back'];
  return '<div class="amo-locker-keys" role="group" aria-label="Keypad">' + keys.map(k => {
    const dis = disabled || (k === 'clear' || k === 'back' ? !S.code.length : S.code.length >= 6);
    const why = disabled ? 'Keypad locked' : k === 'clear' || k === 'back' ? 'Nothing to delete' : 'All 6 digits entered';
    return '<button type="button" data-key="' + k + '" class="' + (k.length > 1 ? 'fn' : '') + '"' + (dis ? ' disabled title="' + why + '"' : '') + ' aria-label="' + (k === 'back' ? 'Delete digit' : k === 'clear' ? 'Clear code' : k) + '">' + (k === 'back' ? ico(I.del) : k === 'clear' ? 'Clear' : k) + '</button>';
  }).join('') + '</div>';
}
function renderModes() {
  $('[data-modes]').innerHTML = [['collect', 'Collect', I.box], ['return', 'Return', I.ret]].map(([k, t, ic]) => '<button type="button" role="tab" data-mode="' + k + '" aria-selected="' + (S.mode === k) + '"' + (S.step !== 'enter' && S.mode !== k ? ' disabled title="Finish the current ' + S.mode + ' first"' : '') + '>' + ico(ic) + t + '</button>').join('');
}
function renderScreen() {
  const sc = $('[data-screen]'), job = S.job;
  let h = '';
  if (S.step === 'enter') {
    const locked = Date.now() < S.lockUntil, full = S.code.length === 6;
    h = '<div class="amo-locker-copy"><h2>' + (S.mode === 'collect' ? 'Enter your collection code' : 'Enter your return code') + '</h2><p>' + (S.mode === 'collect' ? 'It’s the 6-digit code in the text we sent when your parcel arrived. Type it or tap the keys.' : 'Your retailer sends a 6-digit drop-off code when the return is approved. Type it or tap the keys.') + '</p></div>' +
      codeBoxes() + '<p class="amo-locker-msg' + (S.err ? ' bad' : '') + '" data-msg role="alert">' + (locked ? ico(I.lock) + 'Too many tries — keypad unlocks in <b data-lockleft>' + Math.ceil((S.lockUntil - Date.now()) / 1000) + '</b> s' : S.err ? esc(S.err) : '&nbsp;') + '</p>' +
      keypad(locked) +
      '<button type="button" class="amo-locker-go" data-act="submit"' + (full && !locked ? '' : ' disabled title="' + (locked ? 'Keypad locked' : 'Enter all 6 digits') + '"') + '>' + (S.mode === 'collect' ? 'Open my door' : 'Find a door') + '<kbd>↵</kbd></button>';
  } else if (S.step === 'open') {
    const it = S.mode === 'collect' ? job.items[S.idx] : null, n = S.mode === 'collect' ? it.door : job.door, d = DN(n);
    h = '<div class="amo-locker-open"><span class="k">' + (S.mode === 'collect' ? 'Parcel ' + (S.idx + 1) + ' of ' + job.items.length + ' · ' + esc(job.who) : esc(job.who) + ' return') + '</span>' +
      '<div class="big"><span>Door</span><b>' + String(n).padStart(2, '0') + '</b></div>' +
      '<p>' + (S.mode === 'collect' ? 'Take your parcel (' + esc(it.what) + ') and push the door shut.' : 'Place the parcel inside — ' + SIZE[d.size].name.toLowerCase() + ' door, ' + SIZE[d.size].dims + ' — then push the door shut.') + '</p>' +
      (S.mode === 'collect' && job.items.length > 1 ? '<ol class="amo-locker-steps">' + job.items.map((x, i) => '<li class="' + (i < S.idx ? 'done' : i === S.idx ? 'cur' : '') + '">' + (i < S.idx ? ico(I.check) : '<i>' + (i + 1) + '</i>') + 'Door ' + x.door + ' · ' + esc(x.what) + '</li>').join('') + '</ol>' : '') +
      '<button type="button" class="amo-locker-go" data-act="closed">' + ico(I.door) + 'I’ve closed door ' + n + '</button>' +
      '<button type="button" class="amo-locker-link" data-act="reopen">' + ico(I.help) + 'Door didn’t open?</button></div>';
  } else if (S.step === 'done') {
    h = '<div class="amo-locker-done"><span class="tick">' + ico(I.check) + '</span><h2>' + (S.mode === 'collect' ? (job.items.length > 1 ? 'All ' + job.items.length + ' parcels collected' : 'Parcel collected') : 'Return dropped off') + '</h2>' +
      '<p>' + (S.mode === 'collect' ? 'From ' + esc(job.who) + ' · door' + (job.items.length > 1 ? 's ' : ' ') + job.items.map(x => x.door).join(' and ') + '. A receipt is on its way to your phone.' : 'Tracking ' + esc(job.track) + '. ' + esc(job.who) + ' refunds you once the courier scans it, usually within 2 days.') + '</p>' +
      '<button type="button" class="amo-locker-go" data-act="reset">Done</button></div>';
  }
  const had = root.contains(document.activeElement);
  sc.innerHTML = h;
  renderModes();
  /* the focused control may have just been replaced: keep focus in the kiosk so typing still works */
  if (had && !root.contains(document.activeElement)) root.focus({ preventScroll: true });
}

/* ── phone ───────────────────────────────────────────────────────────── */
function renderPhone() {
  $('[data-phone]').innerHTML = '<header><span class="k">Messages</span><button type="button" class="x" data-act="phoneclose" aria-label="Close messages">' + ico('<path d="M6 6l12 12M18 6 6 18"/>') + '</button></header><ol>' + MSGS.map((m, i) => {
    const c = CODES[m.code], used = c.used;
    return '<li style="--i:' + i + '"><div class="who"><b>' + esc(m.from) + '</b><small>' + esc(m.at) + '</small></div><p>' + esc(m.text) + ' <button type="button" class="code" data-use="' + m.code + '"' + (used ? ' disabled title="Already used"' : '') + '>' + fmt(m.code) + '</button></p></li>';
  }).join('') + '</ol><p class="hint">Tap a code to type it on the kiosk.</p>';
}

/* ── flow ────────────────────────────────────────────────────────────── */
function press(k) {
  if (S.step !== 'enter' || Date.now() < S.lockUntil) return;
  S.err = '';
  if (k === 'back') S.code = S.code.slice(0, -1);
  else if (k === 'clear') S.code = '';
  else if (S.code.length < 6) S.code += k;
  renderScreen();
}
function submit() {
  if (S.code.length !== 6 || Date.now() < S.lockUntil) return;
  const c = CODES[S.code];
  if (c && c.kind === 'expired') { S.err = c.note; S.code = ''; renderScreen(); shake(); return; }
  if (!c || c.used || c.kind !== S.mode) {
    S.tries--;
    if (c && !c.used && c.kind !== S.mode) { S.tries++; S.err = 'That’s a ' + c.kind + ' code — switch to ' + (c.kind === 'return' ? 'Return' : 'Collect') + ' above.'; }
    else if (S.tries <= 0) { S.lockUntil = Date.now() + 30000; S.tries = 3; S.err = ''; startLockTimer(); }
    else S.err = (c && c.used ? 'That code has already been used. ' : 'That code doesn’t match a parcel here. ') + S.tries + (S.tries === 1 ? ' try' : ' tries') + ' left.';
    S.code = ''; renderScreen(); shake(); return;
  }
  S.tries = 3;
  if (S.mode === 'collect') { S.job = c; S.idx = 0; S.step = 'open'; c.items.forEach(it => setDoor(it.door, { mine: true })); renderScreen(); openDoor(c.items[0].door, true); }
  else {
    /* best free door of the right size; with Lower doors on, wheelchair height wins */
    const reach = d => d.r >= 4;   /* doors starting in the lower half can be reached seated */
    const fits = DOORS.filter(d => d.state === 'free' && SIZE[d.size].h >= SIZE[c.size].h).sort((a, b) => (S.low ? reach(b) - reach(a) : 0) || (SIZE[a.size].h - SIZE[b.size].h) || (Math.abs(a.r - 4) - Math.abs(b.r - 4)));
    if (!fits.length) { S.err = 'No free door is big enough right now — try Cubby Market Hall.'; S.code = ''; renderScreen(); return; }
    S.job = { ...c, door: fits[0].n }; S.step = 'open';
    setDoor(fits[0].n, { mine: true, low: S.low && fits[0].r >= 4 });
    renderScreen(); openDoor(fits[0].n, false);
  }
  S.code = '';
}
const setView = v => { S.view = v; root.dataset.view = v; $$('.amo-locker-tabs [role=tab]').forEach(b => b.setAttribute('aria-selected', String(b.dataset.view === v))); };
function openDoor(n, withParcel) {
  if (root.clientWidth < 760) setView('wall');   /* on a phone, show the wall so the door is seen opening */
  setDoor(n, { parcel: withParcel ? 'here' : null });
  const el = $('[data-door="' + n + '"]');
  el.scrollIntoView({ block: 'nearest', inline: 'nearest' });
  /* light up first, then swing: a beat so the eye finds the door */
  setTimeout(() => { if (!root.isConnected) return; setDoor(n, { open: true }); $('[data-close="' + n + '"]')?.focus({ preventScroll: true }); toast('Door ' + n + ' is open'); }, RM.matches ? 0 : 420);
}
function closeDoor(n) {
  const d = DN(n); if (!d.open) return;
  if (S.mode === 'collect') {
    setDoor(n, { parcel: 'out' });
    setTimeout(() => { if (!root.isConnected) return; setDoor(n, { open: false, mine: false, state: 'free', parcel: null }); afterClose(); }, RM.matches ? 0 : 420);
  } else {
    setDoor(n, { parcel: 'put' });
    setTimeout(() => { if (!root.isConnected) return; setDoor(n, { open: false, mine: false, low: false, state: 'full' }); afterClose(); }, RM.matches ? 0 : 520);
  }
}
function afterClose() {
  const job = S.job;
  if (S.mode === 'collect' && S.idx < job.items.length - 1) { S.idx++; renderScreen(); openDoor(job.items[S.idx].door, true); return; }
  S.step = 'done'; Object.keys(CODES).forEach(k => { if (CODES[k] === job || (S.mode === 'return' && CODES[k].track === job.track)) CODES[k].used = true; });
  renderWallHead(); renderScreen(); renderPhone();
  if (root.clientWidth < 760) setView('kiosk');
}
let lockT = 0;
function startLockTimer() {
  clearInterval(lockT);
  lockT = setInterval(() => {
    if (!root.isConnected) { clearInterval(lockT); return; }
    const left = Math.ceil((S.lockUntil - Date.now()) / 1000), el = $('[data-lockleft]');
    if (left <= 0) { clearInterval(lockT); S.err = ''; renderScreen(); toast('Keypad unlocked'); return; }
    if (el) el.textContent = left;
  }, 500);
}
function shake() { if (RM.matches) return; $('[data-codebox]')?.animate([{ transform: 'translateX(0)' }, { transform: 'translateX(-9px)' }, { transform: 'translateX(8px)' }, { transform: 'translateX(-5px)' }, { transform: 'translateX(3px)' }, { transform: 'none' }], { duration: 420, easing: 'cubic-bezier(.3,.7,.4,1)' }); }

/* ── toast ───────────────────────────────────────────────────────────── */
let toastT = 0;
function toast(msg) { const t = $('[data-toast]'); t.textContent = msg; t.hidden = false; clearTimeout(toastT); toastT = setTimeout(() => { if (root.isConnected) t.hidden = true; }, 2600); }

/* ── events ──────────────────────────────────────────────────────────── */
root.addEventListener('click', e => {
  const t = e.target;
  const tab = t.closest('.amo-locker-tabs [role=tab]'); if (tab) { S.view = tab.dataset.view; root.dataset.view = S.view; $$('.amo-locker-tabs [role=tab]').forEach(b => b.setAttribute('aria-selected', String(b === tab))); return; }
  const md = t.closest('[data-mode]'); if (md && !md.disabled) { S.mode = md.dataset.mode; S.code = ''; S.err = ''; renderScreen(); return; }
  const k = t.closest('[data-key]'); if (k && !k.disabled) { press(k.dataset.key); $('[data-key="' + k.dataset.key + '"]')?.focus({ preventScroll: true }); return; }
  const cl = t.closest('[data-close]'); if (cl) { closeDoor(+cl.dataset.close); return; }
  const u = t.closest('[data-use]');
  if (u && !u.disabled) {
    const c = CODES[u.dataset.use];
    if (S.step !== 'enter') { toast('Finish at the kiosk first'); return; }
    S.mode = c.kind === 'return' ? 'return' : 'collect'; S.code = u.dataset.use; S.err = ''; renderScreen();
    if (root.clientWidth < 760) { S.view = 'kiosk'; root.dataset.view = 'kiosk'; $$('.amo-locker-tabs [role=tab]').forEach(b => b.setAttribute('aria-selected', String(b.dataset.view === 'kiosk'))); }
    toast('Typed ' + fmt(u.dataset.use) + ' on the keypad'); return;
  }
  const b = t.closest('[data-act]'); if (!b || b.disabled) return;
  const a = b.dataset.act;
  if (a === 'submit') submit();
  else if (a === 'closed') { const n = S.mode === 'collect' ? S.job.items[S.idx].door : S.job.door; closeDoor(n); }
  else if (a === 'reopen') {
    const n = S.mode === 'collect' ? S.job.items[S.idx].door : S.job.door, el = $('[data-door="' + n + '"]');
    if (el && !RM.matches) el.animate([{ transform: 'none' }, { transform: 'translateX(-3px)' }, { transform: 'translateX(3px)' }, { transform: 'none' }], { duration: 260, iterations: 2 });
    setDoor(n, { open: true }); toast('Released door ' + n + ' again — give it a gentle pull');
  }
  else if (a === 'reset') { S.step = 'enter'; S.job = null; S.idx = 0; S.code = ''; S.err = ''; renderScreen(); }
  else if (a === 'low') { S.low = !S.low; b.setAttribute('aria-pressed', String(S.low)); toast(S.low ? 'Returns will use doors at wheelchair height' : 'Any door height'); }
  else if (a === 'phone' || a === 'phoneclose') { S.phone = a === 'phone' ? !S.phone : false; root.dataset.phone = S.phone ? '1' : '0'; $('[data-act=phone]')?.setAttribute('aria-expanded', String(S.phone)); if (a === 'phoneclose' && root.clientWidth < 760) { S.view = 'kiosk'; root.dataset.view = 'kiosk'; $$('.amo-locker-tabs [role=tab]').forEach(x => x.setAttribute('aria-selected', String(x.dataset.view === 'kiosk'))); } }
});
root.addEventListener('keydown', e => {
  const t = e.target;
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  if (S.step === 'enter') {
    if (/^[0-9]$/.test(e.key)) { e.preventDefault(); press(e.key); return; }
    if (e.key === 'Backspace') { e.preventDefault(); press('back'); return; }
      if (e.key === 'Escape') { press('clear'); return; }
    if (e.key === 'Enter' && !(t.closest && t.closest('button'))) { e.preventDefault(); submit(); return; }
  } else if (S.step === 'open' && e.key === 'Enter' && !(t.closest && t.closest('button'))) { e.preventDefault(); $('[data-act=closed]')?.click(); }
  const lf = t.closest && t.closest('[data-close]');
  if (lf && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); closeDoor(+lf.dataset.close); return; }
  const grp = t.closest && t.closest('[role=tablist]');
  if (grp && (e.key === 'ArrowLeft' || e.key === 'ArrowRight')) { const items = $$('[role=tab]:not(:disabled)', grp), i = items.indexOf(t.closest('[role=tab]')); e.preventDefault(); const n = items[(i + (e.key === 'ArrowRight' ? 1 : -1) + items.length) % items.length]; n.click(); n.focus(); }
});

/* header button for mid widths: the phone becomes a drawer */
$('.amo-locker-brand').insertAdjacentHTML('beforeend', '<button type="button" class="amo-locker-msgbtn" data-act="phone" aria-expanded="false" title="Messages">' + ico(I.msg) + '<span>' + MSGS.length + '</span></button>');
renderWall(); renderScreen(); renderPhone();

css:
.amo-fleet {
  /* re-theme with these four; status and category colours are below */
  --amo-fleet-paper: oklch(0.985 0.004 100);
  --amo-fleet-ink: oklch(0.22 0.015 150);
  --amo-fleet-accent: oklch(0.5 0.1 160);
  --amo-fleet-plate: oklch(0.93 0.13 95);
  --amo-fleet-soon: oklch(0.72 0.15 68);
  --amo-fleet-over: oklch(0.57 0.19 28);
  --amo-fleet-shop: oklch(0.55 0.08 250);
  --amo-fleet-c-service: var(--amo-fleet-accent);
  --amo-fleet-c-tyres: oklch(0.42 0.03 250);
  --amo-fleet-c-repair: oklch(0.76 0.14 70);
  --amo-fleet-c-inspect: oklch(0.66 0.09 35);

  --amo-fleet-card: color-mix(in oklch, var(--amo-fleet-paper), white 60%);
  --amo-fleet-well: color-mix(in oklch, var(--amo-fleet-ink) 4%, var(--amo-fleet-paper));
  --amo-fleet-line: color-mix(in oklch, var(--amo-fleet-ink) 10%, transparent);
  --amo-fleet-line2: color-mix(in oklch, var(--amo-fleet-ink) 18%, transparent);
  --amo-fleet-hover: color-mix(in oklch, var(--amo-fleet-ink) 4.5%, transparent);
  --amo-fleet-mute: color-mix(in oklch, var(--amo-fleet-ink) 60%, var(--amo-fleet-paper));
  --amo-fleet-faint: color-mix(in oklch, var(--amo-fleet-ink) 40%, var(--amo-fleet-paper));
  --amo-fleet-ease: cubic-bezier(.2, .8, .2, 1);
  --amo-fleet-spring: linear(0, 0.14 6%, 0.47 13%, 0.82 21%, 1.02 29%, 1.05 36%, 1.03 45%, 1.005 58%, 1);

  position: relative; width: 100%; height: var(--amo-fleet-h, 680px); box-sizing: border-box;
  container-type: inline-size; overflow: clip; isolation: isolate; display: flex; flex-direction: column; border-radius: 18px;
  background: var(--amo-fleet-paper); color: var(--amo-fleet-ink); color-scheme: light; accent-color: var(--amo-fleet-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; box-shadow: inset 0 0 0 1px var(--amo-fleet-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & :focus-visible { outline: 2px solid var(--amo-fleet-accent); outline-offset: 2px; }
  & button, & input, & select { font: inherit; color: inherit; }
  & button { cursor: pointer; background: none; border: 0; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & h2, & h3, & p, & ul, & ol, & table { margin: 0; padding: 0; }
  & ul, & ol { list-style: none; }
  & [hidden] { display: none !important; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 4px; font: 650 10px/1 ui-monospace, Menlo, monospace; color: inherit; opacity: .6; box-shadow: inset 0 0 0 1px currentColor; }
  & .k { font-size: 10.5px; font-weight: 750; letter-spacing: .09em; text-transform: uppercase; color: var(--amo-fleet-faint); }
  & .plate { display: inline-block; padding: 4px 8px; border-radius: 5px; background: var(--amo-fleet-plate); color: oklch(0.2 0.02 90); font: 800 14px/1 ui-monospace, Menlo, monospace; letter-spacing: .07em; box-shadow: inset 0 0 0 1.5px oklch(0.2 0.02 90 / .65); white-space: nowrap; }
  & .plate.sm { font-size: 10.5px; padding: 2px 5px; }
  & .c-service { --c: var(--amo-fleet-c-service); } & .c-tyres { --c: var(--amo-fleet-c-tyres); } & .c-repair { --c: var(--amo-fleet-c-repair); } & .c-inspect { --c: var(--amo-fleet-c-inspect); }
}
.amo-fleet .amo-fleet-tabs { display: none; }
.amo-fleet .amo-fleet-app { position: relative; flex: 1; min-height: 0; display: grid; grid-template-columns: clamp(260px, 26cqi, 300px) minmax(0, 1fr) clamp(280px, 28cqi, 330px); grid-template-areas: "list detail costs"; }

/* ── list ─────────────────────────────────────────── */
.amo-fleet .amo-fleet-list { grid-area: list; min-height: 0; display: flex; flex-direction: column; gap: 10px; padding: 16px 0 0; border-right: 1px solid var(--amo-fleet-line); }
.amo-fleet .amo-fleet-brand { display: flex; align-items: center; gap: 10px; padding: 0 14px; & b { display: block; font-size: 17px; font-weight: 820; letter-spacing: -.04em; line-height: 1.1; } & small { display: block; font-size: 11.5px; color: var(--amo-fleet-mute); } }
.amo-fleet .amo-fleet-logo { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; background: var(--amo-fleet-ink); color: var(--amo-fleet-paper); & svg { width: 22px; height: 22px; stroke-width: 1.7; } }
.amo-fleet .amo-fleet-search {
  display: flex; align-items: center; gap: 8px; margin: 0 14px; padding: 0 10px; height: 36px; border-radius: 10px; background: var(--amo-fleet-well); box-shadow: inset 0 0 0 1px var(--amo-fleet-line);
  & svg { color: var(--amo-fleet-faint); }
  & input { flex: 1; min-width: 0; border: 0; background: none; outline: none; }
  &:has(input:focus) { box-shadow: inset 0 0 0 2px var(--amo-fleet-accent); background: var(--amo-fleet-card); }
  & kbd { opacity: .4; }
}
.amo-fleet .amo-fleet-chips {
  display: flex; flex-wrap: wrap; gap: 4px; padding: 0 14px;
  & button { display: inline-flex; align-items: center; gap: 4px; height: 26px; padding: 0 9px; border-radius: 99px; font-size: 11.5px; font-weight: 650; color: var(--amo-fleet-mute); box-shadow: inset 0 0 0 1px var(--amo-fleet-line2); }
  & button span { font-size: 10.5px; font-variant-numeric: tabular-nums; opacity: .75; }
  & button:hover { color: var(--amo-fleet-ink); }
  & [aria-checked="true"] { background: var(--amo-fleet-ink); color: var(--amo-fleet-paper); box-shadow: none; }
  & .f-over span { color: var(--amo-fleet-over); opacity: 1; font-weight: 800; }
}
.amo-fleet .amo-fleet-rows { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: thin; display: grid; align-content: start; gap: 4px; padding: 2px 8px 12px; }
.amo-fleet .amo-fleet-row {
  --sc: var(--amo-fleet-accent);
  position: relative; display: grid; grid-template-columns: 30px minmax(0, 1fr) auto; align-items: center; gap: 10px; padding: 9px 10px 12px; border-radius: 12px; cursor: pointer; outline-offset: -2px;
  transition: background .15s; animation: amo-fleet-in .4s var(--amo-fleet-ease) backwards; animation-delay: calc(var(--i) * 30ms);
  &:hover { background: var(--amo-fleet-hover); }
  &[aria-selected="true"] { background: var(--amo-fleet-card); box-shadow: inset 0 0 0 1px var(--amo-fleet-line2), 0 6px 16px -12px var(--amo-fleet-line2); }
  &.st-soon { --sc: var(--amo-fleet-soon); } &.st-over { --sc: var(--amo-fleet-over); } &.st-shop { --sc: var(--amo-fleet-shop); }
  & .ic { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 9px; background: var(--amo-fleet-well); color: var(--amo-fleet-mute); }
  & .tx b { display: block; font: 750 13px/1.2 ui-monospace, Menlo, monospace; letter-spacing: .04em; }
  & .tx small { display: block; font-size: 11.5px; color: var(--amo-fleet-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .st { display: grid; justify-items: end; }
  & .st em { font-style: normal; font-size: 11px; font-weight: 750; color: color-mix(in oklch, var(--sc), black 12%); }
  & .st small { font-size: 11px; color: var(--amo-fleet-mute); font-variant-numeric: tabular-nums; white-space: nowrap; }
  & .bar { position: absolute; left: 50px; right: 10px; bottom: 6px; height: 3px; border-radius: 2px; background: linear-gradient(90deg, var(--sc) var(--p), var(--amo-fleet-line) var(--p)); }
}
@keyframes amo-fleet-in { from { opacity: 0; translate: 0 6px; } }
.amo-fleet .amo-fleet-none { padding: 18px 10px; color: var(--amo-fleet-mute); text-align: center; text-wrap: pretty; }

/* ── detail ───────────────────────────────────────── */
.amo-fleet .amo-fleet-detail { grid-area: detail; position: relative; min-width: 0; min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; display: grid; align-content: start; gap: 14px; padding: 16px 20px 24px; }
.amo-fleet .amo-fleet-vhead {
  display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap;
  & .id { display: flex; align-items: center; gap: 12px; min-width: 0; }
  & .id b { display: block; font-size: clamp(16px, 1.8cqi, 19px); font-weight: 780; letter-spacing: -.025em; line-height: 1.2; }
  & .id small { display: block; font-size: 12px; color: var(--amo-fleet-mute); }
}
.amo-fleet .amo-fleet-back { display: none; }
.amo-fleet .amo-fleet-odo {
  display: inline-flex; align-items: center; gap: 2px; padding: 4px; border-radius: 8px; background: oklch(0.2 0.01 150); box-shadow: inset 0 0 0 1px black, 0 1px 0 var(--amo-fleet-line2);
  & i { display: grid; place-items: center; width: 19px; height: 28px; border-radius: 3px; font: 700 17px/1 ui-monospace, Menlo, monospace; font-style: normal; color: oklch(0.96 0.01 90); background: linear-gradient(oklch(0.16 0 0), oklch(0.3 0.005 150) 50%, oklch(0.16 0 0)); box-shadow: inset 0 2px 3px black, inset 0 -2px 3px black; }
  & i:last-of-type { color: oklch(0.2 0 0); background: linear-gradient(oklch(0.82 0 0), oklch(0.97 0 0) 50%, oklch(0.82 0 0)); }
  & b { padding: 0 5px 0 4px; font-size: 10.5px; font-weight: 700; color: oklch(0.8 0.01 150); }
}
.amo-fleet .amo-fleet-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.amo-fleet .amo-fleet-btn {
  display: inline-flex; align-items: center; gap: 7px; height: 36px; padding: 0 13px; border-radius: 10px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--amo-fleet-line2);
  transition: background .15s, scale .3s var(--amo-fleet-spring);
  &:hover { background: var(--amo-fleet-hover); }
  &:active { scale: .97; }
  &.pri { background: var(--amo-fleet-ink); color: var(--amo-fleet-paper); box-shadow: none; }
  &.pri:hover { background: color-mix(in oklch, var(--amo-fleet-ink), var(--amo-fleet-accent) 35%); }
}
.amo-fleet .amo-fleet-due {
  --sc: var(--amo-fleet-accent);
  display: grid; gap: 12px; padding: 16px; border-radius: 16px; background: color-mix(in oklch, var(--sc) 7%, var(--amo-fleet-card)); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--sc) 22%, transparent);
  &.st-soon { --sc: var(--amo-fleet-soon); } &.st-over { --sc: var(--amo-fleet-over); } &.st-shop { --sc: var(--amo-fleet-shop); }
  & .top { display: grid; gap: 3px; }
  & h2 { font-size: clamp(20px, 2.4cqi, 26px); font-weight: 800; letter-spacing: -.04em; line-height: 1.1; color: color-mix(in oklch, var(--sc), var(--amo-fleet-ink) 45%); text-wrap: balance; }
  & p { color: var(--amo-fleet-mute); text-wrap: pretty; } & p b { color: var(--amo-fleet-ink); }
}
.amo-fleet .amo-fleet-meter {
  display: grid; grid-template-columns: minmax(0, 1fr); gap: 5px;
  & .l { display: flex; align-items: baseline; gap: 8px; font-size: 12px; color: var(--amo-fleet-mute); font-variant-numeric: tabular-nums; }
  & .l b { color: var(--amo-fleet-ink); font-weight: 700; }
  & .l em { font-style: normal; font-size: 10px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; padding: 1px 6px; border-radius: 99px; background: var(--sc); color: white; }
  & .l span { margin-left: auto; }
  & > i { position: relative; display: block; height: 10px; border-radius: 5px; background: color-mix(in oklch, var(--amo-fleet-ink) 8%, transparent); overflow: hidden; }
  & > i s { position: absolute; inset: 0 auto 0 0; width: var(--p); border-radius: inherit; background: color-mix(in oklch, var(--sc) 45%, var(--amo-fleet-card)); transform-origin: left; animation: amo-fleet-fill .9s var(--amo-fleet-ease) backwards; }
  &.first > i s { background: var(--sc); }
  &.over > i s { background: repeating-linear-gradient(-45deg, var(--amo-fleet-over) 0 6px, color-mix(in oklch, var(--amo-fleet-over), white 25%) 6px 12px); }
  & .r { font-size: 11.5px; color: var(--amo-fleet-mute); font-variant-numeric: tabular-nums; text-align: right; }
}
@keyframes amo-fleet-fill { from { scale: 0 1; } }
.amo-fleet .amo-fleet-detail h3 { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; font-size: 10.5px; font-weight: 750; letter-spacing: .09em; text-transform: uppercase; color: var(--amo-fleet-faint); margin-bottom: 8px; & span { font-weight: 600; letter-spacing: 0; text-transform: none; font-size: 12px; color: var(--amo-fleet-mute); font-variant-numeric: tabular-nums; } }
.amo-fleet .amo-fleet-defects {
  & ul { display: grid; gap: 6px; }
  & li { display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; gap: 10px; align-items: center; padding: 9px 10px; border-radius: 12px; background: var(--amo-fleet-card); box-shadow: inset 0 0 0 1px var(--amo-fleet-line); }
  & li > svg { color: var(--amo-fleet-soon); }
  & li.major > svg { color: var(--amo-fleet-over); }
  & li.done > svg { color: var(--amo-fleet-accent); }
  & li.done b { text-decoration: line-through; color: var(--amo-fleet-mute); }
  & b { display: block; font-weight: 650; }
  & small { font-size: 11.5px; color: var(--amo-fleet-mute); }
  & li button { padding: 5px 10px; border-radius: 8px; font-size: 12px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--amo-fleet-line2); }
  & li button:hover { background: var(--amo-fleet-hover); }
  & .none { display: flex; align-items: center; gap: 6px; color: var(--amo-fleet-mute); }
  & .none svg { color: var(--amo-fleet-accent); }
}
.amo-fleet .amo-fleet-hist {
  & ol { position: relative; display: grid; gap: 2px; }
  & ol::before { content: ""; position: absolute; left: 14px; top: 8px; bottom: 8px; width: 2px; background: var(--amo-fleet-line); }
  & li { position: relative; display: grid; grid-template-columns: 30px minmax(0, 1fr) 28px; gap: 10px; align-items: start; padding: 6px 0; animation: amo-fleet-in .4s var(--amo-fleet-ease) backwards; animation-delay: calc(var(--i) * 35ms); }
  & .dot { position: relative; display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; background: var(--amo-fleet-paper); color: var(--c); box-shadow: inset 0 0 0 2px var(--c); }
  & .dot svg { width: 15px; height: 15px; }
  & .t { display: flex; justify-content: space-between; gap: 8px; }
  & .t b { font-weight: 700; }
  & .amt { font-weight: 720; font-variant-numeric: tabular-nums; }
  & small { display: block; font-size: 11.5px; color: var(--amo-fleet-mute); font-variant-numeric: tabular-nums; }
  & p { margin-top: 2px; font-size: 12px; color: var(--amo-fleet-mute); text-wrap: pretty; }
  & .rm { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; color: var(--amo-fleet-faint); opacity: 0; transition: opacity .15s, background .15s; }
  & li:hover .rm, & .rm:focus-visible { opacity: 1; }
  & .rm:hover { background: color-mix(in oklch, var(--amo-fleet-over) 10%, transparent); color: var(--amo-fleet-over); }
}
/* the log sheet */
.amo-fleet .amo-fleet-sheet {
  position: sticky; bottom: -24px; z-index: 5; margin: 0 -20px -24px; padding: 0 12px 12px;
  transition: translate .45s var(--amo-fleet-ease), opacity .3s; @starting-style { translate: 0 30px; opacity: 0; }
  & form { display: grid; gap: 12px; padding: 14px; border-radius: 16px; background: var(--amo-fleet-card); box-shadow: 0 0 0 1px var(--amo-fleet-line2), 0 -20px 50px -20px color-mix(in oklch, var(--amo-fleet-ink) 45%, transparent); }
  & header { display: flex; justify-content: space-between; align-items: center; }
  & header b { font-size: 14.5px; font-weight: 750; }
  & .x { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; } & .x:hover { background: var(--amo-fleet-hover); }
  & .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); gap: 10px; }
  & label { display: grid; gap: 4px; font-size: 11.5px; font-weight: 600; color: var(--amo-fleet-mute); }
  & label em { font-style: normal; font-size: 11px; font-weight: 500; color: var(--amo-fleet-faint); min-height: 1em; }
  & label.bad em { color: var(--amo-fleet-over); font-weight: 600; }
  & input, & select { height: 34px; padding: 0 9px; border-radius: 8px; border: 0; background: var(--amo-fleet-paper); box-shadow: inset 0 0 0 1px var(--amo-fleet-line2); outline: none; min-width: 0; font-variant-numeric: tabular-nums; }
  & input:focus, & select:focus { box-shadow: inset 0 0 0 2px var(--amo-fleet-accent); }
  & [aria-invalid="true"] { box-shadow: inset 0 0 0 2px var(--amo-fleet-over); }
  & .parts { display: grid; gap: 6px; }
  & .part { display: grid; grid-template-columns: minmax(0, 1fr) 56px 84px 30px; gap: 6px; }
  & .part button { display: grid; place-items: center; border-radius: 8px; color: var(--amo-fleet-faint); } & .part button:hover:not(:disabled) { background: var(--amo-fleet-hover); color: var(--amo-fleet-over); }
  & .add { justify-self: start; display: inline-flex; align-items: center; gap: 5px; padding: 5px 8px; border-radius: 8px; font-size: 12px; font-weight: 650; color: var(--amo-fleet-accent); } & .add:hover { background: var(--amo-fleet-hover); }
  & footer { display: flex; align-items: center; gap: 12px; padding-top: 10px; border-top: 1px dashed var(--amo-fleet-line2); }
  & footer span { font-size: 12.5px; color: var(--amo-fleet-mute); } & footer b { color: var(--amo-fleet-ink); font-size: 16px; font-variant-numeric: tabular-nums; }
  & footer small { font-size: 11.5px; color: var(--amo-fleet-accent); }
  & footer .amo-fleet-btn { margin-left: auto; }
}

/* ── costs ────────────────────────────────────────── */
.amo-fleet .amo-fleet-costs { grid-area: costs; min-height: 0; overflow-y: auto; scrollbar-width: thin; display: grid; align-content: start; gap: 14px; padding: 16px 16px 20px; border-left: 1px solid var(--amo-fleet-line); background: var(--amo-fleet-card); }
.amo-fleet .amo-fleet-chead { display: grid; gap: 2px; & h2 { font: 800 clamp(26px, 2.8cqi, 32px)/1.1 ui-monospace, Menlo, monospace; letter-spacing: -.05em; } & p { font-size: 12px; color: var(--amo-fleet-mute); font-variant-numeric: tabular-nums; } }
.amo-fleet .amo-fleet-chart {
  position: relative; height: 190px; padding-left: 44px;
  & .grid span { position: absolute; left: 0; right: 0; bottom: calc(var(--f) * (100% - 26px) + 22px); translate: 0 50%; display: flex; align-items: center; gap: 6px; font: 600 10px/1 ui-monospace, Menlo, monospace; color: var(--amo-fleet-faint); font-variant-numeric: tabular-nums; }
  & .grid span::after { content: ""; flex: 1; height: 1px; background: var(--amo-fleet-line); }
  & .bars { position: relative; height: 100%; display: grid; grid-template-columns: repeat(6, 1fr); gap: 8px; }
  & .col { position: relative; display: flex; flex-direction: column; justify-content: flex-end; align-items: stretch; gap: 6px; padding-top: 4px; border-radius: 8px 8px 0 0; outline-offset: 2px; }
  & .stack { display: flex; flex-direction: column-reverse; gap: 1.5px; height: calc((100% - 26px) * var(--hf)); min-height: 0; border-radius: 5px 5px 2px 2px; overflow: hidden; transform-origin: bottom; animation: amo-fleet-grow .7s var(--amo-fleet-ease) backwards; animation-delay: calc(var(--i) * 60ms); transition: filter .2s, opacity .2s; }
  & .stack i { display: block; min-height: 2px; background: var(--c); }
  & .col b { height: 16px; font-size: 11px; font-weight: 650; color: var(--amo-fleet-mute); text-align: center; }
  & .col:hover .stack { filter: brightness(1.08); }
  & .col[aria-pressed="false"] .stack { opacity: .55; }
  & .col[aria-pressed="true"] b { color: var(--amo-fleet-ink); font-weight: 800; }
  & .col[aria-pressed="true"]::after { content: ""; position: absolute; left: 50%; bottom: 0; width: 18px; height: 3px; translate: -50% 0; border-radius: 2px; background: var(--amo-fleet-ink); }
}
@keyframes amo-fleet-grow { from { scale: 1 0; } }
.amo-fleet .amo-fleet-legend { display: flex; flex-wrap: wrap; gap: 4px 12px; font-size: 11.5px; color: var(--amo-fleet-mute); & span { display: inline-flex; align-items: center; gap: 5px; } & i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); } }
.amo-fleet .amo-fleet-month {
  display: grid; gap: 8px;
  & h3 { display: flex; justify-content: space-between; font-size: 10.5px; font-weight: 750; letter-spacing: .09em; text-transform: uppercase; color: var(--amo-fleet-faint); }
  & h3 span { letter-spacing: 0; text-transform: none; font-weight: 600; font-size: 12px; }
  & table { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums; }
  & th { text-align: left; font-weight: 500; color: var(--amo-fleet-mute); padding: 5px 0; display: flex; align-items: center; gap: 7px; }
  & th i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); }
  & td { text-align: right; padding: 5px 0; }
  & tbody tr { border-bottom: 1px solid var(--amo-fleet-line); }
  & tfoot th, & tfoot td { font-weight: 800; color: var(--amo-fleet-ink); padding-top: 8px; }
  & ul { display: grid; gap: 2px; }
  & li button { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 8px; align-items: center; width: 100%; padding: 6px 4px; border-radius: 8px; text-align: left; font-size: 12px; }
  & li button:hover { background: var(--amo-fleet-hover); }
  & li span:not(.plate) { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: var(--amo-fleet-mute); }
  & li b { font-variant-numeric: tabular-nums; }
  & .none { color: var(--amo-fleet-mute); font-size: 12px; }
}

/* toast */
.amo-fleet .amo-fleet-toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 9; translate: -50% 0; display: flex; align-items: center; gap: 12px; max-width: calc(100% - 32px); padding: 10px 10px 10px 16px; border-radius: 12px;
  background: var(--amo-fleet-ink); color: var(--amo-fleet-paper); font-weight: 550; box-shadow: 0 16px 36px -12px color-mix(in oklch, var(--amo-fleet-ink) 55%, transparent);
  transition: opacity .25s, translate .45s var(--amo-fleet-spring); @starting-style { opacity: 0; translate: -50% 12px; }
  & button { padding: 4px 9px; border-radius: 7px; font-weight: 750; color: color-mix(in oklch, var(--amo-fleet-accent), white 45%); }
  & button:hover { background: color-mix(in oklch, var(--amo-fleet-paper) 12%, transparent); }
}

/* ── responsive ───────────────────────────────────── */
@container (max-width: 1099px) {
  .amo-fleet .amo-fleet-tabs {
    display: flex; gap: 4px; padding: 8px 10px; border-bottom: 1px solid var(--amo-fleet-line);
    & button { flex: 1; height: 34px; border-radius: 9px; font-weight: 650; color: var(--amo-fleet-mute); }
    & button[aria-selected="true"] { background: var(--amo-fleet-ink); color: var(--amo-fleet-paper); }
    & [data-view="list"] { display: none; }
  }
  .amo-fleet .amo-fleet-app { grid-template-columns: 270px minmax(0, 1fr); grid-template-areas: "list main"; }
  .amo-fleet .amo-fleet-detail, .amo-fleet .amo-fleet-costs { grid-area: main; border: 0; }
  .amo-fleet[data-view="costs"] .amo-fleet-detail { display: none; }
  .amo-fleet:not([data-view="costs"]) .amo-fleet-costs { display: none; }
  .amo-fleet .amo-fleet-costs { background: none; }
}
@container (max-width: 759px) {
  .amo-fleet .amo-fleet-tabs [data-view="list"] { display: block; }
  .amo-fleet .amo-fleet-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "main"; }
  .amo-fleet .amo-fleet-list { grid-area: main; border: 0; }
  .amo-fleet:not([data-view="list"]) .amo-fleet-list { display: none; }
  .amo-fleet[data-view="list"] .amo-fleet-detail { display: none; }
  .amo-fleet .amo-fleet-back { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 9px; background: var(--amo-fleet-well); }
  .amo-fleet .amo-fleet-detail { padding: 12px 14px 20px; }
  .amo-fleet .amo-fleet-sheet { margin: 0 -14px -20px; bottom: -20px; padding: 0 6px 6px; }
  .amo-fleet .amo-fleet-sheet .part { grid-template-columns: minmax(0, 1fr) 46px 70px 28px; }
}
@container (max-width: 420px) {
  .amo-fleet .amo-fleet-odo i { width: 15px; height: 24px; font-size: 14px; }
  .amo-fleet .amo-fleet-vhead .id { flex-wrap: wrap; }
}

@media (prefers-reduced-motion: reduce) {
  .amo-fleet {
    & *, & *::before, & *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
  }
}

