/* ── Odo · fleet maintenance log ───────────────────────────────────────────
   Each vehicle has a service interval in kilometres and months, whichever
   comes first. The kilometre side is projected into a date using the
   vehicle's own average since its last service (km driven ÷ days elapsed),
   so the list status, both meters, the due date and the "due first" badge
   all come from the same arithmetic. Logging work recomputes everything:
   a service resets the interval, the cost lands in its month on the chart,
   and the month breakdown always sums to the bar. Every log and removal can
   be undone. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const gbp = p => '£' + (p / 100).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const gbp0 = p => '£' + Math.round(p / 100).toLocaleString('en-GB');
const km = n => Math.round(n).toLocaleString('en-GB');
const ico = p => '<svg viewBox="0 0 24 24" aria-hidden="true">' + p + '</svg>';
const I = {
  van: '<path d="M3 16.5V7.5h11v9M14 10h4l3 3.5v3h-7"/><circle cx="7" cy="17" r="1.8"/><circle cx="17" cy="17" r="1.8"/>',
  truck: '<path d="M2.5 16.5V6h12v10.5M14.5 9.5H18l3.5 4v3h-7"/><circle cx="6.5" cy="17" r="1.8"/><circle cx="11" cy="17" r="1.8"/><circle cx="18" cy="17" r="1.8"/>',
  ev: '<path d="M3 16.5V7.5h11v9M14 10h4l3 3.5v3h-7"/><circle cx="7" cy="17" r="1.8"/><circle cx="17" cy="17" r="1.8"/><path d="m9 8.5-1.6 2.8h2.4L8.3 14" stroke-width="1.4"/>',
  bike: '<circle cx="6" cy="16.5" r="3.5"/><circle cx="18" cy="16.5" r="3.5"/><path d="M6 16.5 9.5 9h6L18 16.5M9.5 9 12 16.5h2.5M8 6h3"/>',
  wrench: '<path d="M14.5 6.5a4 4 0 0 0 5 5L12 19a2.1 2.1 0 0 1-3-3Z"/><path d="M14.5 6.5 17 4l3 3-2.5 2.5"/>',
  tyre: '<circle cx="12" cy="12" r="8.5"/><circle cx="12" cy="12" r="3.5"/><path d="M12 3.5v5M12 15.5v5M3.5 12h5M15.5 12h5"/>',
  brake: '<circle cx="12" cy="12" r="8.5"/><path d="M7 7.5a7 7 0 0 0 0 9"/><circle cx="12" cy="12" r="2"/>',
  check: '<path d="m5 12.5 4.5 4.5L19 7.5"/>',
  clip: '<rect x="5" y="4.5" width="14" height="16" rx="2"/><path d="M9 4.5V3h6v1.5M8.5 10h7M8.5 14h5"/>',
