  back: '<path d="M15 6 9 12l6 6"/>',
};
const DAY = 864e5, D = s => Math.round(Date.UTC(+s.slice(0, 4), +s.slice(5, 7) - 1, +s.slice(8, 10)) / DAY);
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const TODAY = D('2026-10-02');
const ymd = n => { const t = new Date(n * DAY); return [t.getUTCFullYear(), t.getUTCMonth(), t.getUTCDate()]; };
const fmtD = n => { const [y, m, d] = ymd(n); return d + ' ' + MON[m] + ' ' + y; };
const iso = n => { const [y, m, d] = ymd(n); return y + '-' + String(m + 1).padStart(2, '0') + '-' + String(d).padStart(2, '0'); };
const addMo = (n, mo) => { const [y, m, d] = ymd(n); return Math.round(Date.UTC(y, m + mo, d) / DAY); };

/* ── data ────────────────────────────────────────────────────────────── */
const CATS = { service: 'Service', tyres: 'Tyres', repair: 'Repairs', inspect: 'Inspection' };
const TYPES = [['Full service', 'service'], ['Interim service', 'service'], ['Tyres', 'tyres'], ['Brakes', 'repair'], ['Repair', 'repair'], ['Inspection', 'inspect']];
