  { id: 'v1', plate: 'HV21 KRT', model: 'Ferro Transit 2.0', kind: 'van', odo: 84320, iv: [20000, 12], last: [70100, '2026-03-12'], driver: 'Ahmed Siddiqui', mot: '2027-03-30' },
