  { id: 'v9', plate: 'GN19 VCE', model: 'Ferro Transit 2.0', kind: 'van', odo: 152400, iv: [20000, 12], last: [139000, '2026-06-15'], driver: 'Priya Natarajan', mot: '2027-06-08' },
