].map(v => ({ ...v, last: { odo: v.last[0], d: D(v.last[1]) }, defects: (v.defects || []).map(([t, sev, at], i) => ({ id: v.id + 'd' + i, t, sev, at, done: false })), shop: v.shop ? { where: v.shop[0], d: D(v.shop[1]) } : null }));
VEH.forEach(v => { v.avg = (v.odo - v.last.odo) / Math.max(1, TODAY - v.last.d); });
const VB = Object.fromEntries(VEH.map(v => [v.id, v]));
