/* ── maths: whichever comes first ────────────────────────────────────── */
function due(v) {
  /* km a day since the last service; right after a service, fall back to the average it had before */
  const used = v.odo - v.last.odo, kmLeft = v.iv[0] - used, since = TODAY - v.last.d, perDay = since >= 14 ? used / since : v.avg;
  const tDue = addMo(v.last.d, v.iv[1]), daysT = tDue - TODAY, daysK = perDay > 0 ? kmLeft / perDay : Infinity;
  const kmFirst = daysK < daysT, days = Math.min(daysT, daysK), when = TODAY + Math.floor(days);
  const st = v.shop ? 'shop' : (kmLeft < 0 || daysT < 0) ? 'over' : (days <= 30 || kmLeft <= 1500) ? 'soon' : 'ok';
  return { used, kmLeft, since, perDay, tDue, daysT, daysK, kmFirst, days, when, st, ivDays: tDue - v.last.d };
}
const STN = { ok: 'OK', soon: 'Due soon', over: 'Overdue', shop: 'In workshop' };

/* ── state ───────────────────────────────────────────────────────────── */
const S = { sel: 'v2', q: '', filter: 'all', view: 'detail', month: 8, form: null, undo: null, errs: {} };
const MONTHS = [4, 5, 6, 7, 8, 9];   /* May–Oct 2026 */

/* ── list ────────────────────────────────────────────────────────────── */
function renderList() {
  const F = [['all', 'All'], ['over', 'Overdue'], ['soon', 'Due soon'], ['shop', 'Workshop'], ['ok', 'OK']];
  $('[data-chips]').innerHTML = F.map(([k, t]) => { const n = VEH.filter(v => k === 'all' || due(v).st === k).length; return '<button type="button" role="radio" data-filter="' + k + '" aria-checked="' + (S.filter === k) + '" class="f-' + k + '">' + t + '<span>' + n + '</span></button>'; }).join('');
  const q = S.q.trim().toLowerCase();
  const order = { over: 0, soon: 1, shop: 2, ok: 3 };
  const L = VEH.filter(v => (S.filter === 'all' || due(v).st === S.filter) && (!q || (v.plate + ' ' + v.model + ' ' + v.driver).toLowerCase().includes(q))).sort((a, b) => order[due(a).st] - order[due(b).st] || due(a).days - due(b).days);
  $('[data-rows]').innerHTML = L.length ? L.map((v, i) => {
    const u = due(v), pct = Math.min(100, Math.max(u.used / v.iv[0], (TODAY - v.last.d) / u.ivDays) * 100);
    return '<div class="amo-fleet-row st-' + u.st + '" role="option" data-v="' + v.id + '" aria-selected="' + (S.sel === v.id) + '" tabindex="' + (S.sel === v.id ? 0 : -1) + '" style="--i:' + i + ';--p:' + pct.toFixed(1) + '%">' +
      '<span class="ic">' + ico(I[v.kind]) + '</span><span class="tx"><b>' + v.plate + '</b><small>' + esc(v.model) + '</small></span>' +
      '<span class="st"><em>' + STN[u.st] + '</em><small>' + dueShort(v, u) + '</small></span><i class="bar"></i></div>';
  }).join('') : '<p class="amo-fleet-none">No vehicles match “' + esc(S.q) + '”.</p>';
}
function dueShort(v, u) {
  if (u.st === 'shop') return 'booked ' + fmtD(v.shop.d).replace(/ \d{4}$/, '');
  if (u.kmLeft < 0) return km(-u.kmLeft) + ' km over';
  if (u.daysT < 0) return -u.daysT + ' days over';
  return u.days < 1 ? 'today' : 'in ' + Math.floor(u.days) + ' days';
}

/* ── detail ──────────────────────────────────────────────────────────── */
function odoDrum(n) { return '<span class="amo-fleet-odo" aria-label="' + km(n) + ' kilometres">' + String(Math.round(n)).padStart(6, '0').split('').map((d, i) => '<i style="--i:' + i + '">' + d + '</i>').join('') + '<b>km</b></span>'; }
function renderDetail() {
  const v = VB[S.sel], box = $('[data-detail]');
  if (!v) { box.innerHTML = '<p class="amo-fleet-none">Choose a vehicle.</p>'; return; }
  const u = due(v), hist = H.filter(e => e.v === v.id).sort((a, b) => b.d - a.d || b.odo - a.odo);
  const kmPct = u.used / v.iv[0] * 100, tPct = (TODAY - v.last.d) / u.ivDays * 100;
  const head = u.kmLeft < 0 ? 'Overdue by ' + km(-u.kmLeft) + ' km' : u.daysT < 0 ? 'Overdue by ' + -u.daysT + ' days' : 'Service due in ' + Math.floor(u.days) + ' days';
  let h = '<header class="amo-fleet-vhead"><button type="button" class="amo-fleet-back" data-act="back" aria-label="Back to vehicles">' + ico(I.back) + '</button>' +
    '<div class="id"><span class="plate">' + v.plate + '</span><span><b>' + esc(v.model) + '</b><small>' + esc(v.driver) + (v.mot ? ' · annual test ' + fmtD(D(v.mot)) : '') + '</small></span></div>' + odoDrum(v.odo) + '</header>';
  h += '<div class="amo-fleet-actions"><button type="button" class="amo-fleet-btn pri" data-act="log">' + ico(I.plus) + 'Log work<kbd>N</kbd></button>' +
    (v.shop ? '<button type="button" class="amo-fleet-btn" data-act="unbook">' + ico(I.cal) + 'Cancel booking · ' + esc(v.shop.where) + '</button>' : '<button type="button" class="amo-fleet-btn" data-act="book">' + ico(I.cal) + 'Book into workshop</button>') + '</div>';
  /* the two intervals; the one that ends first carries the date */
  h += '<section class="amo-fleet-due st-' + u.st + '"><div class="top"><span class="k">' + (v.first ? 'First service' : 'Next service') + ' · every ' + km(v.iv[0]) + ' km or ' + v.iv[1] + ' months</span><h2>' + head + '</h2>' +
    '<p>' + (u.kmLeft < 0 || u.daysT < 0 ? 'Book it in now — the interval has passed.' : (u.kmFirst ? 'Around <b>' + fmtD(u.when) + '</b> by distance, at ' + Math.round(u.perDay) + ' km a day since the last service.' : 'On <b>' + fmtD(u.tDue) + '</b> by date — distance won’t run out until about ' + fmtD(TODAY + Math.floor(u.daysK)) + '.')) + '</p></div>' +
    meter('Distance', u.kmFirst, kmPct, km(u.used) + ' of ' + km(v.iv[0]) + ' km', u.kmLeft >= 0 ? km(u.kmLeft) + ' km left' : km(-u.kmLeft) + ' km over') +
    meter('Time', !u.kmFirst, tPct, (TODAY - v.last.d) + ' of ' + u.ivDays + ' days', u.daysT >= 0 ? u.daysT + ' days left · ' + fmtD(u.tDue) : -u.daysT + ' days over') + '</section>';
  const open = v.defects.filter(d => !d.done), closed = v.defects.filter(d => d.done);
  h += '<section class="amo-fleet-defects"><h3>Driver-reported defects <span>' + open.length + ' open</span></h3>' + (v.defects.length ? '<ul>' + open.concat(closed).map(d => '<li class="' + d.sev + (d.done ? ' done' : '') + '">' + ico(d.done ? I.check : I.warn) + '<span><b>' + esc(d.t) + '</b><small>' + (d.done ? 'Resolved ' + esc(d.done) : (d.sev === 'major' ? 'Off-road until fixed' : 'Minor') + ' · reported ' + esc(d.at)) + '</small></span><button type="button" data-defect="' + d.id + '" aria-pressed="' + !!d.done + '">' + (d.done ? 'Reopen' : 'Resolve') + '</button></li>').join('') + '</ul>' : '<p class="none">' + ico(I.check) + 'Nothing reported.</p>') + '</section>';
  h += '<section class="amo-fleet-hist"><h3>History <span>' + hist.length + ' entries · ' + gbp(hist.reduce((n, e) => n + total(e), 0)) + '</span></h3><ol data-hist>' + hist.map((e, i) => {
    const c = TCAT[e.type];
    return '<li class="c-' + c + '" data-e="' + e.id + '" style="--i:' + i + '"><span class="dot">' + ico(c === 'tyres' ? I.tyre : c === 'repair' ? (e.type === 'Brakes' ? I.brake : I.wrench) : c === 'inspect' ? I.clip : I.wrench) + '</span>' +
      '<div class="b"><div class="t"><b>' + esc(e.type) + '</b><span class="amt">' + gbp(total(e)) + '</span></div><small>' + fmtD(e.d) + ' · ' + km(e.odo) + ' km · ' + esc(e.shop) + '</small>' +
      (e.parts.length ? '<p>' + e.parts.map(p => esc((p.qty > 1 ? p.qty + ' × ' : '') + p.desc)).join(' · ') + '</p>' : '') + '</div>' +
      '<button type="button" class="rm" data-rm="' + e.id + '" aria-label="Remove ' + esc(e.type) + ' on ' + fmtD(e.d) + '" title="Remove entry">' + ico(I.trash) + '</button></li>';
  }).join('') + '</ol></section>';
  box.innerHTML = h + (S.form ? formHTML(v) : '');
}
function meter(name, first, pct, a, b) {
  const over = pct > 100;
  return '<div class="amo-fleet-meter' + (first ? ' first' : '') + (over ? ' over' : '') + '" style="--p:' + Math.min(100, Math.max(0, pct)).toFixed(1) + '%"><div class="l"><b>' + name + '</b>' + (first ? '<em>due first</em>' : '') + '<span>' + a + '</span></div><i><s></s></i><div class="r">' + b + '</div></div>';
}

/* ── log form (a sheet inside the detail pane) ───────────────────────── */
function lastOdo(v) { return Math.max(...H.filter(e => e.v === v.id).map(e => e.odo), v.last.odo); }
function formHTML(v) {
  const F = S.form, E = S.errs, sum = (+F.labour || 0) * 100 + F.parts.reduce((n, p) => n + (+p.qty || 0) * Math.round((+p.unit || 0) * 100), 0);
  return '<div class="amo-fleet-sheet" role="dialog" aria-modal="false" aria-label="Log work for ' + v.plate + '"><form data-form novalidate>' +
    '<header><b>Log work · ' + v.plate + '</b><button type="button" class="x" data-act="cancel" aria-label="Close (Esc)">' + ico(I.x) + '</button></header>' +
    '<div class="grid">' +
    '<label><span>Type</span><select data-f="type">' + TYPES.map(([t]) => '<option' + (F.type === t ? ' selected' : '') + '>' + t + '</option>').join('') + '</select></label>' +
    '<label><span>Workshop</span><select data-f="shop">' + SHOPS.map(t => '<option' + (F.shop === t ? ' selected' : '') + '>' + t + '</option>').join('') + '</select></label>' +
    '<label class="' + (E.d ? 'bad' : '') + '"><span>Date</span><input type="date" data-f="d" value="' + F.d + '" max="' + iso(TODAY) + '"' + (E.d ? ' aria-invalid="true"' : '') + '><em>' + esc(E.d || '') + '</em></label>' +
    '<label class="' + (E.odo ? 'bad' : '') + '"><span>Odometer (km)</span><input type="number" inputmode="numeric" data-f="odo" value="' + esc(F.odo) + '" min="' + lastOdo(v) + '"' + (E.odo ? ' aria-invalid="true"' : '') + '><em>' + esc(E.odo || 'Last reading ' + km(lastOdo(v)) + ' km') + '</em></label>' +
    '<label class="' + (E.cost ? 'bad' : '') + '"><span>Labour (£)</span><input type="number" step="0.01" min="0" data-f="labour" value="' + esc(F.labour) + '"><em>' + esc(E.cost || '') + '</em></label>' +
    '</div><div class="parts"><span class="k">Parts</span>' + F.parts.map((p, i) => '<div class="part"><input type="text" data-p="desc" data-i="' + i + '" placeholder="Part" value="' + esc(p.desc) + '" aria-label="Part ' + (i + 1) + '"><input type="number" min="1" data-p="qty" data-i="' + i + '" value="' + esc(p.qty) + '" aria-label="Quantity"><input type="number" step="0.01" min="0" data-p="unit" data-i="' + i + '" value="' + esc(p.unit) + '" placeholder="£ each" aria-label="Unit price"><button type="button" data-delpart="' + i + '" aria-label="Remove part ' + (i + 1) + '"' + (F.parts.length < 2 ? ' disabled title="Keep at least one row"' : '') + '>' + ico(I.x) + '</button></div>').join('') +
    '<button type="button" class="add" data-act="addpart">' + ico(I.plus) + 'Add part</button></div>' +
    '<footer><span>Total <b data-sum>' + gbp(sum) + '</b></span>' + (TCAT[F.type] === 'service' ? '<small>Resets the service interval</small>' : '') + '<button type="submit" class="amo-fleet-btn pri">Save entry</button></footer></form></div>';
}
function openForm() {
  const v = VB[S.sel];
  S.form = { type: 'Full service', shop: SHOPS[0], d: iso(TODAY), odo: String(v.odo), labour: '', parts: [{ desc: '', qty: '1', unit: '' }] }; S.errs = {};
  renderDetail(); $('[data-f=type]')?.focus();
}
function saveForm() {
  const v = VB[S.sel], F = S.form, E = {};
  const dn = F.d ? D(F.d) : NaN, odo = Math.round(+F.odo), sum = Math.round((+F.labour || 0) * 100) + F.parts.reduce((n, p) => n + (+p.qty || 0) * Math.round((+p.unit || 0) * 100), 0);
  if (!F.d || isNaN(dn)) E.d = 'Pick a date'; else if (dn > TODAY) E.d = 'Can’t be in the future';
  if (!F.odo || isNaN(odo)) E.odo = 'Enter the reading'; else if (odo < lastOdo(v)) E.odo = 'Lower than the last reading (' + km(lastOdo(v)) + ' km)';
  if (sum <= 0) E.cost = 'Add labour or at least one priced part';
  S.errs = E;
  if (Object.keys(E).length) { renderDetail(); $('.amo-fleet-sheet [aria-invalid="true"]')?.focus(); toast('Check the highlighted fields'); return; }
  const before = { last: { ...v.last }, odo: v.odo };
  const e = { id: 'e' + (++EID), v: v.id, d: dn, type: F.type, odo, shop: F.shop, labour: Math.round((+F.labour || 0) * 100), parts: F.parts.filter(p => p.desc.trim() && +p.unit > 0).map(p => ({ desc: p.desc.trim(), qty: Math.max(1, Math.round(+p.qty || 1)), unit: Math.round(+p.unit * 100) })) };
  H.push(e);
  if (odo > v.odo) v.odo = odo;
  if (TCAT[e.type] === 'service' && (dn >= v.last.d)) { v.last = { odo, d: dn }; v.first = 0; if (v.shop) v.shop = null; }
  S.form = null; S.errs = {};
  const m = ymd(dn); if (m[0] === 2026 && MONTHS.includes(m[1])) S.month = m[1];
  S.undo = () => { H.splice(H.indexOf(e), 1); v.last = before.last; v.odo = before.odo; render(); };
  render(true);
  toast(e.type + ' logged · ' + gbp(total(e)), true);
}

/* ── fleet costs ─────────────────────────────────────────────────────── */
function monthTotals() {
  return MONTHS.map(m => {
    const es = H.filter(e => { const [y, mm] = ymd(e.d); return y === 2026 && mm === m; }), c = {};
    Object.keys(CATS).forEach(k => c[k] = es.filter(e => TCAT[e.type] === k).reduce((n, e) => n + total(e), 0));
    return { m, c, sum: Object.values(c).reduce((a, b) => a + b, 0), es };
  });
}
function renderCosts() {
  const T = monthTotals(), max = Math.max(...T.map(t => t.sum), 1), top = Math.ceil(max / 50000) * 50000, all = T.reduce((n, t) => n + t.sum, 0);
  const sel = T.find(t => t.m === S.month) || T[T.length - 1];
  const sts = VEH.map(v => due(v).st);
  let h = '<header class="amo-fleet-chead"><span class="k">Maintenance spend · May–Oct 2026</span><h2>' + gbp0(all) + '</h2><p>' + gbp0(all / VEH.length) + ' per vehicle · ' + sts.filter(s => s === 'over').length + ' overdue · ' + sts.filter(s => s === 'soon').length + ' due soon</p></header>';
  h += '<div class="amo-fleet-chart" style="--top:' + top + '"><div class="grid" aria-hidden="true">' + [1, .5, 0].map(f => '<span style="--f:' + f + '">' + gbp0(top * f) + '</span>').join('') + '</div><div class="bars">' +
    T.map((t, i) => '<button type="button" class="col" data-month="' + t.m + '" aria-pressed="' + (t.m === sel.m) + '" aria-label="' + MON[t.m] + ': ' + gbp(t.sum) + '" style="--i:' + i + '"><span class="stack" style="--hf:' + (t.sum / top).toFixed(4) + '">' +
      Object.keys(CATS).map(k => t.c[k] ? '<i class="c-' + k + '" style="flex-grow:' + t.c[k] + '"></i>' : '').join('') + '</span><b>' + MON[t.m] + '</b></button>').join('') + '</div></div>';
  h += '<div class="amo-fleet-legend">' + Object.entries(CATS).map(([k, n]) => '<span><i class="c-' + k + '"></i>' + n + '</span>').join('') + '</div>';
  h += '<section class="amo-fleet-month"><h3>' + MON[sel.m] + ' 2026 <span>' + sel.es.length + ' job' + (sel.es.length === 1 ? '' : 's') + '</span></h3><table><tbody>' +
    Object.entries(CATS).map(([k, n]) => '<tr><th><i class="c-' + k + '"></i>' + n + '</th><td>' + gbp(sel.c[k]) + '</td></tr>').join('') + '</tbody><tfoot><tr><th>Total</th><td>' + gbp(sel.sum) + '</td></tr></tfoot></table>' +
    (sel.es.length ? '<ul>' + sel.es.sort((a, b) => total(b) - total(a)).map(e => '<li><button type="button" data-goto="' + e.v + '"><span class="plate sm">' + VB[e.v].plate + '</span><span>' + esc(e.type) + '</span><b>' + gbp(total(e)) + '</b></button></li>').join('') + '</ul>' : '<p class="none">Nothing logged yet this month.</p>') + '</section>';
  $('[data-costs]').innerHTML = h;
}

/* ── render & flow ───────────────────────────────────────────────────── */
function render(newEntry) {
  renderList(); renderDetail(); renderCosts();
  root.dataset.view = S.view; $$('.amo-fleet-tabs [role=tab]').forEach(b => b.setAttribute('aria-selected', String(b.dataset.view === S.view)));
  if (newEntry && !RM.matches) $('[data-hist] li')?.animate([{ opacity: 0, transform: 'translateY(-8px)', background: 'color-mix(in oklch, currentColor 10%, transparent)' }, { opacity: 1, transform: 'none' }], { duration: 600, easing: 'cubic-bezier(.2,.8,.2,1)' });
}
function pick(id) {
  if (S.sel === id) { if (root.clientWidth < 760) { S.view = 'detail'; render(); } return; }
  S.sel = id; S.form = null; S.errs = {};
  if (root.clientWidth < 760) S.view = 'detail';
  render();
  if (!RM.matches) $$('.amo-fleet-odo i').forEach((el, i) => el.animate([{ transform: 'translateY(-60%)', opacity: 0 }, { transform: 'none', opacity: 1 }], { duration: 420, delay: i * 45, easing: 'linear(0, 0.14 6%, 0.47 13%, 0.82 21%, 1.02 29%, 1.05 36%, 1.03 45%, 1.005 58%, 1)', fill: 'backwards' }));
}
let toastT = 0;
function toast(msg, undo) {
  const t = $('[data-toast]');
  t.innerHTML = '<span>' + esc(msg) + '</span>' + (undo && S.undo ? '<button type="button" data-act="undo">Undo</button>' : '');
  t.hidden = false; clearTimeout(toastT); toastT = setTimeout(() => { if (root.isConnected) t.hidden = true; }, undo ? 5000 : 2800);
}

/* ── events ──────────────────────────────────────────────────────────── */
root.addEventListener('click', e => {
  const t = e.target;
  const tab = t.closest('.amo-fleet-tabs [role=tab]'); if (tab) { S.view = tab.dataset.view; render(); return; }
  const f = t.closest('[data-filter]'); if (f) { S.filter = f.dataset.filter; renderList(); return; }
  const row = t.closest('[data-v]'); if (row) { pick(row.dataset.v); return; }
  const mo = t.closest('[data-month]'); if (mo) { S.month = +mo.dataset.month; renderCosts(); $('[data-month="' + S.month + '"]')?.focus(); return; }
  const go = t.closest('[data-goto]'); if (go) { S.filter = 'all'; S.q = ''; $('[data-q]').value = ''; pick(go.dataset.goto); if (root.clientWidth < 1100) { S.view = 'detail'; render(); } return; }
  const df = t.closest('[data-defect]');
  if (df) { const v = VB[S.sel], d = v.defects.find(x => x.id === df.dataset.defect); d.done = d.done ? false : '2 Oct'; renderDetail(); renderList(); toast(d.done ? 'Defect resolved · ' + d.t : 'Defect reopened'); return; }
  const rm = t.closest('[data-rm]');
  if (rm) {
    const i = H.findIndex(x => x.id === rm.dataset.rm), ent = H[i], v = VB[ent.v], before = { last: { ...v.last } };
    H.splice(i, 1);
    /* removing the latest service rolls the interval back to the one before it */
    if (TCAT[ent.type] === 'service' && ent.d === v.last.d && ent.odo === v.last.odo) { const prev = H.filter(x => x.v === v.id && TCAT[x.type] === 'service').sort((a, b) => b.d - a.d)[0]; if (prev) v.last = { odo: prev.odo, d: prev.d }; }
    S.undo = () => { H.splice(i, 0, ent); v.last = before.last; render(); };
    render(); toast('Removed ' + ent.type + ' · ' + gbp(total(ent)), true); return;
  }
  const dp = t.closest('[data-delpart]'); if (dp && !dp.disabled) { S.form.parts.splice(+dp.dataset.delpart, 1); renderDetail(); return; }
  const b = t.closest('[data-act]'); if (!b || b.disabled) return;
  const a = b.dataset.act, v = VB[S.sel];
  if (a === 'log') openForm();
  else if (a === 'cancel') { S.form = null; S.errs = {}; renderDetail(); $('[data-act=log]')?.focus(); }
  else if (a === 'addpart') { S.form.parts.push({ desc: '', qty: '1', unit: '' }); renderDetail(); $$('[data-p=desc]').pop()?.focus(); }
  else if (a === 'book') { v.shop = { where: SHOPS[0], d: TODAY + 3 };   /* next working day: Mon 5 Oct */ render(); toast(v.plate + ' booked into ' + SHOPS[0] + ' on ' + fmtD(v.shop.d)); }
  else if (a === 'unbook') { const w = v.shop.where; v.shop = null; render(); toast('Booking at ' + w + ' cancelled'); }
  else if (a === 'back') { S.view = 'list'; render(); }
  else if (a === 'undo') { $('[data-toast]').hidden = true; if (S.undo) { const u = S.undo; S.undo = null; u(); toast('Undone'); } }
});
root.addEventListener('submit', e => { e.preventDefault(); if (S.form) saveForm(); });
root.addEventListener('input', e => {
  const t = e.target;
  if (t.matches('[data-q]')) { S.q = t.value; renderList(); return; }
  if (!S.form) return;
  if (t.dataset.f) S.form[t.dataset.f] = t.value;
  if (t.dataset.p) S.form.parts[+t.dataset.i][t.dataset.p] = t.value;
  const F = S.form, sum = Math.round((+F.labour || 0) * 100) + F.parts.reduce((n, p) => n + (+p.qty || 0) * Math.round((+p.unit || 0) * 100), 0), s = $('[data-sum]');
  if (s) s.textContent = gbp(sum);
});
root.addEventListener('change', e => { if (S.form && e.target.matches('select[data-f]')) { S.form[e.target.dataset.f] = e.target.value; const pos = e.target.dataset.f; renderDetail(); $('[data-f="' + pos + '"]')?.focus(); } });
root.addEventListener('keydown', e => {
  const t = e.target, typing = t.matches('input, select, textarea');
  if (e.key === 'Escape') { if (S.form) { S.form = null; renderDetail(); $('[data-act=log]')?.focus(); } else if (typing) t.blur(); return; }
  if (typing || e.metaKey || e.ctrlKey || e.altKey) return;
  const grp = t.closest && t.closest('[role=radiogroup], [role=listbox], .bars');
  if (grp && ['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)) {
